--
-- Name: case_activacao_bloqueios(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.case_activacao_bloqueios(_case uuid) RETURNS text[]
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT COALESCE(
    array_agg(g.label || ' — ' || g.motivo ORDER BY g.check_key),
    ARRAY[]::text[]
  )
  FROM public.case_activation_gates(_case) g
  WHERE g.obrigatorio AND g.estado <> 'validado';
$$;


--
-- Name: case_activation_gates(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.case_activation_gates(_case uuid) RETURNS TABLE(check_key text, label text, dominio text, obrigatorio boolean, estado text, motivo text, evidencia text, validado_em timestamp with time zone, validado_por uuid, origem text, isencao_motivo text, isencao_expira_em timestamp with time zone)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT
    d.check_key,
    d.label,
    d.dominio,
    d.obrigatorio,
    CASE
      WHEN k.id IS NULL THEN 'nao_avaliada'
      WHEN k.status = 'isento' AND k.isencao_expira_em IS NOT NULL AND k.isencao_expira_em < now() THEN 'expirada'
      WHEN k.status IN ('validado','nao_aplicavel','isento') THEN 'validado'
      ELSE 'pendente'
    END AS estado,
    CASE
      WHEN k.id IS NULL THEN 'Requisito ainda não instanciado para este caso'
      WHEN k.status = 'isento' AND k.isencao_expira_em IS NOT NULL AND k.isencao_expira_em < now() THEN 'Isenção expirada'
      WHEN k.status IN ('validado','nao_aplicavel','isento') THEN NULL
      ELSE 'Aguardando validação com evidência'
    END AS motivo,
    k.observacao AS evidencia,
    k.validado_em,
    k.validado_por,
    k.origem_validacao AS origem,
    k.isencao_motivo,
    k.isencao_expira_em
  FROM public.activation_check_definicoes() d
  LEFT JOIN public.case_activation_checks k
    ON k.case_id = _case AND k.check_key = d.check_key
  ORDER BY d.check_key;
$$;


--
-- Name: case_activation_pendencias(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.case_activation_pendencias(_case uuid) RETURNS TABLE(check_key text, label text, motivo text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT k.check_key, k.label,
    CASE
      WHEN k.status = 'pendente' THEN 'Aguardando validação'
      WHEN k.status = 'isento' AND k.isencao_expira_em is not null AND k.isencao_expira_em < now() THEN 'Isenção expirada'
      ELSE 'Pendente'
    END
  FROM public.case_activation_checks k
  WHERE k.case_id = _case AND k.obrigatorio
    AND (k.status = 'pendente'
      OR (k.status = 'isento' AND k.isencao_expira_em is not null AND k.isencao_expira_em < now()));
$$;


--
-- Name: caso_saude_cadencia(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.caso_saude_cadencia(_case uuid) RETURNS TABLE(dias_sem_touchpoint integer, status_cadencia text)
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  SELECT
    GREATEST(0, (current_date - COALESCE(c.ultimo_touchpoint_em, c.created_at)::date))::int,
    CASE
      WHEN c.aguardando_instituicao_externa AND COALESCE(c.motivo_espera_externa,'') <> '' THEN 'regular'
      WHEN (current_date - COALESCE(c.ultimo_touchpoint_em, c.created_at)::date) >= 14 THEN 'critico'
      WHEN (current_date - COALESCE(c.ultimo_touchpoint_em, c.created_at)::date) >= 10 THEN 'atencao'
      ELSE 'regular'
    END
  FROM public.crm_casos c
  WHERE c.id = _case;
$$;


--
-- Name: consentimento_ativo(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.consentimento_ativo(_case uuid, _client uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT EXISTS (
    SELECT 1 FROM public.consent_records c
    WHERE c.tipo_consentimento = 'tratamento_dados'
      AND c.status IN ('coletado','ativo')
      AND c.archived_at IS NULL
      AND c.revogado_em IS NULL
      AND ((_case IS NOT NULL AND c.case_id = _case) OR (_client IS NOT NULL AND c.client_id = _client))
  );
$$;


--
-- Name: consentimento_dispensado(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.consentimento_dispensado(_case uuid, _client uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT EXISTS (
    SELECT 1 FROM public.consent_exceptions e
    WHERE e.archived_at IS NULL
      AND e.revogado_em IS NULL
      AND (e.valido_ate IS NULL OR e.valido_ate >= current_date)
      AND ((_case IS NOT NULL AND e.case_id = _case) OR (_client IS NOT NULL AND e.client_id = _client))
  );
$$;


