--
-- Name: fn_activation_check_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_activation_check_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare v_admin boolean; v_papel app_role;
begin
  v_admin := public.has_org_role(NEW.organization_id, 'admin');
  v_papel := public.staff_meu_papel(NEW.organization_id);

  if TG_OP = 'UPDATE' and (NEW.check_key <> OLD.check_key or NEW.case_id <> OLD.case_id) then
    raise exception 'Não é permitido alterar a chave ou o caso de um requisito de ativação.';
  end if;

  if TG_OP = 'UPDATE' and NEW.status is distinct from OLD.status then
    if not v_admin then
      if v_papel is null or v_papel in ('leitura','pesquisador') then
        raise exception 'Seu papel não permite validar requisitos de ativação.';
      end if;
      if NEW.status in ('isento','nao_aplicavel') then
        raise exception 'Apenas admin pode autorizar isenção ou dispensa de requisito.';
      end if;
      if NEW.dominio = 'financeiro' and v_papel <> 'financeiro' then
        raise exception 'Apenas financeiro ou admin pode validar o requisito financeiro.';
      end if;
      if NEW.dominio = 'comercial' and v_papel not in ('comercial','operacoes') then
        raise exception 'Apenas comercial, operações ou admin pode validar o requisito comercial.';
      end if;
      if NEW.dominio in ('operacional','contratual') and v_papel not in ('operacoes','comercial','financeiro') then
        raise exception 'Seu papel não permite validar este requisito.';
      end if;
      if NEW.dominio = 'contratual' and v_papel <> 'operacoes' then
        raise exception 'Apenas operações ou admin pode validar o requisito contratual.';
      end if;
    end if;

    if NEW.status = 'isento' then
      if NEW.isencao_motivo is null or length(trim(NEW.isencao_motivo)) < 10 then
        raise exception 'Isenção exige motivo com no mínimo 10 caracteres.';
      end if;
      NEW.isencao_autorizada_por := auth.uid();
      NEW.isencao_autorizada_em := now();
    else
      NEW.isencao_motivo := null;
      NEW.isencao_autorizada_por := null;
      NEW.isencao_autorizada_em := null;
      NEW.isencao_expira_em := null;
    end if;

    if NEW.status = 'pendente' then
      NEW.validado_em := null;
      NEW.validado_por := null;
      NEW.origem_validacao := null;
    else
      NEW.validado_em := now();
      NEW.validado_por := auth.uid();
      NEW.origem_validacao := coalesce(NEW.origem_validacao, 'validacao_manual');
    end if;
  end if;

  return NEW;
end $$;


--
-- Name: fn_anexo_v_versionar_os_escopo(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_anexo_v_versionar_os_escopo() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  v_os_anterior public.service_orders%ROWTYPE;
  v_os_nova_id uuid;
  v_item jsonb;
  v_hash text;
  v_ordem integer := 0;
  v_itens jsonb;
  v_ator uuid := auth.uid();
BEGIN
  IF NEW.annex_code <> 'ANEXO_V_ALTERACAO_ESCOPO'
     OR NEW.status <> 'approved'
     OR (TG_OP = 'UPDATE' AND OLD.status = 'approved') THEN
    RETURN NEW;
  END IF;

  IF NEW.file_hash IS NULL OR btrim(NEW.file_hash) = '' THEN
    RAISE EXCEPTION 'Anexo V não pode ser aceito sem conteudo_hash.';
  END IF;

  IF NEW.structured_data IS NULL OR NEW.structured_data = '{}'::jsonb THEN
    RAISE EXCEPTION 'Anexo V não pode ser aceito sem conteúdo estruturado.';
  END IF;

  v_itens := COALESCE(NEW.structured_data->'itens_escopo', NEW.structured_data->'scope_items');
  IF v_itens IS NULL OR jsonb_typeof(v_itens) <> 'array' OR jsonb_array_length(v_itens) = 0 THEN
    RAISE EXCEPTION 'Anexo V não pode ser aceito sem itens de escopo versionáveis.';
  END IF;

  SELECT * INTO v_os_anterior
  FROM public.service_orders
  WHERE organization_id = NEW.organization_id
    AND contract_id = NEW.contract_id
    AND archived_at IS NULL
  ORDER BY versao DESC, created_at DESC
  LIMIT 1
  FOR UPDATE;

  IF v_os_anterior.id IS NULL THEN
    RAISE EXCEPTION 'Anexo V exige ordem de serviço anterior vinculada ao contrato.';
  END IF;

  v_hash := md5(
    NEW.file_hash || ':' ||
    COALESCE(NEW.structured_data::text, '') || ':' ||
    v_os_anterior.id::text || ':' ||
    (v_os_anterior.versao + 1)::text
  );

  INSERT INTO public.service_orders (
    organization_id, contract_id, contract_version_id, case_id, status,
    scope_summary, start_condition_status, start_condition_notes,
    responsible_user_id, start_date, end_date, deliverable_summary,
    client_visible_summary, internal_notes, demo, proposal_id,
    commercial_condition_id, versao, conteudo_hash, dados_teste,
    previous_version_id, source_annex_id, created_by, updated_by
  ) VALUES (
    v_os_anterior.organization_id, v_os_anterior.contract_id,
    v_os_anterior.contract_version_id, v_os_anterior.case_id, 'draft',
    COALESCE(NULLIF(btrim(NEW.structured_data->>'scope_summary'), ''), v_os_anterior.scope_summary),
    'pending',
    'Nova versão interna derivada do aceite do Anexo V; ativação permanece sujeita aos gates vigentes.',
    v_os_anterior.responsible_user_id, v_os_anterior.start_date, v_os_anterior.end_date,
    COALESCE(NULLIF(btrim(NEW.structured_data->>'deliverable_summary'), ''), v_os_anterior.deliverable_summary),
    COALESCE(NULLIF(btrim(NEW.structured_data->>'client_visible_summary'), ''), v_os_anterior.client_visible_summary),
    'Versionada automaticamente a partir do Anexo V aprovado.',
    v_os_anterior.demo, v_os_anterior.proposal_id,
    v_os_anterior.commercial_condition_id, v_os_anterior.versao + 1,
    v_hash, v_os_anterior.dados_teste,
    v_os_anterior.id, NEW.id, v_ator, v_ator
  ) RETURNING id INTO v_os_nova_id;

  FOR v_item IN SELECT value FROM jsonb_array_elements(v_itens)
  LOOP
    IF COALESCE(btrim(v_item->>'title'), '') = '' THEN
      RAISE EXCEPTION 'Anexo V contém item de escopo sem título.';
    END IF;
    v_ordem := v_ordem + 1;
    INSERT INTO public.contract_scope_items (
      organization_id, contract_id, category, title, description, status,
      source_type, source_reference, display_order, requires_human_validation,
      proposal_id, commercial_condition_id, service_order_id,
      previous_version_id, source_annex_id, scope_version, conteudo_hash,
      created_by, updated_by
    ) VALUES (
      NEW.organization_id, NEW.contract_id,
      COALESCE(NULLIF(v_item->>'category', ''), 'contracted_scope'),
      btrim(v_item->>'title'), NULLIF(btrim(v_item->>'description'), ''),
      COALESCE(NULLIF(v_item->>'status', ''), 'included'),
      'annex', 'Anexo V v' || NEW.annex_version::text,
      COALESCE((v_item->>'display_order')::integer, v_ordem), true,
      v_os_anterior.proposal_id, v_os_anterior.commercial_condition_id, v_os_nova_id,
      (SELECT c.id FROM public.contract_scope_items c
       WHERE c.organization_id = NEW.organization_id
         AND c.contract_id = NEW.contract_id
         AND c.title = btrim(v_item->>'title')
         AND c.archived_at IS NULL
       ORDER BY c.scope_version DESC, c.created_at DESC LIMIT 1),
      NEW.id, v_os_anterior.versao + 1,
      md5(NEW.file_hash || ':' || v_item::text),
      v_ator, v_ator
    );
  END LOOP;

  INSERT INTO public.audit_logs (
    organization_id, user_id, acao, entidade, entidade_id, metadados
  ) VALUES (
    NEW.organization_id, v_ator, 'anexo_v_aceito_versionamento_interno',
    'service_orders', v_os_nova_id,
    jsonb_build_object(
      'anexo_id', NEW.id,
      'os_anterior_id', v_os_anterior.id,
      'os_versao', v_os_anterior.versao + 1,
      'conteudo_hash', v_hash,
      'itens_escopo', jsonb_array_length(v_itens),
      'acao_externa', false
    )
  );

  RETURN NEW;
END;
$$;


--
-- Name: fn_app_projection_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_app_projection_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  txt text := lower(coalesce(NEW.content_sanitized, ''));
  ev public.evidences%ROWTYPE;
BEGIN
  IF coalesce(btrim(NEW.content_sanitized), '') = '' THEN
    RAISE EXCEPTION 'Projeção exige conteúdo sanitizado.';
  END IF;

  IF txt ~ '(https?://|www\.|drive\.google|storage/|/storage|s3://|supabase\.co|\.pdf|\.jpg|\.png)' THEN
    RAISE EXCEPTION 'Conteúdo com URL, link ou referência de arquivo interno não pode compor projeção.';
  END IF;

  IF txt ~ '(hipótese|hipotese|risco|suspeita|transcri|nota interna|uso interno|confidencial|probabilidade|chance de êxito|chance de exito|garantid|parecer jurídico|parecer juridico)' THEN
    RAISE EXCEPTION 'Conteúdo com hipótese, risco, transcrição, nota interna ou juízo de mérito não pode compor projeção.';
  END IF;

  IF NEW.source_entity_type = 'evidence' THEN
    SELECT * INTO ev FROM public.evidences WHERE id = NEW.source_entity_id;
    IF ev.id IS NULL THEN
      RAISE EXCEPTION 'Projeção de evidência exige evidência existente.';
    END IF;
    IF ev.case_id <> NEW.case_id THEN
      RAISE EXCEPTION 'Projeção deve pertencer ao mesmo caso da evidência.';
    END IF;
    IF NEW.approval_status IN ('approved','published') THEN
      IF ev.access_level = 'restrito' THEN
        RAISE EXCEPTION 'Evidência restrita não pode ser projetada ao cliente.';
      END IF;
      IF ev.workflow_status NOT IN ('aprovada_para_entrega','publicada') THEN
        RAISE EXCEPTION 'Somente evidência aprovada para entrega pode ser projetada.';
      END IF;
    END IF;
  END IF;

  IF NEW.approval_status IN ('approved','published') THEN
    IF NEW.approved_by IS NULL OR NEW.approved_at IS NULL THEN
      RAISE EXCEPTION 'Aprovação de projeção exige aprovador e data de aprovação.';
    END IF;
  ELSE
    NEW.approved_by := NULL;
    NEW.approved_at := NULL;
  END IF;

  IF NEW.approval_status = 'published' AND NEW.effective_from IS NULL THEN
    NEW.effective_from := now();
  END IF;

  IF TG_OP = 'UPDATE' AND OLD.approval_status = 'published' AND NEW.approval_status NOT IN ('published','archived') THEN
    RAISE EXCEPTION 'Projeção publicada só pode ser arquivada, nunca revertida silenciosamente.';
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: fn_archive_meta(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_archive_meta() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
begin
  if NEW.archived_at is not null and OLD.archived_at is null then
    NEW.archived_by := coalesce(NEW.archived_by, auth.uid());
    if NEW.archive_motivo is null or length(trim(NEW.archive_motivo)) = 0 then
      raise exception 'Informe o motivo do arquivamento.';
    end if;
  end if;
  return NEW;
end $$;


--
-- Name: fn_artifact_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_artifact_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.archived_at IS NOT NULL AND (TG_OP = 'INSERT' OR OLD.archived_at IS NULL) THEN
    IF NEW.sucessor_id IS NULL AND COALESCE(btrim(NEW.archive_motivo), '') = '' THEN
      RAISE EXCEPTION 'Arquivar artefato exige sucessor ou motivo.';
    END IF;
    IF NEW.status_recuperacao = 'NAO_LOCALIZADO' THEN
      IF staff_meu_papel(NEW.organization_id) IS DISTINCT FROM 'admin' THEN
        RAISE EXCEPTION 'Artefato não localizado só pode ser arquivado por admin.';
      END IF;
      IF length(COALESCE(btrim(NEW.archive_motivo), '')) < 15 THEN
        RAISE EXCEPTION 'Arquivar artefato não localizado exige justificativa detalhada do admin.';
      END IF;
    END IF;
  END IF;

  IF NEW.sucessor_id IS NOT NULL AND NEW.sucessor_id = NEW.id THEN
    RAISE EXCEPTION 'Um artefato não pode substituir a si mesmo.';
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: fn_atendimento_entrega_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_atendimento_entrega_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE b text[]; pode boolean;
BEGIN
  IF TG_OP = 'UPDATE' AND COALESCE(NEW.entrega_cliente,false) IS DISTINCT FROM COALESCE(OLD.entrega_cliente,false) THEN
    pode := public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'operacoes');
    IF NOT pode THEN RAISE EXCEPTION 'Apenas admin e operações liberam ou recolhem entregas.'; END IF;

    IF COALESCE(NEW.entrega_cliente,false) THEN
      IF NEW.case_id IS NULL THEN RAISE EXCEPTION 'Entrega exige caso vinculado.'; END IF;
      b := public.atendimento_bloqueios(NEW.case_id);
      IF array_length(b,1) > 0 THEN
        RAISE EXCEPTION 'Caso sem portal elegível: %', array_to_string(b, '; ');
      END IF;
      IF COALESCE(NEW.entrega_classificacao,'') <> 'externa_aprovada' THEN
        RAISE EXCEPTION 'Entrega só pode ser liberada como externa aprovada.';
      END IF;
      IF COALESCE(btrim(NEW.entrega_versao),'') = '' THEN RAISE EXCEPTION 'Informe a versão da entrega.'; END IF;
      IF NEW.entrega_responsavel_id IS NULL THEN RAISE EXCEPTION 'Informe o responsável pela entrega.'; END IF;
      NEW.liberado_cliente := true;
      NEW.liberado_em := now();
      NEW.liberado_por := auth.uid();
      NEW.recolhido_em := NULL;
    ELSE
      IF COALESCE(btrim(NEW.recolhimento_motivo),'') = '' THEN
        RAISE EXCEPTION 'Recolher entrega exige justificativa objetiva.';
      END IF;
      NEW.liberado_cliente := false;
      NEW.recolhido_em := now();
      NEW.recolhido_por := auth.uid();
    END IF;

    INSERT INTO public.audit_logs (organization_id, user_id, acao, entidade, entidade_id, metadados)
    VALUES (NEW.organization_id, auth.uid(),
      CASE WHEN COALESCE(NEW.entrega_cliente,false) THEN 'entrega_liberada' ELSE 'entrega_recolhida' END,
      'documents', NEW.id,
      jsonb_build_object(
        'case_id', NEW.case_id,
        'classificacao', NEW.entrega_classificacao,
        'versao', NEW.entrega_versao,
        'versao_substituta', NEW.versao_substituta,
        'responsavel_id', NEW.entrega_responsavel_id,
        'motivo_recolhimento', NEW.recolhimento_motivo));
  END IF;
  RETURN NEW;
END; $$;


--
-- Name: fn_atendimento_fatura_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_atendimento_fatura_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE b text[]; pode boolean; acesso int;
BEGIN
  IF TG_OP = 'UPDATE' AND COALESCE(NEW.liberada_cliente,false) IS DISTINCT FROM COALESCE(OLD.liberada_cliente,false) THEN
    pode := public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'financeiro');
    IF NOT pode THEN RAISE EXCEPTION 'Apenas admin e financeiro alteram a visibilidade de faturas.'; END IF;

    IF COALESCE(NEW.liberada_cliente,false) THEN
      IF NEW.case_id IS NULL THEN RAISE EXCEPTION 'Fatura exige vínculo com caso antes de ficar visível.'; END IF;
      b := public.atendimento_bloqueios(NEW.case_id);
      IF array_length(b,1) > 0 THEN
        RAISE EXCEPTION 'Caso sem portal elegível: %', array_to_string(b, '; ');
      END IF;
      SELECT count(*) INTO acesso
        FROM public.client_portal_access a
       WHERE a.client_id = NEW.client_id
         AND a.access_status = 'active'
         AND a.access_level = 'client_workspace'
         AND a.archived_at IS NULL;
      IF acesso = 0 THEN RAISE EXCEPTION 'Cliente sem acesso autorizado e ativo ao espaço do cliente.'; END IF;
      NEW.liberada_em := now();
      NEW.liberada_por := auth.uid();
    END IF;

    INSERT INTO public.audit_logs (organization_id, user_id, acao, entidade, entidade_id, metadados)
    VALUES (NEW.organization_id, auth.uid(),
      CASE WHEN COALESCE(NEW.liberada_cliente,false) THEN 'fatura_liberada' ELSE 'fatura_ocultada' END,
      'invoices', NEW.id,
      jsonb_build_object('case_id', NEW.case_id, 'client_id', NEW.client_id));
  END IF;
  RETURN NEW;
END; $$;


--
-- Name: fn_atendimento_solicitacao_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_atendimento_solicitacao_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE b text[];
BEGIN
  IF TG_OP = 'INSERT' OR NEW.case_id IS DISTINCT FROM OLD.case_id THEN
    IF NEW.case_id IS NULL THEN RAISE EXCEPTION 'Solicitação exige caso vinculado.'; END IF;
    b := public.atendimento_bloqueios(NEW.case_id);
    IF array_length(b,1) > 0 THEN
      RAISE EXCEPTION 'Caso sem portal elegível: %', array_to_string(b, '; ');
    END IF;
  END IF;
  IF TG_OP = 'INSERT' THEN
    IF COALESCE(btrim(NEW.finalidade),'') = '' THEN RAISE EXCEPTION 'Informe a finalidade da solicitação.'; END IF;
    IF COALESCE(btrim(NEW.categoria),'') = '' THEN RAISE EXCEPTION 'Informe a categoria do documento solicitado.'; END IF;
    IF NEW.responsavel_id IS NULL THEN RAISE EXCEPTION 'Informe o responsável interno pela solicitação.'; END IF;
    IF NEW.prazo IS NULL THEN RAISE EXCEPTION 'Informe o prazo da solicitação.'; END IF;
    IF COALESCE(btrim(NEW.participante_nome),'') = '' THEN RAISE EXCEPTION 'Informe o participante a quem o documento se refere.'; END IF;
  END IF;
  RETURN NEW;
END; $$;


--
-- Name: fn_audit(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_audit() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_org uuid; v_id uuid;
begin
  v_org := (to_jsonb(NEW)->>'organization_id')::uuid;
  v_id := (to_jsonb(NEW)->>'id')::uuid;
  insert into public.audit_logs (organization_id, user_id, acao, entidade, entidade_id, valores_anteriores, valores_posteriores)
  values (v_org, auth.uid(), lower(TG_OP), TG_TABLE_NAME, v_id,
    case when TG_OP = 'UPDATE' then to_jsonb(OLD) else null end, to_jsonb(NEW));
  return NEW;
end $$;


--
-- Name: fn_audit_campos(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_audit_campos() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_org uuid;
  v_id uuid;
  v_old jsonb := case when TG_OP = 'UPDATE' then to_jsonb(OLD) else '{}'::jsonb end;
  v_new jsonb := to_jsonb(NEW);
  v_ant jsonb := '{}'::jsonb;
  v_pos jsonb := '{}'::jsonb;
  k text;
  sensivel boolean;
begin
  v_org := (v_new->>'organization_id')::uuid;
  v_id := (v_new->>'id')::uuid;

  for k in select jsonb_object_keys(v_new) loop
    if TG_OP = 'UPDATE' and (v_old->k) is not distinct from (v_new->k) then
      continue;
    end if;
    sensivel := k ~* '(cpf|rg\b|documento|endereco|cep|telefone|email|e_mail|url|link|token|transcri|storage_path|protegid|observac)';
    v_ant := v_ant || jsonb_build_object(
      k,
      case
        when TG_OP <> 'UPDATE' then null
        when v_old->k is null or v_old->k = 'null'::jsonb then null
        when sensivel then to_jsonb('[protegido]'::text)
        else v_old->k
      end);
    v_pos := v_pos || jsonb_build_object(
      k,
      case
        when v_new->k is null or v_new->k = 'null'::jsonb then null
        when sensivel then to_jsonb('[protegido]'::text)
        else v_new->k
      end);
  end loop;

  if v_org is null or (TG_OP = 'UPDATE' and v_pos = '{}'::jsonb) then
    return NEW;
  end if;

  insert into public.audit_logs (organization_id, user_id, acao, entidade, entidade_id, valores_anteriores, valores_posteriores, metadados)
  values (v_org, auth.uid(), lower(TG_OP), TG_TABLE_NAME, v_id,
    case when TG_OP = 'UPDATE' then v_ant else null end, v_pos,
    jsonb_build_object('origem', 'aba_casos', 'campos', (select jsonb_agg(x) from jsonb_object_keys(v_pos) x)));
  return NEW;
end
$$;


--
-- Name: fn_audit_status(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_audit_status() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_old text; v_new text;
begin
  v_old := to_jsonb(OLD)->>TG_ARGV[0];
  v_new := to_jsonb(NEW)->>TG_ARGV[0];
  if v_old is distinct from v_new then
    insert into public.audit_logs (organization_id, user_id, acao, entidade, entidade_id, valores_anteriores, valores_posteriores, metadados)
    values ((to_jsonb(NEW)->>'organization_id')::uuid, auth.uid(), 'status_change', TG_TABLE_NAME, NEW.id,
            jsonb_build_object('status', v_old), jsonb_build_object('status', v_new),
            jsonb_build_object('campo', TG_ARGV[0]));
  end if;
  return NEW;
end $$;


--
-- Name: fn_authorized_portal_email_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_authorized_portal_email_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  v_case_cliente uuid;
BEGIN
  NEW.email := lower(btrim(NEW.email));
  IF NEW.email !~ '^[^@[:space:]]+@[^@[:space:]]+\.[^@[:space:]]+$' THEN
    RAISE EXCEPTION 'E-mail inválido para autorização de portal.';
  END IF;

  IF NEW.finalidade IS NULL OR length(btrim(NEW.finalidade)) < 5 THEN
    RAISE EXCEPTION 'Registre a finalidade da autorização (mínimo 5 caracteres).';
  END IF;

  IF NEW.status NOT IN ('pendente', 'aprovado', 'recusado', 'revogado') THEN
    RAISE EXCEPTION 'Status de autorização inválido: %', NEW.status;
  END IF;

  IF NEW.status IN ('aprovado', 'recusado', 'revogado') THEN
    IF NEW.validado_por IS NULL THEN NEW.validado_por := auth.uid(); END IF;
    IF NEW.validado_em IS NULL THEN NEW.validado_em := now(); END IF;
  END IF;

  IF NEW.case_id IS NOT NULL THEN
    SELECT cliente_id INTO v_case_cliente FROM public.crm_casos WHERE id = NEW.case_id;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'Caso informado não existe.';
    END IF;
    IF NEW.client_id IS NOT NULL AND v_case_cliente IS DISTINCT FROM NEW.client_id THEN
      RAISE EXCEPTION 'O caso autorizado não pertence à pessoa informada.';
    END IF;
  END IF;

  IF NEW.archived_at IS NOT NULL AND (NEW.archive_motivo IS NULL OR length(btrim(NEW.archive_motivo)) < 5) THEN
    RAISE EXCEPTION 'Arquivamento exige motivo registrado.';
  END IF;

  RETURN NEW;
END;
$_$;


