--
-- Name: fn_blueprint_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_blueprint_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  prod public.product_catalog%ROWTYPE;
  exc public.sku_price_exceptions%ROWTYPE;
BEGIN
  IF NEW.product_catalog_id IS NOT NULL THEN
    SELECT * INTO prod FROM public.product_catalog WHERE id = NEW.product_catalog_id;
    IF prod.exige_case_service AND NEW.case_service_id IS NULL THEN
      RAISE EXCEPTION 'Produto contextual/complementar exige case_service vinculado.';
    END IF;
    IF prod.exige_justificativa_escopo AND coalesce(btrim(NEW.escopo_aprovado), '') = '' THEN
      RAISE EXCEPTION 'Produto contextual/complementar exige justificativa de escopo aprovado.';
    END IF;
    IF NEW.conteudo_aprovado_para_proposta AND (prod.status_homologacao <> 'homologado' OR prod.elegivel_para_proposta IS NOT TRUE) THEN
      RAISE EXCEPTION 'Produto não homologado/não elegível não entra em proposta.';
    END IF;
  END IF;

  IF NEW.origem_preco = 'excecao_comercial_aprovada' THEN
    IF NEW.excecao_comercial_id IS NULL THEN
      RAISE EXCEPTION 'Origem de preço por exceção exige exceção comercial aprovada vinculada.';
    END IF;
    SELECT * INTO exc FROM public.sku_price_exceptions WHERE id = NEW.excecao_comercial_id;
    IF exc.id IS NULL THEN
      RAISE EXCEPTION 'Exceção comercial não encontrada.';
    END IF;
  ELSE
    IF NEW.preco_comercial_vigente IS NOT NULL THEN
      IF prod.id IS NULL THEN
        RAISE EXCEPTION 'Preço no Blueprint exige produto do catálogo homologado.';
      END IF;
      IF prod.status_homologacao <> 'homologado' THEN
        RAISE EXCEPTION 'Preço no Blueprint exige produto com homologação vigente.';
      END IF;
      IF prod.preco_comercial_vigente IS NULL OR prod.preco_comercial_vigente <> NEW.preco_comercial_vigente THEN
        RAISE EXCEPTION 'Preço manual bloqueado: use o preço comercial vigente do catálogo homologado.';
      END IF;
    END IF;
  END IF;

  NEW.updated_at := now();
  RETURN NEW;
END; $$;


--
-- Name: fn_case_alias_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_case_alias_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE v_org uuid;
BEGIN
  SELECT organization_id INTO v_org FROM public.crm_casos WHERE id = NEW.case_id;
  IF v_org IS NULL THEN
    RAISE EXCEPTION 'Alias precisa apontar para um caso existente.';
  END IF;
  IF v_org <> NEW.organization_id THEN
    RAISE EXCEPTION 'Alias precisa pertencer à mesma organização do caso.';
  END IF;
  NEW.alias := btrim(NEW.alias);
  IF EXISTS (
    SELECT 1 FROM public.crm_casos c
     WHERE c.organization_id = NEW.organization_id
       AND c.id <> NEW.case_id
       AND upper(c.codigo) = upper(NEW.alias)
  ) THEN
    RAISE EXCEPTION 'Este identificador é o código canônico de outro caso e não pode virar alias.';
  END IF;
  NEW.created_by := coalesce(NEW.created_by, auth.uid());
  RETURN NEW;
END;
$$;


--
-- Name: fn_case_alias_imutavel(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_case_alias_imutavel() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'Alias histórico não pode ser excluído. Registre substituição em superseded_by.';
  END IF;
  IF NEW.alias IS DISTINCT FROM OLD.alias
     OR NEW.case_id IS DISTINCT FROM OLD.case_id
     OR NEW.organization_id IS DISTINCT FROM OLD.organization_id THEN
    RAISE EXCEPTION 'Alias histórico é imutável. Apenas superseded_by/reason podem ser complementados.';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: fn_case_codigo_canonico(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_case_codigo_canonico() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF TG_OP = 'UPDATE' THEN
    -- case_id é imutável: edição manual é silenciosamente revertida e sinalizada
    IF NEW.codigo IS DISTINCT FROM OLD.codigo THEN
      RAISE EXCEPTION 'O identificador canônico do caso é imutável (%). Registre o valor anterior em case_aliases.', OLD.codigo;
    END IF;
    IF NEW.modelo IS DISTINCT FROM OLD.modelo THEN
      RAISE EXCEPTION 'O modelo do caso compõe o identificador canônico e não pode ser alterado após a abertura.';
    END IF;
    RETURN NEW;
  END IF;

  NEW.modelo := upper(btrim(coalesce(NEW.modelo, 'IND')));

  IF NEW.codigo IS NULL OR btrim(NEW.codigo) = '' THEN
    NEW.codigo := public.gerar_case_id(NEW.organization_id, NEW.modelo, coalesce(NEW.demo, false));
  END IF;

  NEW.codigo := upper(btrim(NEW.codigo));

  -- fixtures nunca se confundem com casos reais
  IF coalesce(NEW.demo, false) AND NEW.codigo !~ '^CA-DEMO' THEN
    RAISE EXCEPTION 'Caso de demonstração exige identificador com prefixo CA-DEMO.';
  END IF;
  IF NOT coalesce(NEW.demo, false) AND NEW.codigo ~ '^CA-DEMO' THEN
    RAISE EXCEPTION 'Caso real não pode usar identificador de demonstração.';
  END IF;

  -- alias histórico nunca vira chave de caso novo
  IF EXISTS (
    SELECT 1 FROM public.case_aliases a
     WHERE a.organization_id = NEW.organization_id
       AND upper(a.alias) = NEW.codigo
  ) THEN
    RAISE EXCEPTION 'Este identificador já existe como alias histórico. Use o identificador canônico do caso.';
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: fn_case_dependent_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_case_dependent_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  _participa boolean := coalesce(NEW.participa_do_contrato,false)
                     OR coalesce(NEW.possui_acesso_app,false)
                     OR coalesce(NEW.anexo_individual_aplicavel,false);
BEGIN
  IF NEW.status_representacao = 'documentada'
     AND coalesce(NEW.documento_representacao_referencia_interna, '') = '' THEN
    RAISE EXCEPTION 'Representação documentada exige referência interna do documento.';
  END IF;

  IF _participa THEN
    IF NEW.status_representacao <> 'documentada' THEN
      RAISE EXCEPTION 'Contrato, App ou anexo individual do dependente exigem representação documentada.';
    END IF;
    IF coalesce(NEW.documento_representacao_referencia_interna, '') = '' THEN
      RAISE EXCEPTION 'Participação do dependente exige referência interna válida da representação.';
    END IF;
    IF NEW.dependent_person_id IS NULL OR NEW.titular_responsavel_legal_id IS NULL THEN
      RAISE EXCEPTION 'Participação do dependente exige pessoa e responsável legal referenciados por ID.';
    END IF;
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: fn_case_plan_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_case_plan_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_derivado text;
BEGIN
  IF NEW.status = 'ativo' AND NEW.archived_at IS NULL THEN
    IF NEW.responsavel_user_id IS NULL THEN
      RAISE EXCEPTION 'Plano ativo exige responsável.';
    END IF;
    IF NEW.proxima_acao IS NULL OR btrim(NEW.proxima_acao) = '' THEN
      RAISE EXCEPTION 'Plano ativo exige próxima ação.';
    END IF;
    IF NEW.prazo_proxima_acao IS NULL THEN
      RAISE EXCEPTION 'Plano ativo exige prazo da próxima ação.';
    END IF;
    SELECT status_caso_derivado INTO v_derivado FROM public.crm_casos WHERE id = NEW.case_id;
    IF v_derivado = 'pre_onboarding_bloqueado' THEN
      RAISE EXCEPTION 'Caso em pre_onboarding_bloqueado não pode ter plano ativo.';
    END IF;
  END IF;
  NEW.updated_at := now();
  RETURN NEW;
END $$;


--
-- Name: fn_case_report_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_case_report_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  NEW.updated_at := now();

  IF NEW.report_status IN ('aprovado_internamente','entregue') AND NEW.data_aprovacao IS NULL THEN
    RAISE EXCEPTION 'Data de aprovacao obrigatoria a partir de aprovado internamente';
  END IF;

  IF NEW.report_status = 'entregue' THEN
    IF NEW.data_entrega IS NULL THEN
      RAISE EXCEPTION 'Data de entrega obrigatoria quando o relatorio esta entregue';
    END IF;
    IF NEW.resumo_aprovado_cliente IS NULL OR btrim(NEW.resumo_aprovado_cliente) = '' THEN
      RAISE EXCEPTION 'Entrega exige resumo aprovado e sanitizado para o cliente';
    END IF;
  END IF;

  IF NEW.publicado_no_app THEN
    IF NEW.report_status <> 'entregue' THEN
      RAISE EXCEPTION 'Relatorio nao entregue nao pode ser publicado no App';
    END IF;
    IF NEW.resumo_aprovado_cliente IS NULL OR btrim(NEW.resumo_aprovado_cliente) = '' THEN
      RAISE EXCEPTION 'Publicacao exige projecao aprovada e sanitizada';
    END IF;
  END IF;

  IF NEW.archived_at IS NOT NULL AND (NEW.archived_reason IS NULL OR btrim(NEW.archived_reason) = '') THEN
    RAISE EXCEPTION 'Arquivamento exige motivo';
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: fn_case_service_promocao_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_case_service_promocao_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  pendentes integer;
  condicoes integer;
BEGIN
  IF NEW.status IN ('approved','contracted','active')
     AND (TG_OP = 'INSERT' OR OLD.status IS DISTINCT FROM NEW.status) THEN

    SELECT count(*) INTO pendentes
      FROM public.case_service_criterios c
     WHERE c.case_id = NEW.case_id
       AND c.archived_at IS NULL
       AND c.obrigatorio
       AND (c.status = 'pendente_decisao_humana'
            OR (c.status IN ('aceito','recusado') AND (c.decidido_por IS NULL OR c.decidido_em IS NULL)));
    IF pendentes > 0 THEN
      RAISE EXCEPTION 'CRITERIO_ACEITE_PENDENTE: % critério(s) obrigatório(s) sem decisão humana registrada.', pendentes;
    END IF;

    SELECT count(*) INTO condicoes
      FROM public.commercial_conditions cc
     WHERE cc.case_service_id = NEW.id
       AND cc.archived_at IS NULL
       AND cc.status = 'homologada';
    IF condicoes = 0 THEN
      RAISE EXCEPTION 'CONDICAO_COMERCIAL_NAO_HOMOLOGADA: serviço não pode sair de rascunho sem condição comercial homologada.';
    END IF;

    IF NEW.contrato_referencia_interna IS NULL OR btrim(NEW.contrato_referencia_interna) = '' THEN
      RAISE EXCEPTION 'REFERENCIA_CONTRATUAL_AUSENTE: serviço exige referência contratual interna antes da promoção.';
    END IF;
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: fn_case_source_document_audit(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_case_source_document_audit() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  INSERT INTO public.audit_logs (organization_id, user_id, acao, entidade, entidade_id, metadados)
  VALUES (
    NEW.organization_id,
    auth.uid(),
    CASE WHEN TG_OP = 'INSERT' THEN 'criacao'
         WHEN NEW.archived_at IS NOT NULL AND OLD.archived_at IS NULL THEN 'arquivamento'
         ELSE 'atualizacao' END,
    'case_source_documents',
    NEW.id,
    jsonb_build_object(
      'case_id', NEW.case_id,
      'tipo_documento', NEW.tipo_documento,
      'status', NEW.status,
      'qualidade_origem', NEW.qualidade_origem,
      'confidencialidade', NEW.confidencialidade,
      'archive_motivo', NEW.archive_motivo
    )
  );
  RETURN NEW;
END;
$$;


--
-- Name: fn_case_source_document_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_case_source_document_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_tipos text[] := ARRAY[
    'certidao_nascimento','certidao_casamento','certidao_obito','registro_civil','inteiro_teor',
    'certidao_estrangeira','registro_religioso_batismo','registro_imigracao','lista_passageiros',
    'registro_consular','naturalizacao','passaporte','documento_identidade','comprovante_residencia',
    'documento_militar','documento_notarial','inventario_testamento','documento_judicial',
    'documento_cidadania','certidao_negativa_positiva','registro_arquivo_historico',
    'fotografia_imagem_historica','correspondencia','arvore_recebida_familia','relato_familiar',
    'documento_comercial_contratual','proposta_canva','outro_documento'];
  v_status text[] := ARRAY['pendente_revisao','revisado','rejeitado','arquivado'];
  v_qualidade text[] := ARRAY['original_oficial','copia_autenticada','copia_simples','imagem_digital',
    'relato_familiar','fonte_secundaria','origem_a_confirmar'];
  v_conf text[] := ARRAY['equipe_do_caso','interno','restrito'];
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'EXCLUSAO_FISICA_BLOQUEADA: use arquivamento com motivo.';
  END IF;

  IF NOT (NEW.tipo_documento = ANY (v_tipos)) THEN
    RAISE EXCEPTION 'TIPO_DOCUMENTO_INVALIDO: %', NEW.tipo_documento;
  END IF;
  IF NOT (NEW.status = ANY (v_status)) THEN
    RAISE EXCEPTION 'STATUS_INVALIDO: %', NEW.status;
  END IF;
  IF NOT (NEW.qualidade_origem = ANY (v_qualidade)) THEN
    RAISE EXCEPTION 'QUALIDADE_ORIGEM_INVALIDA: %', NEW.qualidade_origem;
  END IF;
  IF NOT (NEW.confidencialidade = ANY (v_conf)) THEN
    RAISE EXCEPTION 'CONFIDENCIALIDADE_INVALIDA: %', NEW.confidencialidade;
  END IF;
  IF NEW.extracao_status <> 'nao_preparado' THEN
    RAISE EXCEPTION 'EXTRACAO_NAO_DISPONIVEL: ponto de extensão ainda não implementado.';
  END IF;

  IF coalesce(btrim(NEW.origem_documento), '') = '' THEN
    RAISE EXCEPTION 'ORIGEM_DOCUMENTO_OBRIGATORIA';
  END IF;

  IF (NEW.pessoa_ref_id IS NULL AND NEW.pessoa_nao_identificada IS NOT TRUE)
     OR (NEW.pessoa_ref_id IS NOT NULL AND NEW.pessoa_nao_identificada IS TRUE) THEN
    RAISE EXCEPTION 'PESSOA_RELACIONADA_OBRIGATORIA: informe pessoa existente do caso ou marque pessoa ainda não identificada.';
  END IF;

  IF NEW.archived_at IS NOT NULL AND coalesce(btrim(NEW.archive_motivo), '') = '' THEN
    RAISE EXCEPTION 'MOTIVO_ARQUIVAMENTO_OBRIGATORIO';
  END IF;

  IF TG_OP = 'INSERT' THEN
    NEW.created_by := auth.uid();
    NEW.created_at := now();
    NEW.status := coalesce(NEW.status, 'pendente_revisao');
  ELSE
    NEW.created_by := OLD.created_by;
    NEW.created_at := OLD.created_at;
    NEW.organization_id := OLD.organization_id;
    NEW.case_id := OLD.case_id;
    NEW.storage_path := OLD.storage_path;
  END IF;
  NEW.updated_by := auth.uid();
  NEW.updated_at := now();
  RETURN NEW;
END;
$$;


--
-- Name: fn_case_source_document_link_audit(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_case_source_document_link_audit() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  INSERT INTO public.audit_logs (organization_id, user_id, acao, entidade, entidade_id, metadados)
  VALUES (
    NEW.organization_id,
    auth.uid(),
    CASE WHEN TG_OP = 'INSERT' THEN 'vinculo_fonte_criado'
         WHEN NEW.archived_at IS NOT NULL AND OLD.archived_at IS NULL THEN 'vinculo_fonte_arquivado'
         ELSE 'vinculo_fonte_atualizado' END,
    'case_source_document_links',
    NEW.id,
    jsonb_build_object(
      'case_id', NEW.case_id,
      'source_document_id', NEW.source_document_id,
      'tipo_vinculo', NEW.tipo_vinculo,
      'alvo', CASE WHEN NEW.evidence_id IS NOT NULL THEN 'evidencia'
                   WHEN NEW.document_request_id IS NOT NULL THEN 'solicitacao'
                   WHEN NEW.research_person_id IS NOT NULL THEN 'pessoa'
                   ELSE 'relatorio' END
    )
  );
  RETURN NEW;
END;
$$;


--
-- Name: fn_case_source_document_link_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_case_source_document_link_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  alvos int;
  doc record;
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'EXCLUSAO_FISICA_PROIBIDA';
  END IF;

  IF NEW.tipo_vinculo NOT IN ('comprova','complementa','atende_solicitacao','refere_pessoa','citado_em_relatorio') THEN
    RAISE EXCEPTION 'TIPO_VINCULO_INVALIDO';
  END IF;

  alvos := (CASE WHEN NEW.evidence_id IS NOT NULL THEN 1 ELSE 0 END)
         + (CASE WHEN NEW.document_request_id IS NOT NULL THEN 1 ELSE 0 END)
         + (CASE WHEN NEW.research_person_id IS NOT NULL THEN 1 ELSE 0 END)
         + (CASE WHEN NEW.case_report_id IS NOT NULL THEN 1 ELSE 0 END);
  IF alvos <> 1 THEN
    RAISE EXCEPTION 'ALVO_UNICO_OBRIGATORIO';
  END IF;

  SELECT organization_id, case_id INTO doc
  FROM public.case_source_documents WHERE id = NEW.source_document_id;
  IF doc IS NULL THEN
    RAISE EXCEPTION 'DOCUMENTO_NAO_ENCONTRADO';
  END IF;
  IF doc.organization_id <> NEW.organization_id OR doc.case_id <> NEW.case_id THEN
    RAISE EXCEPTION 'DOCUMENTO_DE_OUTRO_CASO';
  END IF;

  IF NEW.evidence_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.evidences e
    WHERE e.id = NEW.evidence_id AND e.case_id = NEW.case_id AND e.organization_id = NEW.organization_id
  ) THEN
    RAISE EXCEPTION 'ALVO_DE_OUTRO_CASO';
  END IF;
  IF NEW.document_request_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.document_requests d
    WHERE d.id = NEW.document_request_id AND d.case_id = NEW.case_id AND d.organization_id = NEW.organization_id
  ) THEN
    RAISE EXCEPTION 'ALVO_DE_OUTRO_CASO';
  END IF;
  IF NEW.research_person_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.research_people p
    WHERE p.id = NEW.research_person_id AND p.organization_id = NEW.organization_id
  ) THEN
    RAISE EXCEPTION 'ALVO_DE_OUTRO_CASO';
  END IF;
  IF NEW.case_report_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.case_reports r
    WHERE r.id = NEW.case_report_id AND r.case_id = NEW.case_id AND r.organization_id = NEW.organization_id
  ) THEN
    RAISE EXCEPTION 'ALVO_DE_OUTRO_CASO';
  END IF;

  IF TG_OP = 'INSERT' THEN
    NEW.created_by := auth.uid();
    NEW.vinculado_por := auth.uid();
    NEW.vinculado_em := now();
    NEW.created_at := now();
    NEW.archived_at := NULL;
    NEW.archive_motivo := NULL;
  ELSE
    NEW.created_by := OLD.created_by;
    NEW.created_at := OLD.created_at;
    NEW.source_document_id := OLD.source_document_id;
    NEW.case_id := OLD.case_id;
    NEW.organization_id := OLD.organization_id;
    IF NEW.archived_at IS NOT NULL AND (NEW.archive_motivo IS NULL OR length(btrim(NEW.archive_motivo)) < 5) THEN
      RAISE EXCEPTION 'MOTIVO_DE_ARQUIVAMENTO_OBRIGATORIO';
    END IF;
  END IF;
  NEW.updated_by := auth.uid();
  NEW.updated_at := now();
  RETURN NEW;
END;
$$;


--
-- Name: fn_caso_alias_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_caso_alias_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  IF EXISTS (
    SELECT 1 FROM public.crm_casos c
    WHERE c.organization_id = NEW.organization_id
      AND c.id <> NEW.id
      AND c.archived_at IS NULL
      AND upper(NEW.codigo) = ANY (SELECT upper(x) FROM unnest(c.codigos_legados) x)
  ) THEN
    RAISE EXCEPTION 'Este código é alias histórico de um caso canônico existente. Use o case_id canônico.';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: fn_caso_ativacao_gates_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_caso_ativacao_gates_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_bloqueios text[];
  v_virou_ativo boolean;
BEGIN
  v_virou_ativo :=
    (COALESCE(NEW.ativo, false) AND NOT COALESCE(OLD.ativo, false))
    OR (NEW.status = 'ativo' AND COALESCE(OLD.status, '') <> 'ativo')
    OR (NEW.eixo_operacao = 'caso_ativo' AND COALESCE(OLD.eixo_operacao, '') <> 'caso_ativo');

  IF NOT v_virou_ativo THEN
    RETURN NEW;
  END IF;

  v_bloqueios := public.case_activacao_bloqueios(NEW.id);

  IF array_length(v_bloqueios, 1) > 0 THEN
    RAISE EXCEPTION 'NÃO ELEGÍVEL — ATIVAÇÃO BLOQUEADA: % requisito(s) obrigatório(s) fora de validado. %',
      array_length(v_bloqueios, 1), array_to_string(v_bloqueios, ' | ');
  END IF;

  RETURN NEW;
END $$;


--
-- Name: fn_caso_ativo_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_caso_ativo_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_pend integer;
BEGIN
  IF NEW.eixo_operacao = 'caso_ativo' AND COALESCE(OLD.eixo_operacao,'') <> 'caso_ativo' THEN
    IF NEW.onboarding_iniciado_em IS NULL THEN
      RAISE EXCEPTION 'Caso ativo exige onboarding iniciado.';
    END IF;
    SELECT count(*) INTO v_pend FROM public.onboarding_checklist
      WHERE case_id = NEW.id AND obrigatorio IS TRUE
        AND COALESCE(status,'pendente') NOT IN ('concluido','nao_aplicavel')
        AND archived_at IS NULL;
    IF v_pend > 0 THEN
      RAISE EXCEPTION 'Caso ativo bloqueado: % item(ns) obrigatório(s) do checklist de onboarding pendente(s).', v_pend;
    END IF;
  END IF;
  RETURN NEW;
END $$;


--
-- Name: fn_caso_papel_registro(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_caso_papel_registro() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.demo IS TRUE OR COALESCE(NEW.codigo, '') LIKE 'CA-DEMO-%' THEN
    NEW.papel_registro := 'demonstracao';
    NEW.demo := true;
  ELSIF NEW.piloto IS TRUE AND COALESCE(NEW.papel_registro, 'operacional') = 'operacional' THEN
    NEW.papel_registro := 'piloto_real';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: fn_catalog_audit_append_only(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_catalog_audit_append_only() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  RAISE EXCEPTION 'Auditoria de catálogo é append-only: alteração ou exclusão não permitida.';
END;
$$;


--
-- Name: fn_catalog_recon_run_append_only(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_catalog_recon_run_append_only() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  RAISE EXCEPTION 'Execuções de conciliação são registro histórico e não podem ser alteradas ou excluídas.';
END;
