--
-- Name: fn_catalogo_homologacao_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_catalogo_homologacao_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  -- Divergência de link ou ausência de preço/escopo homologado bloqueia a oferta.
  IF NEW.status_homologacao = 'homologado'
     AND (NEW.status_link_asaas = 'desatualizado'
          OR NEW.preco_comercial_vigente IS NULL
          OR NEW.escopo_aprovado IS NULL) THEN
    NEW.status_homologacao := 'bloqueado';
    NEW.observacao_de_governanca := coalesce(NEW.observacao_de_governanca, '')
      || ' [Bloqueado por validação comercial: preço, escopo ou link divergente.]';
  END IF;

  NEW.elegivel_para_proposta := (
    NEW.ativo IS TRUE
    AND NEW.status_produto = 'ativo'
    AND NEW.status_homologacao = 'homologado'
    AND NEW.status_link_asaas IN ('validado','nao_aplicavel')
    AND NEW.archived_at IS NULL
  );
  RETURN NEW;
END;
$$;


--
-- Name: fn_ccp_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_ccp_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_demo boolean; v_code text; v_status text;
BEGIN
  SELECT demo INTO v_demo FROM public.crm_casos WHERE id = NEW.case_id;
  IF COALESCE(v_demo, false) THEN
    RAISE EXCEPTION 'Casos de demonstração não podem alimentar o motor contratual real.';
  END IF;

  IF NEW.contract_template_id IS NOT NULL THEN
    SELECT code, status INTO v_code, v_status FROM public.contract_templates WHERE id = NEW.contract_template_id;
    IF v_code IS NULL OR v_code NOT IN ('MODELO-ESTUDO','BASE-GEN-V2') THEN
      RAISE EXCEPTION 'Somente MODELO ESTUDO e a base contratual genérica v2 podem ser usados. Modelos anteriores são referência histórica.';
    END IF;
    IF v_status <> 'active' THEN
      RAISE EXCEPTION 'O modelo contratual selecionado não está ativo.';
    END IF;
  END IF;

  IF TG_OP = 'UPDATE' AND NEW.status IN ('aprovado','enviado_assinatura','assinado')
     AND OLD.status NOT IN ('aprovado','enviado_assinatura','assinado') THEN
    IF NEW.revisao_humana_por IS NULL THEN
      RAISE EXCEPTION 'Revisão humana obrigatória antes de aprovar os parâmetros contratuais.';
    END IF;
    IF EXISTS (
      SELECT 1 FROM public.contract_parameter_values v
      WHERE v.parameters_id = NEW.id AND v.archived_at IS NULL
        AND v.obrigatorio AND v.status <> 'validado'
    ) THEN
      RAISE EXCEPTION 'Existem parâmetros obrigatórios não validados. Resolva o checklist de pendências.';
    END IF;
  END IF;

  NEW.updated_at := now();
  NEW.updated_by := auth.uid();
  RETURN NEW;
END;
$$;


--
-- Name: fn_checklist_item_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_checklist_item_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.status = 'cumprido' THEN
    IF NEW.concluido_por IS NULL THEN NEW.concluido_por := auth.uid(); END IF;
    IF NEW.concluido_em IS NULL THEN NEW.concluido_em := now(); END IF;
  ELSIF NEW.status = 'nao_aplicavel' THEN
    IF NEW.observacao IS NULL OR length(btrim(NEW.observacao)) < 10 THEN
      RAISE EXCEPTION 'Marcar item como não aplicável exige justificativa com ao menos 10 caracteres.';
    END IF;
    IF NEW.concluido_por IS NULL THEN NEW.concluido_por := auth.uid(); END IF;
    IF NEW.concluido_em IS NULL THEN NEW.concluido_em := now(); END IF;
  ELSE
    NEW.concluido_por := NULL;
    NEW.concluido_em := NULL;
  END IF;
  NEW.updated_at := now();
  RETURN NEW;
END; $$;


--
-- Name: fn_checklist_pessoa_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_checklist_pessoa_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  _nome text;
  _homonimo uuid;
BEGIN
  IF NEW.pessoa_tipo IN ('titular','dependente') THEN
    IF NEW.pessoa_ref_id IS NULL THEN
      SELECT id INTO _homonimo FROM public.case_members
        WHERE case_id = NEW.case_id AND archived_at IS NULL
          AND lower(btrim(nome)) = lower(btrim(coalesce(NEW.pessoa_nome,'')))
        LIMIT 1;
      IF _homonimo IS NULL THEN
        SELECT id INTO _homonimo FROM public.case_dependents
          WHERE case_id = NEW.case_id AND archived_at IS NULL
            AND lower(btrim(nome_completo)) = lower(btrim(coalesce(NEW.pessoa_nome,'')))
          LIMIT 1;
      END IF;
      IF _homonimo IS NOT NULL THEN
        RAISE EXCEPTION 'Já existe pessoa registrada neste caso para "%": use a referência (pessoa_ref_id), não o nome.', NEW.pessoa_nome;
      END IF;
      RAISE EXCEPTION 'Checklist cadastral exige referência obrigatória à pessoa (pessoa_ref_id).';
    END IF;

    -- Nome canônico vem do cadastro referenciado, nunca de texto solto.
    IF NEW.pessoa_tipo = 'dependente' THEN
      SELECT nome_completo INTO _nome FROM public.case_dependents WHERE id = NEW.pessoa_ref_id AND case_id = NEW.case_id;
      IF _nome IS NULL THEN
        SELECT nome INTO _nome FROM public.case_members WHERE id = NEW.pessoa_ref_id AND case_id = NEW.case_id;
      END IF;
      IF _nome IS NULL THEN
        RAISE EXCEPTION 'Referência de dependente inválida para este caso.';
      END IF;
      NEW.pessoa_ref_tabela := coalesce(NEW.pessoa_ref_tabela, 'case_dependents');
    ELSE
      SELECT nome INTO _nome FROM public.case_members WHERE id = NEW.pessoa_ref_id AND case_id = NEW.case_id;
      IF _nome IS NULL THEN
        RAISE EXCEPTION 'Referência de pessoa inválida para este caso.';
      END IF;
      NEW.pessoa_ref_tabela := coalesce(NEW.pessoa_ref_tabela, 'case_members');
    END IF;

    IF NEW.cliente_id IS NOT NULL THEN
      SELECT nome INTO _nome FROM public.clientes WHERE id = NEW.cliente_id;
      IF _nome IS NULL THEN
        RAISE EXCEPTION 'Cliente canônico informado não existe.';
      END IF;
    END IF;

    IF TG_OP = 'UPDATE' AND coalesce(OLD.pessoa_nome,'') <> coalesce(_nome,'') THEN
      NEW.pessoa_nome_historico := coalesce(NEW.pessoa_nome_historico, OLD.pessoa_nome);
      IF coalesce(btrim(NEW.reconciliacao_motivo),'') = '' THEN
        RAISE EXCEPTION 'Reconciliação de pessoa exige motivo registrado.';
      END IF;
      NEW.reconciliado_em := coalesce(NEW.reconciliado_em, now());
      NEW.reconciliado_por := coalesce(NEW.reconciliado_por, auth.uid());
      INSERT INTO public.audit_logs (organization_id, user_id, acao, entidade, entidade_id, valores_anteriores, valores_posteriores, metadados)
      VALUES (NEW.organization_id, auth.uid(), 'reconciliacao_pessoa', 'checklist_cadastral', NEW.id,
              jsonb_build_object('pessoa_nome', OLD.pessoa_nome, 'pessoa_ref_id', OLD.pessoa_ref_id, 'cliente_id', OLD.cliente_id),
              jsonb_build_object('pessoa_nome', _nome, 'pessoa_ref_id', NEW.pessoa_ref_id, 'cliente_id', NEW.cliente_id),
              jsonb_build_object('motivo', NEW.reconciliacao_motivo));
    END IF;

    NEW.pessoa_nome := _nome;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: fn_citizenship_track_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_citizenship_track_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.lifecycle_status = 'vigente' THEN
    IF coalesce(NEW.versao,'') = '' OR NEW.owner_id IS NULL
       OR coalesce(NEW.criterio_aprovacao,'') = ''
       OR coalesce(NEW.evidencia_aprovacao_referencia,'') = '' THEN
      RAISE EXCEPTION 'Trilha só fica vigente com versão, responsável, critério e evidência de aprovação registrados';
    END IF;
  END IF;
  NEW.updated_at := now();
  RETURN NEW;
END; $$;


--
-- Name: fn_clause_overrides_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_clause_overrides_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
begin
  if NEW.action = 'replace' then
    if coalesce(trim(NEW.base_contract_clause_reference),'') = ''
       or coalesce(trim(NEW.change_reason),'') = ''
       or coalesce(trim(NEW.precedence_statement),'') = '' then
      raise exception 'Substituição de cláusula exige referência da cláusula-base, justificativa e declaração de precedência.';
    end if;
    NEW.requires_human_review := true;
  end if;
  if NEW.action = 'remove_not_permitted' and coalesce(trim(NEW.change_reason),'') = '' then
    raise exception 'Registrar cláusula não reproduzida exige justificativa. O contrato-base permanece íntegro.';
  end if;
  return NEW;
end $$;


--
-- Name: fn_cliente_classificacao_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_cliente_classificacao_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  _apto boolean;
BEGIN
  NEW.pais_interesse := public.pais_canonico(NEW.pais_interesse);

  IF NEW.origem IS NOT NULL AND lower(btrim(NEW.origem)) IN (
    'proposta_aprovada','proposta_enviada','aceite_verbal','contrato_assinado','pagamento_confirmado','onboarding'
  ) THEN
    RAISE EXCEPTION 'Origem inválida: % é status comercial, não origem do relacionamento.', NEW.origem;
  END IF;

  IF NEW.classificacao = 'cliente_ativo' THEN
    IF NEW.ativacao_decidida_em IS NULL OR NEW.ativacao_decidida_por IS NULL THEN
      RAISE EXCEPTION 'Cliente ativo exige decisão humana de ativação registrada (autor e data).';
    END IF;
    SELECT EXISTS (
      SELECT 1 FROM public.crm_casos c
      WHERE c.cliente_id = NEW.id
        AND c.archived_at IS NULL
        AND coalesce(c.contrato_assinado,false)
        AND coalesce(c.pagamento_confirmado,false)
    ) INTO _apto;
    IF NOT _apto THEN
      RAISE EXCEPTION 'Cliente ativo exige caso com contrato assinado e pagamento inicial confirmado.';
    END IF;
  END IF;

  IF NEW.status = 'ativo' AND NEW.classificacao <> 'cliente_ativo' THEN
    RAISE EXCEPTION 'Status ativo só é permitido para cadastro classificado como cliente ativo.';
  END IF;

  IF NEW.archived_at IS NOT NULL AND coalesce(btrim(NEW.archive_motivo),'') = '' THEN
    RAISE EXCEPTION 'Arquivamento exige motivo registrado.';
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: fn_commercial_condition_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_commercial_condition_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  p RECORD;
BEGIN
  NEW.updated_at := now();

  IF NEW.status = 'homologada' THEN
    IF NEW.homologado_por IS NULL OR btrim(NEW.homologado_por) = '' OR NEW.homologado_em IS NULL THEN
      RAISE EXCEPTION 'CONDICAO_SEM_HOMOLOGACAO: condição comercial exige responsável e data de homologação.';
    END IF;
    IF NEW.forma_pagamento IS NULL OR btrim(NEW.forma_pagamento) = '' OR NEW.parcelas IS NULL THEN
      RAISE EXCEPTION 'CONDICAO_INCOMPLETA: forma de pagamento e parcelas são obrigatórias para homologar.';
    END IF;
    IF NEW.product_catalog_id IS NULL THEN
      RAISE EXCEPTION 'CONDICAO_SEM_PRODUTO: condição homologada exige produto do catálogo.';
    END IF;
    SELECT homologado_por, homologado_em, vigencia_inicio, vigencia_fim, status_homologacao
      INTO p FROM public.product_catalog WHERE id = NEW.product_catalog_id;
    IF p.status_homologacao <> 'homologado'
       OR p.homologado_por IS NULL OR p.homologado_em IS NULL OR p.vigencia_inicio IS NULL THEN
      RAISE EXCEPTION 'PRECO_NAO_HOMOLOGADO: produto sem homologador, data ou vigência registrada — condição não pode ser homologada.';
    END IF;
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: fn_consent_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_consent_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Registro de consentimento exige usuário autenticado.';
  END IF;
  IF NOT public.is_org_member(NEW.organization_id) THEN
    RAISE EXCEPTION 'Consentimento fora da sua organização.';
  END IF;

  IF TG_OP = 'INSERT' THEN
    NEW.coletado_em := COALESCE(NEW.coletado_em, now());
    IF COALESCE(btrim(NEW.metodo_coleta), '') = '' THEN
      RAISE EXCEPTION 'Informe o método de coleta do consentimento.';
    END IF;
    IF COALESCE(btrim(NEW.versao_texto), '') = '' THEN
      RAISE EXCEPTION 'Informe a versão do texto aceito.';
    END IF;
  END IF;

  IF NEW.status = 'revogado' THEN
    NEW.revogado_em := COALESCE(NEW.revogado_em, now());
    NEW.revogado_por := COALESCE(NEW.revogado_por, auth.uid());
    IF COALESCE(btrim(NEW.revogacao_motivo), '') = '' THEN
      RAISE EXCEPTION 'A revogação exige motivo registrado.';
    END IF;
  END IF;

  IF TG_OP = 'UPDATE' AND OLD.status = 'revogado' AND NEW.status <> 'revogado' THEN
    RAISE EXCEPTION 'Consentimento revogado não pode ser reativado: registre um novo consentimento.';
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: fn_consent_revogacao_alerta(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_consent_revogacao_alerta() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.status = 'revogado' AND (TG_OP = 'INSERT' OR OLD.status IS DISTINCT FROM 'revogado') THEN
    INSERT INTO public.privacy_alerts (organization_id, case_id, client_id, consent_id, tipo, mensagem)
    VALUES (
      NEW.organization_id, NEW.case_id, NEW.client_id, NEW.id, 'consentimento_revogado',
      'Consentimento revogado em ' || to_char(COALESCE(NEW.revogado_em, now()), 'DD/MM/YYYY HH24:MI') ||
      '. Motivo: ' || COALESCE(NEW.revogacao_motivo, 'não informado') || '. Revisar acessos e uploads do caso.'
    );
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: fn_contact_meta(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_contact_meta() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  NEW.updated_at := now();
  IF NEW.archived_at IS NOT NULL AND coalesce(btrim(NEW.archive_motivo), '') = '' THEN
    RAISE EXCEPTION 'Arquivamento exige motivo.';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: fn_contract_annexes_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_contract_annexes_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
begin
  if NEW.status = 'not_applicable' and coalesce(trim(NEW.reason_not_applicable),'') = '' then
    raise exception 'Anexo marcado como não aplicável exige motivo.';
  end if;
  if NEW.status = 'signed_with_contract' then
    raise exception 'Assinatura de anexo está desabilitada nesta fase.';
  end if;
  return NEW;
end $$;


--
-- Name: fn_contract_meta(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_contract_meta() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
begin
  if TG_OP = 'INSERT' then
    NEW.created_by := coalesce(NEW.created_by, auth.uid());
    NEW.updated_by := coalesce(NEW.updated_by, auth.uid());
  else
    NEW.updated_by := coalesce(auth.uid(), NEW.updated_by);
    NEW.updated_at := now();
    if NEW.archived_at is not null and OLD.archived_at is null then
      NEW.archived_by := coalesce(NEW.archived_by, auth.uid());
      if coalesce(trim(NEW.archive_reason),'') = '' then
        raise exception 'Informe o motivo do arquivamento.';
      end if;
    end if;
  end if;
  return NEW;
end $$;


--
-- Name: fn_contract_parties_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_contract_parties_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
begin
  if NEW.signature_required and NEW.legal_capacity_status in ('minor','legal_representative_required')
     and NEW.represented_by_party_id is null then
    raise exception 'Parte menor de idade não pode assinar sem representante legal vinculado.';
  end if;
  return NEW;
end $$;


--
-- Name: fn_contract_template_uso_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_contract_template_uso_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.code IN ('MODELO-ESTUDO','BASE-GEN-V2') THEN
    NEW.uso_permitido := 'geracao';
  ELSE
    NEW.uso_permitido := 'historico_inutilizavel_para_geracao';
    IF NEW.status = 'active' THEN
      RAISE EXCEPTION 'Modelo histórico (%). Não é instrumento contratual aplicável e não pode ficar ativo para geração.', NEW.code;
    END IF;
    IF NEW.notes_internal IS NULL OR btrim(NEW.notes_internal) = '' THEN
      NEW.notes_internal := 'Referência histórica preservada para auditoria; não é instrumento contratual aplicável.';
    END IF;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: fn_contract_versions_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_contract_versions_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare v_next int;
begin
  if TG_OP = 'INSERT' then
    select coalesce(max(version_number),0) + 1 into v_next
      from public.contract_versions where contract_id = NEW.contract_id;
    NEW.version_number := v_next;
    if v_next > 1 and coalesce(trim(NEW.change_summary),'') = '' then
      raise exception 'A partir da versão 2 é obrigatório informar o resumo das alterações.';
    end if;
    if NEW.status <> 'working' then
      raise exception 'Nova versão deve iniciar como versão de trabalho.';
    end if;
  else
    if OLD.status in ('approved_for_send','signed_snapshot','superseded') then
      if NEW.generated_content is distinct from OLD.generated_content
         or NEW.rendered_file_path is distinct from OLD.rendered_file_path
         or NEW.rendered_file_hash is distinct from OLD.rendered_file_hash
         or NEW.version_number is distinct from OLD.version_number then
        raise exception 'Versão congelada é imutável. Crie uma nova versão de trabalho.';
      end if;
      if OLD.status <> 'superseded' and NEW.status not in (OLD.status,'superseded','archived','signed_snapshot') then
        raise exception 'Transição de versão não permitida a partir de versão congelada.';
      end if;
    end if;
    if OLD.frozen_at is not null and NEW.generated_content is distinct from OLD.generated_content then
      raise exception 'Conteúdo congelado não pode ser editado.';
    end if;
    if OLD.rendered_file_path is not null and NEW.rendered_file_path is distinct from OLD.rendered_file_path
       and OLD.status <> 'working' then
      raise exception 'Arquivo de versão não pode ser substituído no mesmo caminho.';
    end if;
  end if;
  return NEW;
end $$;


--
-- Name: fn_contracts_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_contracts_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare v_seq int; v_parent record; v_ver record; n int;
begin
  if TG_OP = 'INSERT' then
    select count(*) + 1 into v_seq from public.contracts where organization_id = NEW.organization_id;
    NEW.contract_number := to_char(now(),'YYYY') || '-' ||
      case NEW.contract_type when 'contract_base' then 'CB' when 'contract_complement' then 'CC' else 'AD' end ||
      '-' || lpad(v_seq::text, 4, '0');
    NEW.status := coalesce(NEW.status, 'draft');
    if NEW.status not in ('draft','pending_data') then
      raise exception 'Novo instrumento deve iniciar em rascunho.';
    end if;
  else
    if NEW.contract_number is distinct from OLD.contract_number then
      raise exception 'A numeração do contrato é gerada pelo sistema e não pode ser alterada.';
    end if;
    if OLD.status = 'signed' and NEW.status not in ('signed','archived') then
      raise exception 'Contrato assinado é imutável; use complementar ou aditivo.';
    end if;
    if OLD.status = 'signed' and (
         NEW.title is distinct from OLD.title
      or NEW.purpose_summary is distinct from OLD.purpose_summary
      or NEW.scope_summary is distinct from OLD.scope_summary
      or NEW.exclusions_summary is distinct from OLD.exclusions_summary
      or NEW.contract_type is distinct from OLD.contract_type
      or NEW.parent_contract_id is distinct from OLD.parent_contract_id) then
      raise exception 'Conteúdo de contrato assinado não pode ser alterado.';
    end if;
    if OLD.status = 'approved_for_send' and NEW.status = 'sent' then
      raise exception 'Envio de contrato está desabilitado nesta fase (integração não configurada).';
    end if;
    if NEW.status = 'archived' and OLD.status <> 'archived' and coalesce(trim(NEW.archive_reason),'') = '' then
      raise exception 'Arquivamento exige motivo.';
    end if;
  end if;

  -- Gate de assinatura
  if NEW.status = 'signed' and (TG_OP = 'INSERT' or OLD.status is distinct from 'signed') then
    -- versão do instrumento
    select * into v_ver from public.contract_versions
      where contract_id = NEW.id and archived_at is null
      and (NEW.current_version_id is null or id = NEW.current_version_id)
      order by version_number desc limit 1;
    if v_ver is null or v_ver.generated_content = '{}'::jsonb then
      raise exception 'Assinatura bloqueada: não há versão do instrumento com conteúdo gerado.';
    end if;
    -- arquivo ou registro de assinatura externa
    if coalesce(trim(NEW.signature_reference),'') = ''
       and coalesce(trim(NEW.provider_envelope_id),'') = ''
       and coalesce(trim(v_ver.rendered_file_path),'') = '' then
      raise exception 'Assinatura bloqueada: informe o arquivo assinado ou o registro da assinatura externa.';
    end if;
    -- data de assinatura
    if NEW.signed_at is null then
      raise exception 'Assinatura bloqueada: data de assinatura é obrigatória.';
    end if;
    -- partes qualificadas
    select count(*) into n from public.contract_parties
      where contract_id = NEW.id and active and archived_at is null and role = 'provider'
        and coalesce(trim(person_name),'') <> '' and coalesce(trim(document_number),'') <> '';
    if n = 0 then
      raise exception 'Assinatura bloqueada: parte prestadora não qualificada.';
    end if;
    select count(*) into n from public.contract_parties
      where contract_id = NEW.id and active and archived_at is null and role = 'contracting_client'
        and coalesce(trim(person_name),'') <> '' and coalesce(trim(document_number),'') <> '';
    if n = 0 then
      raise exception 'Assinatura bloqueada: parte contratante não qualificada.';
    end if;
    select count(*) into n from public.contract_parties
      where contract_id = NEW.id and active and archived_at is null and signature_required
        and legal_capacity_status in ('minor','legal_representative_required') and represented_by_party_id is null;
    if n > 0 then
      raise exception 'Assinatura bloqueada: parte sem representante legal qualificado.';
    end if;
    -- escopo aprovado
    select count(*) into n from public.contract_scope_items
      where contract_id = NEW.id and archived_at is null
        and category = 'contracted_scope' and status = 'included';
    if n = 0 then
      raise exception 'Assinatura bloqueada: escopo contratado não aprovado.';
    end if;
    -- condição comercial validada
    if NEW.financial_gate_status not in ('confirmed','not_applicable')
       or NEW.financial_change_status = 'pending_review' then
      raise exception 'Assinatura bloqueada: condição comercial não validada.';
    end if;
    -- registro de revisão humana
    if v_ver.review_decision <> 'approved' or v_ver.reviewed_by is null or v_ver.reviewed_at is null then
      raise exception 'Assinatura bloqueada: revisão humana da versão não registrada.';
    end if;
    if NEW.review_owner_user_id is null then
      raise exception 'Assinatura bloqueada: responsável pela revisão humana não definido.';
    end if;
    select count(*) into n from public.contract_validation_results
      where contract_id = NEW.id and archived_at is null
        and severity = 'blocking' and status = 'open';
    if n > 0 then
      raise exception 'Assinatura bloqueada: existem % pendência(s) bloqueante(s) em aberto.', n;
    end if;
  end if;

  -- relacionamento base/complementar/aditivo
  if NEW.contract_type = 'contract_base' then
    if NEW.parent_contract_id is not null then
      raise exception 'Contrato-base não pode ter contrato-pai.';
    end if;
    NEW.relationship_type := 'independent';
  else
    if NEW.parent_contract_id is null or coalesce(trim(NEW.base_contract_reference),'') = '' then
      raise exception 'Instrumento complementar ou aditivo exige contrato-base vinculado e referência do contrato-base.';
    end if;
    select * into v_parent from public.contracts where id = NEW.parent_contract_id;
    if v_parent is null or v_parent.organization_id <> NEW.organization_id then
      raise exception 'Contrato-base deve pertencer à mesma organização.';
    end if;
    if v_parent.contract_type <> 'contract_base' then
      raise exception 'O contrato-pai deve ser um contrato-base.';
    end if;
    if NEW.relationship_type not in ('complement','amendment','replacement_reference') then
      raise exception 'Tipo de relacionamento inválido para instrumento derivado.';
    end if;
  end if;
  return NEW;
end $$;


--
-- Name: fn_contracts_signature_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_contracts_signature_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_arquivo text;
begin
  if NEW.status = 'signed' and (TG_OP = 'INSERT' or OLD.status is distinct from 'signed') then
    if NEW.signed_at is null then
      raise exception 'Contrato assinado exige data de assinatura.';
    end if;
    if NEW.current_version_id is null then
      raise exception 'Contrato assinado exige versão vigente registrada.';
    end if;
    select rendered_file_path into v_arquivo from public.contract_versions where id = NEW.current_version_id;
    if coalesce(btrim(v_arquivo),'') = '' then
      if coalesce(btrim(NEW.external_signature_justification),'') = ''
         or NEW.external_signature_approved_by is null
         or NEW.external_signature_approved_at is null then
        raise exception 'Sem arquivo da versão, a assinatura externa exige justificativa aprovada por admin.';
      end if;
      if not public.has_org_role(NEW.organization_id, 'admin'::public.app_role)
         and not public.has_role(NEW.external_signature_approved_by, 'admin'::public.app_role) then
        raise exception 'A justificativa de assinatura externa precisa ser aprovada por um admin.';
      end if;
    end if;
  end if;
  return NEW;
end $$;


--
-- Name: fn_conversion_event_imutavel(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_conversion_event_imutavel() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
