--
-- Name: fn_crm_no_delete(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_crm_no_delete() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  RAISE EXCEPTION 'Exclusão física proibida. Use arquivamento lógico com motivo.';
END;
$$;


--
-- Name: fn_data_origin_coerencia(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_data_origin_coerencia() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE tem_demo boolean;
BEGIN
  IF NEW.data_origin IS NULL OR btrim(NEW.data_origin) = '' THEN
    NEW.data_origin := 'real';
  END IF;

  SELECT EXISTS (
    SELECT 1 FROM information_schema.columns
    WHERE table_schema = 'public' AND table_name = TG_TABLE_NAME AND column_name = 'demo'
  ) INTO tem_demo;

  IF tem_demo THEN
    IF NEW.data_origin = 'fixture_demo' THEN
      NEW := jsonb_populate_record(NEW, jsonb_build_object('demo', true));
    ELSIF (to_jsonb(NEW) ->> 'demo')::boolean IS TRUE AND NEW.data_origin = 'real' THEN
      NEW.data_origin := 'fixture_demo';
    END IF;
  END IF;

  RETURN NEW;
END $$;


--
-- Name: fn_decisao_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_decisao_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.status IN ('publicada','substituida') THEN
    IF COALESCE(btrim(NEW.contexto), '') = '' THEN
      RAISE EXCEPTION 'Publicar decisão exige contexto.';
    END IF;
    IF COALESCE(btrim(NEW.decisao), '') = '' THEN
      RAISE EXCEPTION 'Publicar decisão exige a decisão tomada.';
    END IF;
    IF COALESCE(btrim(NEW.impacto), '') = '' THEN
      RAISE EXCEPTION 'Publicar decisão exige o impacto esperado.';
    END IF;
    IF NEW.responsavel_user_id IS NULL AND COALESCE(btrim(NEW.responsavel_nome), '') = '' THEN
      RAISE EXCEPTION 'Publicar decisão exige responsável.';
    END IF;
    IF NEW.data_decisao IS NULL THEN
      RAISE EXCEPTION 'Publicar decisão exige a data da decisão.';
    END IF;
  END IF;

  IF NEW.archived_at IS NOT NULL AND COALESCE(btrim(NEW.archive_motivo), '') = '' THEN
    RAISE EXCEPTION 'Arquivar decisão exige motivo.';
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: fn_deck_referencia_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_deck_referencia_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $_$
DECLARE v_codigo text;
BEGIN
  IF NEW.deck_referencia_interna IS NULL OR btrim(NEW.deck_referencia_interna) = '' THEN
    RETURN NEW;
  END IF;

  NEW.deck_referencia_interna := upper(btrim(NEW.deck_referencia_interna));

  IF NEW.case_id IS NULL THEN
    RAISE EXCEPTION 'Referência de deck exige um caso já existente. A proposta não cria identificador de caso.';
  END IF;

  SELECT codigo INTO v_codigo FROM public.crm_casos WHERE id = NEW.case_id;
  IF v_codigo IS NULL THEN
    RAISE EXCEPTION 'Referência de deck aponta para caso inexistente.';
  END IF;

  IF NEW.deck_referencia_interna !~ ('^DECK-CANVA-' || upper(v_codigo) || '-V\d+$') THEN
    RAISE EXCEPTION 'Referência de deck deve seguir DECK-CANVA-%-v[N].', v_codigo;
  END IF;

  RETURN NEW;
END;
$_$;


--
-- Name: fn_deliverable_publicacao_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_deliverable_publicacao_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.approval_status = 'published' THEN
    IF NEW.approved_by IS NULL OR NEW.approved_at IS NULL THEN
      RAISE EXCEPTION 'Publicação exige aprovação humana registrada.';
    END IF;
    IF NEW.summary_approved IS NULL OR btrim(NEW.summary_approved) = '' THEN
      RAISE EXCEPTION 'Publicação exige resumo sanitizado aprovado.';
    END IF;
    IF NEW.published_at IS NULL THEN NEW.published_at := now(); END IF;
  END IF;
  NEW.updated_at := now();
  RETURN NEW;
END $$;


--
-- Name: fn_document_request_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_document_request_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_status_ok text[] := ARRAY['nao_solicitado','a_preparar','solicitado','aguardando_pagamento_cliente','aguardando_cliente','aguardando_instituicao','recebido','em_revisao','validado_internamente','divergente','insuficiente','requer_complemento','requer_retificacao','requer_traducao_apostila','nao_localizado','cancelado','nao_aplicavel'];
  v_pos_pedido text[] := ARRAY['solicitado','aguardando_cliente','aguardando_instituicao','recebido','em_revisao','validado_internamente','divergente','insuficiente','requer_complemento','requer_retificacao','requer_traducao_apostila','nao_localizado'];
  v_exige_acao text[] := ARRAY['aguardando_cliente','aguardando_instituicao','divergente','nao_localizado','requer_retificacao'];
  v_evid uuid;
BEGIN
  IF NEW.organization_id IS NULL THEN
    RAISE EXCEPTION 'ORGANIZACAO_OBRIGATORIA';
  END IF;

  IF NOT (NEW.status = ANY(v_status_ok)) THEN
    RAISE EXCEPTION 'STATUS_FORA_DO_DICIONARIO: %', NEW.status;
  END IF;
  IF NOT (NEW.priority = ANY(ARRAY['baixa','media','alta','critica'])) THEN
    RAISE EXCEPTION 'PRIORIDADE_FORA_DO_DICIONARIO: %', NEW.priority;
  END IF;
  IF NOT (NEW.access_level = ANY(ARRAY['restrito','equipe_do_caso','cliente_autorizado'])) THEN
    RAISE EXCEPTION 'NIVEL_ACESSO_FORA_DO_DICIONARIO: %', NEW.access_level;
  END IF;
  IF NOT (NEW.client_approval_status = ANY(ARRAY['nao_aplicavel','aguardando_aprovacao','aprovado','recusado'])) THEN
    RAISE EXCEPTION 'APROVACAO_CLIENTE_FORA_DO_DICIONARIO: %', NEW.client_approval_status;
  END IF;
  IF NOT (NEW.request_type = ANY(ARRAY['certidao','busca_arquivo','copia_processo','traducao','apostilamento','retificacao','documento_familia','outro'])) THEN
    RAISE EXCEPTION 'TIPO_SOLICITACAO_FORA_DO_DICIONARIO: %', NEW.request_type;
  END IF;

  IF NEW.research_person_id IS NULL AND coalesce(btrim(NEW.full_name_text),'') = '' THEN
    RAISE EXCEPTION 'NOME_COMPLETO_OBRIGATORIO: vincule uma pessoa cadastrada ou informe o nome completo.';
  END IF;
  IF NEW.research_person_id IS NOT NULL THEN
    NEW.full_name_text := NULL;
  END IF;

  IF NEW.status = ANY(v_pos_pedido) AND NEW.requested_at IS NULL THEN
    RAISE EXCEPTION 'DATA_PEDIDO_OBRIGATORIA a partir de Solicitado.';
  END IF;
  IF NEW.status = 'recebido' AND NEW.received_at IS NULL THEN
    RAISE EXCEPTION 'DATA_RECEBIMENTO_OBRIGATORIA para Recebido.';
  END IF;

  IF NEW.status = ANY(v_exige_acao) THEN
    IF coalesce(btrim(NEW.next_action),'') = '' OR NEW.next_action_due IS NULL OR NEW.responsible_user_id IS NULL THEN
      RAISE EXCEPTION 'PROXIMA_ACAO_OBRIGATORIA: informe próxima ação, prazo e responsável para a situação %.', NEW.status;
    END IF;
  END IF;

  IF NEW.estimated_external_cost IS NOT NULL AND NEW.estimated_external_cost < 0 THEN
    RAISE EXCEPTION 'CUSTO_EXTERNO_INVALIDO: previsão não pode ser negativa.';
  END IF;

  IF TG_OP = 'UPDATE' THEN
    NEW.created_at := OLD.created_at;
    NEW.created_by := OLD.created_by;
    NEW.organization_id := OLD.organization_id;
  ELSE
    NEW.created_by := coalesce(NEW.created_by, auth.uid());
  END IF;
  NEW.updated_by := auth.uid();
  NEW.updated_at := now();

  IF NEW.archived_at IS NOT NULL AND coalesce(btrim(NEW.archived_reason),'') = '' THEN
    RAISE EXCEPTION 'ARQUIVAMENTO_EXIGE_MOTIVO';
  END IF;

  -- Recebido cria ou vincula evidência com fluxo "recebida"
  IF NEW.status = 'recebido' AND NEW.evidence_id IS NULL THEN
    INSERT INTO public.evidences (
      organization_id, case_id, research_person_id, source_id,
      evidence_type, evidence_nature, title_internal, description_internal,
      reference_date, access_level, workflow_status, data_origin, created_by, updated_by
    ) VALUES (
      NEW.organization_id, NEW.case_id, NEW.research_person_id, NEW.source_id,
      NEW.document_type, 'documental_oficial',
      'Documento recebido: ' || NEW.document_type,
      'Criada automaticamente pelo recebimento da solicitação documental.',
      NEW.received_at, NEW.access_level, 'recebida', NEW.data_origin, auth.uid(), auth.uid()
    ) RETURNING id INTO v_evid;
    NEW.evidence_id := v_evid;
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: fn_document_request_pos(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_document_request_pos() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_exige_acao text[] := ARRAY['aguardando_cliente','aguardando_instituicao','divergente','nao_localizado','requer_retificacao'];
BEGIN
  IF NEW.status = ANY(v_exige_acao)
     AND (TG_OP = 'INSERT' OR OLD.status IS DISTINCT FROM NEW.status) THEN

    INSERT INTO public.case_alerts (
      organization_id, case_id, tipo, titulo, detalhe, criticidade, status, due_at, data_origin, created_by, updated_by
    ) VALUES (
      NEW.organization_id, NEW.case_id, 'documento_solicitacao',
      'Solicitação documental exige ação: ' || NEW.document_type,
      NEW.next_action, 'alta', 'aberto', NEW.next_action_due::timestamptz,
      NEW.data_origin, auth.uid(), auth.uid()
    );

    IF NEW.status = 'aguardando_cliente' THEN
      INSERT INTO public.communication_queue (
        organization_id, case_id, acao_codigo, assunto, corpo_rascunho,
        target_audience, suggested_channel, visibility, requires_human_approval, status,
        observacao_interna, data_origin, created_by, updated_by
      ) VALUES (
        NEW.organization_id, NEW.case_id, 'documento_aguardando_cliente',
        'Pendência de documento',
        'Rascunho interno: precisamos do documento ' || NEW.document_type || '. Próxima ação combinada: ' || coalesce(NEW.next_action,'') || '.',
        'cliente', 'whatsapp', 'interno', true, 'rascunho',
        'Gerado pela solicitação documental. Nenhum envio automático.',
        NEW.data_origin, auth.uid(), auth.uid()
      );
    END IF;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: fn_documento_liberacao_audit(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_documento_liberacao_audit() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.liberado_cliente = true AND COALESCE(OLD.liberado_cliente, false) = false THEN
    INSERT INTO public.audit_logs (organization_id, user_id, acao, entidade, entidade_id, metadados)
    VALUES (NEW.organization_id, auth.uid(), 'entrega_liberada_cliente', 'documents', NEW.id,
            jsonb_build_object('case_id', NEW.case_id, 'titulo', NEW.titulo,
                               'entrega', NEW.entrega_cliente, 'liberado_em', NEW.liberado_em));
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: fn_documents_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_documents_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_cliente uuid;
  v_portal boolean := false;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Envio de documentos exige usuário autenticado.';
  END IF;

  v_portal := (NEW.origem = 'cliente')
              AND NEW.case_id IS NOT NULL
              AND public.portal_caso_permitido(NEW.case_id)
              AND NEW.client_id IS NOT DISTINCT FROM public.portal_meu_cliente();

  IF NOT v_portal AND NOT public.is_org_member(NEW.organization_id) THEN
    RAISE EXCEPTION 'Documento fora da sua organização.';
  END IF;

  IF TG_OP = 'INSERT' THEN
    NEW.carregado_por := COALESCE(NEW.carregado_por, auth.uid());
    NEW.carregado_em := COALESCE(NEW.carregado_em, now());
    IF NEW.case_id IS NOT NULL THEN
      SELECT cliente_id INTO v_cliente FROM public.crm_casos WHERE id = NEW.case_id;
      NEW.client_id := COALESCE(NEW.client_id, v_cliente);
    END IF;

    IF v_portal THEN
      NEW.status := 'pendente_de_revisao';
      NEW.visibilidade := 'interno_restrito';
      NEW.categoria := 'interno';
      NEW.entrega_cliente := false;
      NEW.liberado_em := NULL;
      NEW.liberado_por := NULL;
      NEW.revisado_em := NULL;
      NEW.revisado_por := NULL;
    ELSE
      IF NEW.categoria IN ('identificacao','certidao','documento_civil','documento_financeiro')
         AND NOT public.consentimento_ativo(NEW.case_id, NEW.client_id)
         AND NOT public.consentimento_dispensado(NEW.case_id, NEW.client_id) THEN
        RAISE EXCEPTION 'Categoria sensível bloqueada: registre consentimento de tratamento de dados ou uma exceção formal aprovada.';
      END IF;
    END IF;
  END IF;

  IF TG_OP = 'UPDATE' THEN
    IF NOT public.is_org_member(NEW.organization_id) THEN
      RAISE EXCEPTION 'Apenas a equipe interna pode alterar documentos.';
    END IF;
    IF NEW.storage_path IS DISTINCT FROM OLD.storage_path AND NEW.storage_path IS NOT NULL THEN
      NEW.versao := COALESCE(OLD.versao, 1) + 1;
    END IF;
    IF NEW.status = 'liberado' AND OLD.status IS DISTINCT FROM 'liberado' THEN
      IF NEW.visibilidade <> 'cliente_quando_liberado' THEN
        RAISE EXCEPTION 'Só documentos com visibilidade "cliente quando liberado" podem ser liberados ao cliente.';
      END IF;
      IF NOT public.is_staff_ativo(NEW.organization_id) THEN
        RAISE EXCEPTION 'Liberação de entrega exige usuário interno ativo.';
      END IF;
      NEW.liberado_em := now();
      NEW.liberado_por := auth.uid();
    END IF;
  END IF;

  NEW.liberado_cliente := (NEW.visibilidade = 'cliente_quando_liberado' AND NEW.status = 'liberado');
  RETURN NEW;
END;
$$;


--
-- Name: fn_drive_queue_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_drive_queue_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE c public.crm_casos%ROWTYPE;
BEGIN
  SELECT * INTO c FROM public.crm_casos WHERE id = NEW.case_id;
  IF NEW.stage_trigger = 'oportunidade' AND NEW.status <> 'blocked' THEN
    RAISE EXCEPTION 'Oportunidade não provisiona dossiê: item permanece bloqueado.';
  END IF;
  IF NEW.stage_trigger = 'confirmacao_formal' AND NEW.status NOT IN ('blocked','cancelled') THEN
    RAISE EXCEPTION 'Confirmação formal só cria item de fila bloqueado.';
  END IF;
  IF NEW.status IN ('ready_for_review','approved','executed')
     AND NOT (coalesce(c.contrato_assinado,false) AND coalesce(c.pagamento_confirmado,false)) THEN
    RAISE EXCEPTION 'Fila do Drive exige contrato assinado e pagamento confirmado.';
  END IF;
  IF NEW.status IN ('approved','executed') AND NEW.approval_required AND NEW.approved_by IS NULL THEN
    RAISE EXCEPTION 'Execução exige confirmação humana registrada.';
  END IF;
  IF NEW.status = 'executed' AND coalesce(btrim(NEW.external_result_reference), '') = '' THEN
    RAISE EXCEPTION 'Execução registrada exige referência do resultado externo.';
  END IF;
  NEW.updated_at := now();
  RETURN NEW;
END; $$;


--
-- Name: fn_estado_caso(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_estado_caso() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
begin
  if TG_OP = 'UPDATE' and not public.transicao_permitida('caso', OLD.status, NEW.status) then
    raise exception 'Transição de caso não permitida: % -> %', OLD.status, NEW.status;
  end if;
  if NEW.status = 'ativo' then
    if NEW.cliente_id is null then raise exception 'Caso ativo exige cliente vinculado.'; end if;
    if NEW.responsavel_id is null then raise exception 'Caso ativo exige responsável.'; end if;
    if NEW.tipo_servico is null or length(trim(NEW.tipo_servico)) = 0 then raise exception 'Caso ativo exige tipo de serviço.'; end if;
    NEW.data_ativacao := coalesce(NEW.data_ativacao, now());
  end if;
  return NEW;
end $$;


