--
-- Name: fn_estado_tarefa(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_estado_tarefa() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
begin
  if TG_OP = 'UPDATE' and not public.transicao_permitida('tarefa', OLD.status, NEW.status) then
    raise exception 'Transição de tarefa não permitida: % -> %', OLD.status, NEW.status;
  end if;

  if NEW.status = 'bloqueada' then
    NEW.bloqueio := true;
    if NEW.motivo_bloqueio is null or length(trim(NEW.motivo_bloqueio)) < 5 then
      raise exception 'Tarefa bloqueada exige motivo do bloqueio.';
    end if;
    NEW.bloqueado_em := coalesce(NEW.bloqueado_em, now());
    NEW.desbloqueado_em := null;
  end if;

  if TG_OP = 'UPDATE' and OLD.status = 'bloqueada' and NEW.status <> 'bloqueada' then
    if NEW.desbloqueado_em is null or NEW.desbloqueio_por is null
       or NEW.desbloqueio_justificativa is null or length(trim(NEW.desbloqueio_justificativa)) < 5 then
      raise exception 'Desbloqueio exige data, responsável e justificativa registrados.';
    end if;
    NEW.bloqueio := false;
  end if;

  if NEW.status = 'concluida' then
    if NEW.bloqueio then raise exception 'Tarefa bloqueada não pode ser concluída sem registrar o desbloqueio.'; end if;
    if NEW.bloqueado_em is not null and (NEW.desbloqueado_em is null or NEW.desbloqueio_por is null
        or NEW.desbloqueio_justificativa is null or length(trim(NEW.desbloqueio_justificativa)) < 5) then
      raise exception 'Tarefa que esteve bloqueada exige desbloqueio, responsável e justificativa antes da conclusão.';
    end if;
    NEW.concluida_em := coalesce(NEW.concluida_em, now());
  end if;

  return NEW;
end $$;


--
-- Name: fn_evidence_estado_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_evidence_estado_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.workflow_status NOT IN (
    'recebida','registrada','em_revisao','validada_internamente','divergente','insuficiente',
    'requer_complemento','requer_retificacao','requer_traducao_ou_apostila',
    'rejeitada_ou_inaplicavel','aprovada_para_entrega_cliente','publicada_ao_cliente'
  ) THEN
    RAISE EXCEPTION 'Situação de evidência inválida: %', NEW.workflow_status;
  END IF;

  -- Validação interna nunca é conclusão jurídica.
  IF NEW.workflow_status = 'validada_internamente' THEN
    NEW.legal_review_status := coalesce(NEW.legal_review_status, 'nao_aplicavel');
  END IF;

  -- Publicação ao cliente exige aprovação prévia explícita e revisor registrado.
  IF NEW.workflow_status = 'publicada_ao_cliente'
     AND coalesce(OLD.workflow_status,'') <> 'aprovada_para_entrega_cliente' THEN
    RAISE EXCEPTION 'Evidência só é publicada após aprovação explícita para entrega ao cliente.';
  END IF;

  IF NEW.workflow_status IN ('validada_internamente','aprovada_para_entrega_cliente')
     AND NEW.reviewed_by IS NULL THEN
    RAISE EXCEPTION 'Informe o revisor responsável antes de validar ou aprovar a evidência.';
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: fn_evidence_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_evidence_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  ordem_ant int;
  ordem_nova int;
  tem_registro boolean;
BEGIN
  -- Busca negativa é evidência válida, mas exige fonte, data e próxima ação
  IF NEW.evidence_nature = 'busca_negativa' THEN
    IF coalesce(btrim(NEW.negative_search_source), '') = ''
       OR NEW.negative_search_date IS NULL
       OR coalesce(btrim(NEW.negative_search_next_action), '') = '' THEN
      RAISE EXCEPTION 'Busca negativa exige fonte consultada, data da consulta e próxima ação possível.';
    END IF;
  END IF;

  -- Fonte colaborativa não valida sozinha vínculo, direito, cidadania ou relação
  IF NEW.evidence_nature = 'colaborativa_familiar' THEN
    IF NEW.epistemic_validation_status = 'VALIDADO_POR_DOCUMENTO' THEN
      RAISE EXCEPTION 'Fonte colaborativa não valida sozinha vínculo, direito, cidadania ou relação: exige documento.';
    END IF;
    IF NEW.confidence_level = 'ALTO' THEN
      RAISE EXCEPTION 'Fonte colaborativa não atinge confiança ALTA sem validação documental.';
    END IF;
  END IF;

  -- Validado por documento exige documento e revisão nominal
  IF NEW.epistemic_validation_status = 'VALIDADO_POR_DOCUMENTO' THEN
    IF NEW.evidence_nature NOT IN ('documental_oficial','documental_nao_oficial') THEN
      RAISE EXCEPTION 'Validação por documento exige evidência de natureza documental.';
    END IF;
    IF NEW.reviewed_by IS NULL OR NEW.reviewed_at IS NULL THEN
      RAISE EXCEPTION 'Validação por documento exige responsável pela revisão e data da revisão.';
    END IF;
  END IF;

  ordem_ant := CASE coalesce(OLD.confidence_level, 'INICIAL')
                 WHEN 'INICIAL' THEN 0 WHEN 'BAIXO' THEN 1 WHEN 'MEDIO' THEN 2 ELSE 3 END;
  ordem_nova := CASE NEW.confidence_level
                 WHEN 'INICIAL' THEN 0 WHEN 'BAIXO' THEN 1 WHEN 'MEDIO' THEN 2 ELSE 3 END;

  IF TG_OP = 'INSERT' THEN
    IF NEW.confidence_level IN ('MEDIO','ALTO') THEN
      RAISE EXCEPTION 'Evidência nasce com confiança INICIAL ou BAIXO: elevação exige revisão registrada.';
    END IF;
    RETURN NEW;
  END IF;

  IF ordem_nova > ordem_ant THEN
    -- Sem salto automático de INICIAL para ALTO
    IF ordem_ant = 0 AND ordem_nova = 3 THEN
      RAISE EXCEPTION 'Salto de confiança INICIAL para ALTO não é permitido: eleve por etapas com revisão.';
    END IF;
    IF NEW.reviewed_by IS NULL OR NEW.reviewed_at IS NULL THEN
      RAISE EXCEPTION 'Elevação de confiança exige responsável e data da revisão.';
    END IF;
    SELECT EXISTS (
      SELECT 1 FROM public.evidence_validations v
       WHERE v.evidence_id = NEW.id
         AND v.confianca_nova = NEW.confidence_level
         AND v.revisado_em >= now() - interval '10 minutes'
    ) INTO tem_registro;
    IF NOT tem_registro THEN
      RAISE EXCEPTION 'Elevação de confiança exige justificativa registrada no histórico de validação.';
    END IF;
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: fn_evidencia_pesquisa_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_evidencia_pesquisa_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.status = 'validada' THEN
    IF NEW.pesquisador_id IS NULL THEN
      RAISE EXCEPTION 'Evidência validada exige pesquisador responsável.';
    END IF;
    IF coalesce(btrim(NEW.fonte), '') = '' THEN
      RAISE EXCEPTION 'Evidência validada exige fonte ou origem.';
    END IF;
    IF length(coalesce(btrim(NEW.justificativa), '')) < 5 THEN
      RAISE EXCEPTION 'Evidência validada exige justificativa da validação.';
    END IF;
  END IF;

  IF NEW.status = 'descartada' AND length(coalesce(btrim(NEW.justificativa), '')) < 5 THEN
    RAISE EXCEPTION 'Evidência descartada exige motivo do descarte.';
  END IF;

  IF TG_OP = 'UPDATE' AND NEW.status IS DISTINCT FROM OLD.status
     AND NEW.status IN ('validada','descartada','inconclusiva') THEN
    NEW.revisado_em := coalesce(NEW.revisado_em, now());
  END IF;

  IF NEW.caso_id IS NOT NULL AND NOT pode_pesquisar_caso(NEW.caso_id) THEN
    RAISE EXCEPTION 'Pesquisadores só editam evidências de casos sob sua responsabilidade.';
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: fn_finding_projecao_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_finding_projecao_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.confidence NOT IN ('baixa','media','alta') THEN
    RAISE EXCEPTION 'Nível de confiança inválido: %', NEW.confidence;
  END IF;
  IF NEW.client_projection_status NOT IN ('nao_projetado','rascunho_sanitizado','aprovado_interno','publicado_cliente') THEN
    RAISE EXCEPTION 'Situação de projeção inválida: %', NEW.client_projection_status;
  END IF;
  IF NEW.client_projection_status IN ('aprovado_interno','publicado_cliente')
     AND NEW.validation_status <> 'validado' THEN
    RAISE EXCEPTION 'Achado precisa estar validado internamente antes de qualquer projeção ao cliente.';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: fn_g02_evento_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_g02_evento_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.validation_status = 'confirmado'
     AND NEW.evidence_id IS NULL AND NEW.source_id IS NULL THEN
    RAISE EXCEPTION 'Evento confirmado exige evidência ou fonte vinculada.';
  END IF;
  IF NEW.start_date IS NOT NULL AND NEW.end_date IS NOT NULL AND NEW.end_date < NEW.start_date THEN
    RAISE EXCEPTION 'Data final do evento não pode ser anterior à data inicial.';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: fn_g02_meta(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_g02_meta() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    NEW.created_by := coalesce(NEW.created_by, auth.uid());
    NEW.updated_by := coalesce(NEW.updated_by, auth.uid());
  ELSE
    NEW.created_at := OLD.created_at;
    NEW.created_by := OLD.created_by;
    NEW.updated_at := now();
    NEW.updated_by := coalesce(auth.uid(), NEW.updated_by);
    IF NEW.archived_at IS NOT NULL AND OLD.archived_at IS NULL THEN
      IF NEW.archive_reason IS NULL OR length(btrim(NEW.archive_reason)) < 5 THEN
        RAISE EXCEPTION 'Arquivamento exige motivo (archive_reason) com pelo menos 5 caracteres.';
      END IF;
      NEW.archived_by := coalesce(NEW.archived_by, auth.uid());
    END IF;
  END IF;
  RETURN NEW;
END $$;


--
-- Name: fn_g02_modulo_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_g02_modulo_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.status_verificacao = 'confirmado'
     AND NEW.evidence_id IS NULL AND NEW.source_id IS NULL THEN
    RAISE EXCEPTION 'Registro histórico confirmado exige evidência ou fonte vinculada.';
  END IF;
  IF NEW.periodo_inicio IS NOT NULL AND NEW.periodo_fim IS NOT NULL
     AND NEW.periodo_fim < NEW.periodo_inicio THEN
    RAISE EXCEPTION 'Período final não pode ser anterior ao inicial.';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: fn_g02_perfil_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_g02_perfil_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.status_verificacao = 'confirmado' AND NEW.evidence_id IS NULL THEN
    RAISE EXCEPTION 'Perfil genealógico só pode ser confirmado com evidência vinculada (evidence_id).';
  END IF;
  IF NEW.status_verificacao = 'confirmado' THEN
    NEW.verified_at := coalesce(NEW.verified_at, now());
    NEW.verified_by := coalesce(NEW.verified_by, auth.uid());
  ELSE
    NEW.verified_at := NULL;
    NEW.verified_by := NULL;
  END IF;
  IF NEW.nascimento_data IS NOT NULL AND NEW.morte_data IS NOT NULL
     AND NEW.morte_data < NEW.nascimento_data THEN
    RAISE EXCEPTION 'Data de morte não pode ser anterior à data de nascimento.';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: fn_g02_relacao_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_g02_relacao_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.status_pesquisa IN ('com_suporte','confirmado')
     AND NEW.evidence_id IS NULL AND NEW.source_id IS NULL THEN
    RAISE EXCEPTION 'Relação só sai de "a confirmar" com evidência ou fonte vinculada.';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: fn_g02_variante_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_g02_variante_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  IF length(btrim(coalesce(NEW.variante,''))) < 2 THEN
    RAISE EXCEPTION 'Variante de nome exige texto com pelo menos 2 caracteres.';
  END IF;
  IF NEW.estado_validacao = 'validada' AND NEW.evidence_id IS NULL AND NEW.source_id IS NULL THEN
    RAISE EXCEPTION 'Variante validada exige evidência ou fonte vinculada.';
  END IF;
  IF TG_OP = 'UPDATE' AND NEW.person_id <> OLD.person_id THEN
    RAISE EXCEPTION 'Variante de nome não pode ser transferida para outra pessoa.';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: fn_g03_meta(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_g03_meta() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    NEW.created_by := coalesce(NEW.created_by, auth.uid());
  ELSE
    NEW.created_by := OLD.created_by;
    NEW.created_at := OLD.created_at;
  END IF;
  NEW.updated_by := coalesce(auth.uid(), NEW.updated_by);
  NEW.updated_at := now();
  IF NEW.archived_at IS NOT NULL AND coalesce(length(btrim(NEW.archived_reason)), 0) < 5 THEN
    RAISE EXCEPTION 'Arquivamento exige motivo com pelo menos 5 caracteres.';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: fn_g07_estimate_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_g07_estimate_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_org uuid;
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'EXCLUSAO_FISICA_BLOQUEADA: previsão de terceiro só pode ser arquivada.';
  END IF;

  SELECT organization_id INTO v_org FROM public.crm_casos WHERE id = NEW.case_id;
  IF v_org IS NULL OR v_org <> NEW.organization_id THEN
    RAISE EXCEPTION 'CASO_FORA_DA_ORGANIZACAO: previsão precisa pertencer ao caso da mesma organização.';
  END IF;

  IF NEW.quantity IS NULL OR NEW.quantity <= 0 THEN
    RAISE EXCEPTION 'QUANTIDADE_INVALIDA: informe quantidade maior que zero.';
  END IF;
  IF NEW.unit_price_min IS NOT NULL AND NEW.unit_price_max IS NOT NULL AND NEW.unit_price_min > NEW.unit_price_max THEN
    RAISE EXCEPTION 'FAIXA_INVALIDA: preço mínimo não pode ser maior que o máximo.';
  END IF;
  IF NEW.estimated_wait_days_min IS NOT NULL AND NEW.estimated_wait_days_max IS NOT NULL
     AND NEW.estimated_wait_days_min > NEW.estimated_wait_days_max THEN
    RAISE EXCEPTION 'PRAZO_INVALIDO: prazo mínimo não pode ser maior que o máximo.';
  END IF;

  -- Totais são derivados: previsão, nunca lançamento financeiro.
  NEW.estimated_total_min := round(coalesce(NEW.unit_price_min, 0) * NEW.quantity, 2);
  NEW.estimated_total_max := round(coalesce(NEW.unit_price_max, NEW.unit_price_min, 0) * NEW.quantity, 2);

  IF NEW.client_approval_status = 'aprovada' AND coalesce(btrim(NEW.estimate_source),'') = '' THEN
    RAISE EXCEPTION 'ORIGEM_DA_ESTIMATIVA_OBRIGATORIA: informe a origem antes de registrar aprovação.';
  END IF;

  NEW.updated_at := now();
  RETURN NEW;
END; $$;


--
-- Name: fn_g07_institution_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_g07_institution_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'EXCLUSAO_FISICA_BLOQUEADA: instituição só pode ser arquivada.';
  END IF;
  IF coalesce(btrim(NEW.name),'') = '' THEN
    RAISE EXCEPTION 'INSTITUICAO_SEM_NOME: informe o nome da instituição.';
  END IF;
  IF NEW.update_status = 'verificado' AND (NEW.last_verified_at IS NULL OR coalesce(btrim(NEW.contact_source),'') = '') THEN
    RAISE EXCEPTION 'VERIFICACAO_INCOMPLETA: contato verificado exige fonte do contato e data da verificação.';
  END IF;
  NEW.updated_at := now();
  RETURN NEW;
END; $$;


--
-- Name: fn_g07_plan_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_g07_plan_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_org uuid;
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'EXCLUSAO_FISICA_BLOQUEADA: item do plano de ação só pode ser arquivado ou cancelado.';
  END IF;

  SELECT organization_id INTO v_org FROM public.crm_casos WHERE id = NEW.case_id;
  IF v_org IS NULL OR v_org <> NEW.organization_id THEN
    RAISE EXCEPTION 'CASO_FORA_DA_ORGANIZACAO: item precisa pertencer ao caso da mesma organização.';
  END IF;

  IF coalesce(btrim(NEW.reason),'') = '' THEN
    RAISE EXCEPTION 'ACAO_SEM_MOTIVO: descreva por que a ação é necessária.';
  END IF;

  -- Aprovação humana é padrão e não pode ser desligada.
  IF NEW.requires_human_approval IS DISTINCT FROM true THEN
    RAISE EXCEPTION 'APROVACAO_HUMANA_OBRIGATORIA: toda ação do plano exige revisão humana.';
  END IF;

  -- Instituição é referência reutilizável da mesma organização.
  IF NEW.institution_id IS NOT NULL THEN
    IF NOT EXISTS (SELECT 1 FROM public.institutions i WHERE i.id = NEW.institution_id AND i.organization_id = NEW.organization_id) THEN
      RAISE EXCEPTION 'INSTITUICAO_INVALIDA: use uma instituição cadastrada na mesma organização.';
    END IF;
  END IF;

  -- Canal externo exige instituição de referência (não duplicar contato na tarefa).
  IF NEW.suggested_channel <> 'desk_only' AND NEW.institution_id IS NULL AND NEW.action_type IN ('contato_institucional','visita_presencial','solicitacao_documento') THEN
    RAISE EXCEPTION 'CONTATO_SEM_INSTITUICAO: vincule a instituição de referência em vez de repetir contatos na tarefa.';
  END IF;

  -- Aguardando resposta exige rechecagem.
  IF NEW.status = 'aguardando_resposta' AND NEW.next_check_at IS NULL THEN
    RAISE EXCEPTION 'RECHECAGEM_OBRIGATORIA: item aguardando resposta exige data de próxima rechecagem.';
  END IF;

  -- Ação realizada exige registro interno do resultado.
  IF NEW.status IN ('realizada','concluida') AND coalesce(btrim(NEW.contact_result_internal),'') = '' THEN
    RAISE EXCEPTION 'RESULTADO_INTERNO_OBRIGATORIO: registre o resultado interno da ação realizada.';
  END IF;
  IF NEW.status IN ('realizada','concluida') AND NEW.contacted_at IS NULL THEN
    NEW.contacted_at := now();
  END IF;

  -- Estimativa de terceiro não é cobrança nem caixa do Clube.
  IF NEW.estimated_cost_amount IS NOT NULL AND NEW.estimated_cost_amount < 0 THEN
    RAISE EXCEPTION 'ESTIMATIVA_INVALIDA: previsão de custo não pode ser negativa.';
  END IF;
  IF NEW.expense_approval_status = 'aprovada' AND NEW.payer = 'nao_definido' THEN
    RAISE EXCEPTION 'PAGADOR_NAO_DEFINIDO: defina quem paga antes de aprovar a previsão.';
  END IF;

  NEW.updated_at := now();
  RETURN NEW;
END; $$;


--
-- Name: fn_g07_plan_pos(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_g07_plan_pos() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_comm uuid;
BEGIN
  -- Regra: prioridade crítica com prazo hoje/vencido gera alerta imediato no Desk.
  IF NEW.priority = 'critica'
     AND NEW.due_date IS NOT NULL
     AND NEW.due_date <= current_date
     AND NEW.status NOT IN ('concluida','cancelada')
     AND NEW.archived_at IS NULL THEN
    IF NOT EXISTS (
      SELECT 1 FROM public.case_alerts a
      WHERE a.case_id = NEW.case_id AND a.tipo = 'plano_acao_critico'
        AND a.status = 'pending' AND a.detalhe = NEW.id::text
    ) THEN
      INSERT INTO public.case_alerts (organization_id, case_id, tipo, criticidade, titulo, detalhe, status, due_at, data_origin)
      VALUES (NEW.organization_id, NEW.case_id, 'plano_acao_critico', 'critico',
              'Ação crítica de pesquisa vencida ou para hoje: ' || NEW.titulo,
              NEW.id::text, 'pending', (NEW.due_date::timestamptz), NEW.data_origin);
    END IF;
  END IF;

  -- Regra: comunicação externa só existe como rascunho na fila, com aprovação humana.
  IF NEW.communication_draft IS NOT NULL AND btrim(NEW.communication_draft) <> ''
     AND NEW.communication_queue_id IS NULL THEN
    INSERT INTO public.communication_queue
      (organization_id, case_id, acao_codigo, target_audience, visibility, suggested_channel,
       assunto, corpo_rascunho, status, requires_human_approval, observacao_interna, data_origin)
    VALUES (NEW.organization_id, NEW.case_id, 'g07_plano_acao', 'interno_tatiana', 'internal_only',
            CASE WHEN NEW.suggested_channel = 'desk_only' THEN 'desk_only' ELSE NEW.suggested_channel END,
            NEW.titulo, NEW.communication_draft, 'draft_created', true,
            'Rascunho gerado pelo plano de ação G-07. Nenhum envio automático.', NEW.data_origin)
    RETURNING id INTO v_comm;
    UPDATE public.research_action_plan_items SET communication_queue_id = v_comm WHERE id = NEW.id;
  END IF;

  -- Regra: ação realizada registra interação imutável de CRM (sem contato externo automático).
  IF NEW.status IN ('realizada','concluida')
     AND (TG_OP = 'INSERT' OR OLD.status IS DISTINCT FROM NEW.status) THEN
    INSERT INTO public.crm_interactions
      (organization_id, case_id, origem, origem_id, canal, direcao, resumo_interno, ocorrido_em, registrado_por, data_origin)
    VALUES (NEW.organization_id, NEW.case_id, 'plano_acao_pesquisa', NEW.id,
            NEW.suggested_channel, 'interno', NEW.contact_result_internal,
            coalesce(NEW.contacted_at, now()), NEW.updated_by, NEW.data_origin);
  END IF;

  RETURN NULL;
END; $$;


--
-- Name: fn_g08_access_log_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_g08_access_log_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  txt text := lower(coalesce(NEW.resumo_interno, ''));
BEGIN
  IF txt ~ '(token|bearer |api[_ -]?key|senha|password|secret|authorization|payload|"?access_token"?)' THEN
    RAISE EXCEPTION 'Registro de acesso não aceita token, credencial ou payload bruto.';
  END IF;
  IF length(coalesce(NEW.resumo_interno,'')) > 500 THEN
    RAISE EXCEPTION 'Registro de acesso aceita apenas resumo interno curto, nunca resposta bruta da fonte.';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: fn_g08_source_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_g08_source_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.estagio_maturidade = 'CATALOGADA'
     AND NEW.status_integracao NOT IN ('sem_integracao','bloqueada') THEN
    RAISE EXCEPTION 'Fonte apenas catalogada não é integração: documente e avalie antes de mudar a situação de integração.';
  END IF;

  IF (NEW.estagio_maturidade = 'TERMOS_A_CONFIRMAR' OR NEW.status_documentacao = 'termos_a_confirmar')
     AND NEW.estagio_maturidade IN ('ELEGIVEL_PARA_PILOTO','PILOTO_INTERNO','HOMOLOGADA_MANUAL','HOMOLOGADA_API') THEN
    RAISE EXCEPTION 'Fonte com termos a confirmar não avança para piloto nem homologação.';
  END IF;

  IF NEW.estagio_maturidade IN ('ELEGIVEL_PARA_PILOTO','PILOTO_INTERNO','HOMOLOGADA_MANUAL','HOMOLOGADA_API')
     AND NEW.status_documentacao <> 'completa' THEN
    RAISE EXCEPTION 'Avanço de maturidade exige documentação completa da fonte.';
  END IF;

  IF NEW.estagio_maturidade = 'HOMOLOGADA_API' AND NEW.modo_de_uso_permitido <> 'api_validada' THEN
    RAISE EXCEPTION 'Homologação por API exige modo de uso permitido api_validada. Fonte manual não equivale a API homologada.';
  END IF;

  IF NEW.estagio_maturidade = 'HOMOLOGADA_MANUAL' AND NEW.modo_de_uso_permitido NOT IN ('manual','metadados_linkout','parceria') THEN
    RAISE EXCEPTION 'Homologação manual exige modo de uso manual, metadados/linkout ou parceria.';
  END IF;

  IF NEW.scraping_status = 'nao_aplicavel' AND NEW.modo_de_uso_permitido = 'api_validada' AND NEW.status_documentacao <> 'completa' THEN
    RAISE EXCEPTION 'Modo API validada exige documentação completa e parecer registrado.';
  END IF;

  IF NEW.estagio_maturidade IN ('RESTRITA','DESCONTINUADA') AND NEW.status_integracao NOT IN ('bloqueada','sem_integracao') THEN
    RAISE EXCEPTION 'Fonte restrita ou descontinuada não pode permanecer com integração ativa.';
  END IF;

  NEW.updated_at := now();
  NEW.updated_by := auth.uid();
  RETURN NEW;
END;
$$;


--
-- Name: fn_gf_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_gf_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_org uuid; v_termo text;
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'EXCLUSAO_FISICA_BLOQUEADA: achados genealógicos só podem ser arquivados.';
  END IF;

  SELECT organization_id INTO v_org FROM public.crm_casos WHERE id = NEW.case_id;
  IF v_org IS NULL OR v_org <> NEW.organization_id THEN
    RAISE EXCEPTION 'CASO_FORA_DA_ORGANIZACAO: achado precisa pertencer ao caso da mesma organização.';
  END IF;

  -- Regra 1: achado exige ao menos uma fonte ou evidência.
  IF coalesce(array_length(NEW.evidence_links, 1), 0) = 0
     AND coalesce(array_length(NEW.source_links, 1), 0) = 0 THEN
    RAISE EXCEPTION 'ACHADO_SEM_EVIDENCIA: informe ao menos uma evidência ou fonte antes de gravar o achado.';
  END IF;

  -- Regra 2: resultado negativo exige fonte consultada, data e próxima ação alternativa.
  IF NEW.finding_type = 'resultado_negativo_pesquisa' THEN
    IF coalesce(array_length(NEW.source_links, 1), 0) = 0
       OR NEW.negative_source_consulted_at IS NULL
       OR coalesce(btrim(NEW.negative_next_action), '') = '' THEN
      RAISE EXCEPTION 'RESULTADO_NEGATIVO_INCOMPLETO: registre fonte consultada, data da consulta e próxima ação alternativa.';
    END IF;
  END IF;

  -- Regra 3: validado internamente ≠ conclusão jurídica. Elegibilidade só após validação humana.
  IF NEW.eligible_for_client_deliverable AND NEW.validation_status <> 'validado_internamente' THEN
    RAISE EXCEPTION 'ELEGIBILIDADE_SEM_VALIDACAO: só achado validado internamente pode ser elegível para entrega ao cliente.';
  END IF;
  IF NEW.client_deliverable_id IS NOT NULL AND NOT NEW.eligible_for_client_deliverable THEN
    RAISE EXCEPTION 'ENTREGA_SEM_ELEGIBILIDADE: vincule a entrega apenas após marcar o achado como elegível.';
  END IF;

  -- Regra: atualização de árvore/timeline exige revisão interna concluída.
  IF (NEW.tree_impact = 'aplicado' OR NEW.timeline_impact = 'aplicado')
     AND NEW.validation_status <> 'validado_internamente' THEN
    RAISE EXCEPTION 'IMPACTO_SEM_REVISAO: árvore e linha do tempo só recebem impacto aplicado após validação interna.';
  END IF;

  -- Hipótese nunca se apresenta como fato confirmado.
  IF NEW.finding_type = 'hipotese_pesquisa' AND NEW.validation_status = 'validado_internamente' THEN
    RAISE EXCEPTION 'HIPOTESE_NAO_VALIDAVEL: hipótese de pesquisa não pode ser marcada como validada; converta o tipo quando houver documento.';
  END IF;

  IF NEW.validation_status = 'validado_internamente' AND NEW.validated_at IS NULL THEN
    NEW.validated_at := now();
  END IF;
  IF NEW.validation_status <> 'validado_internamente' THEN
    NEW.validated_at := NULL;
  END IF;

  v_termo := public.fn_linguagem_proibida(NEW.planning_impact);
  IF v_termo IS NOT NULL THEN
    RAISE EXCEPTION 'LINGUAGEM_PROIBIDA: expressão "%" não é aceita (determinista/terapêutica).', v_termo;
  END IF;

  NEW.updated_at := now();
  NEW.updated_by := auth.uid();
  IF TG_OP = 'INSERT' THEN NEW.created_by := auth.uid(); END IF;
  IF TG_OP = 'UPDATE' THEN
    NEW.created_at := OLD.created_at;
    NEW.created_by := OLD.created_by;
    IF NEW.archived_at IS NOT NULL AND OLD.archived_at IS NULL THEN
      NEW.archived_by := auth.uid();
    END IF;
  END IF;
  RETURN NEW;
END $$;


--
-- Name: fn_governanca_versao(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_governanca_versao() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  anterior jsonb;
  atual jsonb;
  titulo_item text;
BEGIN
  anterior := to_jsonb(OLD) - 'updated_at' - 'versao' - 'change_resumo';
  atual := to_jsonb(NEW) - 'updated_at' - 'versao' - 'change_resumo';

  IF anterior IS DISTINCT FROM atual THEN
    NEW.versao := OLD.versao + 1;
    NEW.updated_at := now();

    titulo_item := CASE TG_TABLE_NAME
      WHEN 'artifact_register' THEN (to_jsonb(NEW) ->> 'nome_original')
      ELSE (to_jsonb(NEW) ->> 'titulo')
    END;

    INSERT INTO public.change_log (
      organization_id, entidade, entidade_id, titulo, versao_anterior, versao_nova, resumo, snapshot_anterior, autor_user_id
    ) VALUES (
      NEW.organization_id, TG_TABLE_NAME, NEW.id, titulo_item, OLD.versao, NEW.versao,
      COALESCE(NULLIF(btrim(NEW.change_resumo), ''), 'Alteração registrada automaticamente.'),
      to_jsonb(OLD), auth.uid()
    );
    NEW.change_resumo := NULL;
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: fn_guard_ativacao(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_guard_ativacao() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare v_pend text;
begin
  if (NEW.ativo and not coalesce(OLD.ativo,false)) or (NEW.status = 'ativo' and coalesce(OLD.status,'') <> 'ativo') then
    if not (public.has_org_role(NEW.organization_id,'admin') or public.has_org_role(NEW.organization_id,'operacoes')) then
      raise exception 'Somente admin ou operações podem ativar um caso.';
    end if;
    select string_agg(p.label, '; ') into v_pend from public.case_activation_pendencias(NEW.id) p;
    if v_pend is not null then
      raise exception 'Ativação bloqueada. Requisitos pendentes: %', v_pend;
    end if;
    NEW.ativo := true;
    NEW.status := 'ativo';
    NEW.ativado_em := coalesce(NEW.ativado_em, now());
    NEW.ativado_por := coalesce(NEW.ativado_por, auth.uid());
    NEW.data_ativacao := coalesce(NEW.data_ativacao, now());
  end if;

  if TG_OP = 'UPDATE' and NEW.status = 'pausado' and OLD.status <> 'pausado' then
    if NEW.suspenso_motivo is null or length(trim(NEW.suspenso_motivo)) < 10 then
      raise exception 'Suspensão exige motivo com no mínimo 10 caracteres.';
    end if;
    NEW.ativo := false;
    NEW.suspenso_em := now();
    NEW.suspenso_por := auth.uid();
  end if;

  return NEW;
end $$;


--
-- Name: fn_guard_cobranca(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_guard_cobranca() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare c record;
begin
  if NEW.caso_id is null then return NEW; end if;
  if TG_OP = 'UPDATE' and NEW.caso_id is not distinct from OLD.caso_id
     and NEW.status is not distinct from OLD.status
     and NEW.valor is not distinct from OLD.valor then
    return NEW;
  end if;
  select * into c from public.crm_casos where id = NEW.caso_id;
  if c is null then return NEW; end if;
  if not coalesce(c.contrato_assinado,false) then
    raise exception 'Cobrança bloqueada: o caso não possui contrato assinado.';
  end if;
  return NEW;
end $$;


--
-- Name: fn_guard_consentimento_ativacao(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_guard_consentimento_ativacao() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.status = 'ativo' AND OLD.status IS DISTINCT FROM 'ativo' THEN
    IF NOT public.consentimento_ativo(NEW.id, NEW.cliente_id)
       AND NOT public.consentimento_dispensado(NEW.id, NEW.cliente_id) THEN
      RAISE EXCEPTION 'Ativação bloqueada: o caso não possui consentimento de tratamento de dados ativo nem exceção formal aprovada.';
    END IF;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: fn_guard_pesquisa_externa(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_guard_pesquisa_externa() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare c record;
begin
  if NEW.caso_id is null then return NEW; end if;
  if coalesce(NEW.origem,'interna') in ('interna','cliente') then return NEW; end if;
  if TG_OP = 'UPDATE' and NEW.origem is not distinct from OLD.origem
     and NEW.caso_id is not distinct from OLD.caso_id then
    return NEW;
  end if;
  select * into c from public.crm_casos where id = NEW.caso_id;
  if c is null then return NEW; end if;
  if not coalesce(c.contrato_assinado,false) then
    raise exception 'Pesquisa externa bloqueada: o caso não possui contrato assinado.';
  end if;
  return NEW;
end $$;


--
-- Name: fn_hipotese_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_hipotese_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.status = 'confirmada' THEN
    IF NOT EXISTS (
      SELECT 1 FROM public.evidencias e
      WHERE e.hypothesis_id = NEW.id
        AND e.status = 'validada'
        AND e.archived_at IS NULL
    ) THEN
      RAISE EXCEPTION 'Hipótese só pode ser confirmada com ao menos uma evidência validada vinculada.';
    END IF;
    IF length(coalesce(btrim(NEW.justificativa), '')) < 5 THEN
      RAISE EXCEPTION 'Confirmar hipótese exige justificativa registrada.';
    END IF;
  END IF;

  IF NEW.status = 'refutada' AND length(coalesce(btrim(NEW.justificativa), '')) < 5 THEN
    RAISE EXCEPTION 'Refutar hipótese exige justificativa registrada.';
  END IF;

  IF TG_OP = 'UPDATE' AND NEW.status IS DISTINCT FROM OLD.status THEN
    NEW.revisado_em := now();
  END IF;

  NEW.updated_at := now();
  RETURN NEW;
END;
$$;


--
-- Name: fn_institutional_profile_events_imutavel(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_institutional_profile_events_imutavel() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  RAISE EXCEPTION 'Eventos do perfil institucional são append-only.';
END;
$$;


--
-- Name: fn_integracao_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_integracao_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  faltando text[];
BEGIN
  NEW.updated_at := now();

  -- Ativação: exige admin, confirmação explícita, responsável e mapeamento completo.
  IF NEW.status = 'ativa' AND (TG_OP = 'INSERT' OR OLD.status IS DISTINCT FROM 'ativa') THEN
    IF staff_meu_papel(NEW.organization_id) IS DISTINCT FROM 'admin' THEN
      RAISE EXCEPTION 'Somente admin pode ativar uma integração.';
    END IF;
    IF NEW.ativacao_confirmacao IS NULL OR upper(btrim(NEW.ativacao_confirmacao)) <> 'ATIVAR' THEN
      RAISE EXCEPTION 'Ativação exige confirmação explícita do admin.';
    END IF;
    IF NEW.owner_user_id IS NULL THEN
      RAISE EXCEPTION 'Defina o responsável interno antes de ativar.';
    END IF;
    SELECT array_agg(c) INTO faltando
    FROM unnest(NEW.campos_obrigatorios) AS c
    WHERE COALESCE(btrim(NEW.field_map ->> c), '') = '';
    IF faltando IS NOT NULL THEN
      RAISE EXCEPTION 'Campos obrigatórios sem mapeamento: %', array_to_string(faltando, ', ');
    END IF;
    NEW.modo_simulado := false;
    NEW.ativada_em := now();
    NEW.ativada_por := auth.uid();
  END IF;

  -- Fora de "ativa" nunca sai do modo simulado.
  IF NEW.status <> 'ativa' THEN
    NEW.modo_simulado := true;
    NEW.ativacao_confirmacao := NULL;
  END IF;

  IF NEW.status = 'pausada' AND COALESCE(btrim(NEW.pausa_motivo), '') = '' THEN
    RAISE EXCEPTION 'Pausar exige motivo.';
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: fn_integration_run_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_integration_run_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  integ public.integrations%ROWTYPE;
  novas integer;
BEGIN
  SELECT * INTO integ FROM public.integrations WHERE id = NEW.integration_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Integração inexistente.';
  END IF;
  IF integ.organization_id <> NEW.organization_id THEN
    RAISE EXCEPTION 'Integração de outra organização.';
  END IF;

  IF NEW.ambiente = 'producao' AND (integ.status <> 'ativa' OR integ.modo_simulado) THEN
    RAISE EXCEPTION 'Integração desligada, em teste ou pausada: chamada externa bloqueada.';
  END IF;

  IF NEW.tentativa > integ.retry_max THEN
    RAISE EXCEPTION 'Limite de tentativas da integração excedido.';
  END IF;

  IF NEW.resultado = 'erro' THEN
    novas := integ.falhas_consecutivas + 1;
    UPDATE public.integrations
       SET falhas_consecutivas = novas,
           ultima_execucao_em = now(),
           ultima_execucao_status = 'erro',
           status = CASE WHEN novas >= integ.retry_max AND status IN ('ativa','teste') THEN 'com_erro' ELSE status END,
           modo_simulado = CASE WHEN novas >= integ.retry_max THEN true ELSE modo_simulado END,
           updated_at = now()
     WHERE id = integ.id;

    IF novas >= integ.retry_max THEN
      INSERT INTO public.integration_review_queue (organization_id, integration_id, run_id, motivo, tentativas)
      VALUES (NEW.organization_id, NEW.integration_id, NEW.id,
              COALESCE(NEW.mensagem, 'Falhas consecutivas acima do limite.'), novas);
    END IF;
  ELSIF NEW.resultado = 'ok' THEN
    UPDATE public.integrations
       SET falhas_consecutivas = 0,
           ultima_execucao_em = now(),
           ultima_execucao_status = 'ok',
           updated_at = now()
     WHERE id = integ.id;
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: fn_integration_run_pre(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_integration_run_pre() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  ok boolean;
BEGIN
  SELECT (status = 'ativa' AND NOT modo_simulado) INTO ok
  FROM public.integrations WHERE id = NEW.integration_id;
  IF NEW.ambiente = 'producao' AND COALESCE(ok, false) = false THEN
    RAISE EXCEPTION 'Execução em produção bloqueada: integração não está ativa.';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: fn_invoice_liberacao(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_invoice_liberacao() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.liberada_cliente = true AND COALESCE(OLD.liberada_cliente, false) = false THEN
    IF NOT public.is_staff_ativo(NEW.organization_id) THEN
      RAISE EXCEPTION 'Liberar fatura ao cliente exige usuário interno ativo.';
    END IF;
    NEW.liberada_em := now();
    NEW.liberada_por := auth.uid();
  END IF;
  IF NEW.liberada_cliente = false AND COALESCE(OLD.liberada_cliente, false) = true THEN
    NEW.liberada_em := NULL;
    NEW.liberada_por := NULL;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: fn_invoice_liberacao_audit(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_invoice_liberacao_audit() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.liberada_cliente IS DISTINCT FROM COALESCE(OLD.liberada_cliente, false) THEN
    INSERT INTO public.audit_logs (organization_id, user_id, acao, entidade, entidade_id, metadados)
    VALUES (NEW.organization_id, auth.uid(),
            CASE WHEN NEW.liberada_cliente THEN 'fatura_liberada_cliente' ELSE 'fatura_ocultada_cliente' END,
            'invoices', NEW.id,
            jsonb_build_object('case_id', NEW.case_id, 'numero', NEW.numero));
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: fn_invoices_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_invoices_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if not public.can_write_financeiro(NEW.organization_id) then
    raise exception 'Alteração financeira exige papel financeiro ou admin.';
  end if;
  if TG_OP = 'UPDATE' and OLD.status = 'paga' and NEW.valor is distinct from OLD.valor then
    raise exception 'Fatura paga não pode ter o valor editado. Registre um ajuste de fatura.';
  end if;
  if NEW.status = 'emitida' and NEW.emitida_em is null then
    NEW.emitida_em := now();
  end if;
  if NEW.status = 'paga' and NEW.paga_em is null then
    NEW.paga_em := now();
  end if;
  return NEW;
end $$;


