END $$;


--
-- Name: fn_le_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_le_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_org uuid; v_termo text; v_campo text;
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'EXCLUSAO_FISICA_BLOQUEADA: encontros de linhagem só podem ser arquivados.';
  END IF;

  SELECT organization_id INTO v_org FROM public.crm_casos WHERE id = NEW.case_id;
  IF v_org IS NULL OR v_org <> NEW.organization_id THEN
    RAISE EXCEPTION 'CASO_FORA_DA_ORGANIZACAO: encontro precisa pertencer ao caso da mesma organização.';
  END IF;

  -- Regra: duas linhas e evidência de cada lado, salvo marco de origem.
  IF NEW.encounter_type <> 'marco_de_origem' THEN
    IF NEW.lineage_path_a_id IS NULL OR NEW.lineage_path_b_id IS NULL THEN
      RAISE EXCEPTION 'ENCONTRO_SEM_DUAS_LINHAS: informe as duas linhas de linhagem envolvidas.';
    END IF;
    IF NEW.lineage_path_a_id = NEW.lineage_path_b_id THEN
      RAISE EXCEPTION 'ENCONTRO_LINHAS_IGUAIS: as duas linhas precisam ser distintas.';
    END IF;
    IF coalesce(array_length(NEW.evidence_links_a, 1), 0) = 0
       OR coalesce(array_length(NEW.evidence_links_b, 1), 0) = 0 THEN
      RAISE EXCEPTION 'ENCONTRO_SEM_EVIDENCIA_POR_LADO: cada linha precisa de ao menos uma evidência.';
    END IF;
  ELSIF coalesce(array_length(NEW.evidence_links_a, 1), 0) = 0 THEN
    RAISE EXCEPTION 'MARCO_SEM_EVIDENCIA: marco de origem exige ao menos uma evidência.';
  END IF;

  -- Hipótese não se apresenta como conexão confirmada.
  IF NEW.encounter_type = 'conexao_confirmada'
     AND (NEW.confidence_internal IN ('hipotese', 'indicio') OR NEW.validation_status <> 'validado_internamente') THEN
    RAISE EXCEPTION 'CONEXAO_NAO_COMPROVADA: conexão confirmada exige validação interna e confiança documental; registre como hipótese/convergência.';
  END IF;

  -- Aprovação exige disclaimer, resumo aprovado e validação interna.
  IF NEW.approval_status = 'aprovado' THEN
    IF NOT NEW.disclaimer_obrigatorio THEN
      RAISE EXCEPTION 'ENCONTRO_SEM_DISCLAIMER: aprovação exige disclaimer obrigatório marcado.';
    END IF;
    IF coalesce(btrim(NEW.resumo_aprovado_cliente), '') = '' THEN
      RAISE EXCEPTION 'ENCONTRO_SEM_RESUMO_APROVADO: escreva o resumo sanitizado antes de aprovar.';
    END IF;
    IF NEW.validation_status <> 'validado_internamente' THEN
      RAISE EXCEPTION 'APROVACAO_SEM_VALIDACAO: valide internamente antes de aprovar.';
    END IF;
  END IF;

  IF NEW.client_deliverable_id IS NOT NULL AND NEW.approval_status <> 'aprovado' THEN
    RAISE EXCEPTION 'PROJECAO_SEM_APROVACAO: encontro sem aprovação não cria projeção para o cliente.';
  END IF;

  IF (NEW.tree_impact = 'aplicado' OR NEW.timeline_impact = 'aplicado')
     AND NEW.validation_status <> 'validado_internamente' THEN
    RAISE EXCEPTION 'IMPACTO_SEM_REVISAO: árvore e linha do tempo só recebem impacto aplicado após validação interna.';
  END IF;

  FOREACH v_campo IN ARRAY ARRAY[
    coalesce(NEW.title_client, ''), coalesce(NEW.resumo_aprovado_cliente, ''),
    coalesce(NEW.repertorios_narrativos, ''), coalesce(NEW.memoria_familiar, '')
  ] LOOP
    v_termo := public.fn_linguagem_proibida(v_campo);
    IF v_termo IS NOT NULL THEN
      RAISE EXCEPTION 'LINGUAGEM_PROIBIDA: expressão "%" não é aceita em texto do cliente (determinista/terapêutica/traço psicológico).', v_termo;
    END IF;
  END LOOP;

  NEW.updated_at := now();
  NEW.updated_by := auth.uid();
  IF TG_OP = 'INSERT' THEN NEW.created_by := auth.uid(); END IF;
  IF TG_OP = 'UPDATE' THEN
    NEW.created_at := OLD.created_at;
    NEW.created_by := OLD.created_by;
    IF NEW.archived_at IS NOT NULL AND OLD.archived_at IS NULL THEN
      NEW.archived_by := auth.uid();
    END IF;
  END IF;
  RETURN NEW;
END $$;


--
-- Name: fn_lead_case_id_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_lead_case_id_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE v_org uuid;
BEGIN
  IF NEW.case_id IS NULL THEN
    RETURN NEW;
  END IF;

  SELECT organization_id INTO v_org FROM public.crm_casos WHERE id = NEW.case_id;
  IF v_org IS NULL THEN
    RAISE EXCEPTION 'Lead só pode ser vinculado a um caso já aberto.';
  END IF;
  IF v_org <> NEW.organization_id THEN
    RAISE EXCEPTION 'Lead e caso precisam pertencer à mesma organização.';
  END IF;

  IF lower(coalesce(NEW.estagio, '')) <> 'ganho' THEN
    RAISE EXCEPTION 'Lead em triagem/negociação não recebe identificador de caso. Registre a abertura formal (lead ganho) antes de vincular.';
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: fn_lead_codigo(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_lead_codigo() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  ano text := to_char(coalesce(NEW.created_at, now()), 'YYYY');
  seq int;
BEGIN
  IF TG_OP = 'UPDATE' THEN
    IF OLD.codigo IS NOT NULL AND NEW.codigo IS DISTINCT FROM OLD.codigo THEN
      NEW.codigo := OLD.codigo;
    END IF;
    RETURN NEW;
  END IF;

  SELECT coalesce(max((regexp_replace(codigo, '^CA-LEAD-\d{4}-', ''))::int), 0) + 1
    INTO seq
    FROM public.leads
   WHERE organization_id = NEW.organization_id
     AND codigo ~ ('^CA-LEAD-' || ano || '-\d+$');

  NEW.codigo := 'CA-LEAD-' || ano || '-' || lpad(seq::text, 4, '0');
  RETURN NEW;
END;
$_$;


--
-- Name: fn_lead_desk_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_lead_desk_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  ativo boolean;
BEGIN
  ativo := NEW.archived_at IS NULL
       AND coalesce(NEW.eixo_comercial, '') NOT IN ('perdido', 'encerrado_sem_aderencia');

  IF ativo THEN
    IF coalesce(NEW.area_responsavel, '') = '' OR coalesce(NEW.responsavel_nome, '') = ''
       OR coalesce(NEW.proxima_acao, '') = '' OR NEW.proxima_acao_em IS NULL THEN
      RAISE EXCEPTION 'Lead ativo exige área responsável, responsável nominal, próxima ação e data da próxima ação.';
    END IF;
  END IF;

  IF NEW.eixo_comercial IN ('discovery_realizada', 'diagnostico_em_elaboracao', 'proposta_enviada', 'negociacao') THEN
    IF coalesce(NEW.discovery_resultado, '') = '' OR NOT coalesce(NEW.resumo_validado, false)
       OR NEW.proxima_acao_em IS NULL THEN
      RAISE EXCEPTION 'Discovery realizada exige resultado da Discovery, resumo validado e próxima ação datada.';
    END IF;
  END IF;

  IF NEW.eixo_comercial IN ('proposta_enviada', 'negociacao') THEN
    IF coalesce(NEW.proposta_link_interno, '') = '' OR coalesce(NEW.responsavel_nome, '') = '' THEN
      RAISE EXCEPTION 'Proposta enviada exige link interno da proposta e responsável nominal.';
    END IF;
  END IF;

  IF NEW.eixo_comercial = 'perdido' AND coalesce(NEW.motivo_perda, '') = '' THEN
    RAISE EXCEPTION 'Lead perdido exige motivo de perda.';
  END IF;

  IF NEW.eixo_formalizacao IN ('contrato_assinado', 'pagamento_inicial_confirmado', 'cliente_ativo', 'onboarding_iniciado', 'caso_ativo')
     AND coalesce(NEW.contrato_link_interno, '') = '' THEN
    RAISE EXCEPTION 'Contrato assinado exige link interno do contrato.';
  END IF;

  IF NEW.eixo_formalizacao IN ('pagamento_inicial_confirmado', 'cliente_ativo', 'onboarding_iniciado', 'caso_ativo')
     AND coalesce(NEW.asaas_evento_referencia, '') = '' THEN
    RAISE EXCEPTION 'Pagamento inicial confirmado exige referência ao evento transacional do Asaas.';
  END IF;

  IF NEW.eixo_formalizacao = 'caso_ativo' AND NEW.case_id IS NULL THEN
    RAISE EXCEPTION 'Caso ativo exige caso operacional vinculado: Discovery ou proposta não abrem caso.';
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: fn_lead_discovery_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_lead_discovery_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.archived_at IS NOT NULL THEN RETURN NEW; END IF;

  -- Call realizada
  IF NEW.status_call = 'realizada' THEN
    IF coalesce(NEW.resumo_call,'') = '' OR coalesce(NEW.resumo_validado,false) = false
       OR coalesce(NEW.discovery_resultado,'') = ''
       OR coalesce(NEW.proxima_acao,'') = '' OR NEW.proxima_acao_em IS NULL THEN
      RAISE EXCEPTION 'Call realizada exige resumo validado, resultado da Discovery e próxima ação com prazo';
    END IF;
  END IF;

  -- Consentimento e gravação
  IF NEW.consentimento_status = 'concedido' THEN
    IF NEW.consentimento_em IS NULL OR coalesce(NEW.consentimento_canal,'') = ''
       OR coalesce(NEW.consentimento_versao_aviso,'') = '' THEN
      RAISE EXCEPTION 'Consentimento concedido exige data/hora, canal e versão do aviso';
    END IF;
  ELSE
    NEW.consentimento_gravacao := false;
    IF coalesce(NEW.gravacao_link_interno,'') <> '' THEN
      RAISE EXCEPTION 'Gravação/transcrição só é permitida com consentimento concedido';
    END IF;
  END IF;

  -- SPIN concluído exige resumo correspondente
  IF coalesce(NEW.spin_situacao,false) AND coalesce(NEW.spin_problema,false)
     AND coalesce(NEW.spin_implicacao,false) AND coalesce(NEW.spin_necessidade,false)
     AND length(coalesce(NEW.resumo_call,'')) < 30 THEN
    RAISE EXCEPTION 'SPIN concluído exige resumo validado correspondente na ficha';
  END IF;

  -- Sinal de aderência forte/provável
  IF NEW.elegibilidade_preliminar IN ('forte','provavel') THEN
    IF coalesce(NEW.confianca_triagem,'') = '' OR coalesce(NEW.via_juridica_preliminar,'') = ''
       OR coalesce(NEW.geracao_ascendente,'') = '' OR coalesce(NEW.linha_transmissao,'') = ''
       OR coalesce(NEW.estado_documental_inicial,'') = '' THEN
      RAISE EXCEPTION 'Sinal forte/provável exige confiança, via preliminar, geração, linha de transmissão e estado documental';
    END IF;
  END IF;

  -- SKU é referência somente após produto recomendado
  IF coalesce(NEW.sku_referencia,'') <> ''
     AND coalesce(array_length(NEW.produtos_recomendados,1),0) = 0 THEN
    RAISE EXCEPTION 'Referência de SKU exige produto/serviço recomendado registrado antes';
  END IF;

  -- Despesas de terceiros
  IF NEW.despesas_terceiros_status = 'aprovadas' THEN
    IF coalesce(NEW.despesas_terceiros_faixa,'') = '' OR coalesce(NEW.despesas_terceiros_regra,'') = ''
       OR coalesce(NEW.proposta_referencia_interna,'') = '' THEN
      RAISE EXCEPTION 'Despesa aprovada exige faixa, regra de pagamento e referência de proposta/escopo';
    END IF;
    IF NEW.despesas_terceiros_regra = 'clube_nao_antecipa' THEN
      RAISE EXCEPTION 'Despesa aprovada exige regra de pagamento direto do cliente ao terceiro';
    END IF;
  END IF;

  -- Pesquisa prévia
  IF coalesce(array_length(NEW.pesquisa_previa_escopo,1),0) > 0
     AND NEW.pesquisa_previa_autorizacao <> 'registrada' THEN
    RAISE EXCEPTION 'Escopo de pesquisa prévia exige autorização registrada';
  END IF;

  RETURN NEW;
END; $$;


