--
-- Name: fn_piloto_bloqueio_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_piloto_bloqueio_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
begin
  NEW.updated_at := now();
  if TG_OP = 'UPDATE' then NEW.updated_by := auth.uid(); end if;

  if TG_OP = 'UPDATE' and NEW.status <> 'aberto' and OLD.status = 'aberto' then
    if not (public.has_org_role(NEW.organization_id,'admin') or public.has_org_role(NEW.organization_id,'operacoes')) then
      raise exception 'Somente admin ou operações podem resolver bloqueios críticos do piloto.';
    end if;
    if NEW.justificativa is null or length(trim(NEW.justificativa)) < 10 then
      raise exception 'Registre a justificativa da resolução (mínimo 10 caracteres).';
    end if;
    NEW.resolvido_por := coalesce(NEW.resolvido_por, auth.uid());
    NEW.resolvido_em := coalesce(NEW.resolvido_em, now());
  end if;
  return NEW;
end $$;


--
-- Name: fn_piloto_caso_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_piloto_caso_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_abertos text;
begin
  if NEW.piloto then
    if NEW.demo then
      raise exception 'O caso piloto real não pode ser marcado como demonstração.';
    end if;
    if exists (select 1 from public.clientes c where c.id = NEW.cliente_id and c.demo) then
      raise exception 'O caso piloto real não pode ser vinculado a um cliente de demonstração.';
    end if;
    if exists (select 1 from public.organizations o where o.id = NEW.organization_id and o.nome ilike 'DEMO%') then
      raise exception 'O caso piloto real não pode pertencer a uma organização de demonstração.';
    end if;

    if (NEW.ativo and not coalesce(OLD.ativo,false)) or (NEW.status = 'ativo' and coalesce(OLD.status,'') <> 'ativo') then
      select string_agg(b.descricao, '; ') into v_abertos
        from public.piloto_bloqueios b
       where b.case_id = NEW.id and b.status = 'aberto' and b.criticidade = 'critico' and b.archived_at is null;
      if v_abertos is not null then
        raise exception 'Ativação operacional NO_GO. Bloqueios críticos abertos: %', v_abertos;
      end if;
    end if;
  end if;
  return NEW;
end $$;


--
-- Name: fn_piloto_contrato_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_piloto_contrato_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_piloto boolean; v_code text;
begin
  select coalesce(c.piloto,false) into v_piloto from public.crm_casos c where c.id = NEW.case_id;
  if not coalesce(v_piloto,false) then return NEW; end if;

  select t.code into v_code from public.contract_templates t where t.id = NEW.template_id;
  if v_code is null then
    raise exception 'Contrato do piloto exige um modelo contratual ativo (MODELO ESTUDO ou base genérica v2).';
  end if;
  if v_code in ('MODELO-SIMPLES','MODELO-2024') then
    raise exception 'Modelo % não é aplicável ao piloto real. Use MODELO ESTUDO com a base contratual genérica v2.', v_code;
  end if;
  if v_code not in ('MODELO-ESTUDO','BASE-GEN-V2') then
    raise exception 'Modelo contratual não autorizado para o piloto real.';
  end if;

  if NEW.status = 'signed' and coalesce(OLD.status,'') <> 'signed' then
    if NEW.signed_at is null or NEW.signature_reference is null or NEW.signed_source is null then
      raise exception 'Assinatura exige data, origem externa e referência de assinatura registradas.';
    end if;
    if NEW.approved_for_send_by is null then
      raise exception 'Assinatura exige aprovação humana registrada antes do envio.';
    end if;
    if not exists (
      select 1 from public.contract_parties p
       where p.contract_id = NEW.id and p.archived_at is null
    ) then
      raise exception 'Assinatura exige partes qualificadas registradas no contrato.';
    end if;
  end if;
  return NEW;
end $$;


--
-- Name: fn_piloto_dado_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_piloto_dado_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
begin
  NEW.updated_at := now();
  if TG_OP = 'UPDATE' then NEW.updated_by := auth.uid(); end if;

  if NEW.valor is not null and length(trim(NEW.valor)) = 0 then
    NEW.valor := null;
  end if;

  if NEW.valor is not null then
    if NEW.valor ~* '(\[ex\.|\bex\.:|lorem ipsum|preencher|placeholder|xxx|<[^>]*>)' then
      raise exception 'Valor contém texto de exemplo/placeholder. Campos sem dado real devem permanecer vazios como pendência.';
    end if;
    if NEW.origem is null then
      raise exception 'Informe a origem do dado (proposta, WhatsApp, reunião/transcrição, documento, formulário ou preenchimento humano).';
    end if;
    if NEW.origem = 'reuniao_transcricao'
       and (TG_OP = 'INSERT' or NEW.valor is distinct from OLD.valor or NEW.origem is distinct from OLD.origem) then
      NEW.verificado := false;
      NEW.verificado_por := null;
      NEW.verificado_em := null;
    end if;
  else
    NEW.verificado := false;
    NEW.verificado_por := null;
    NEW.verificado_em := null;
  end if;

  if NEW.verificado and not coalesce(OLD.verificado, false) then
    NEW.verificado_por := coalesce(NEW.verificado_por, auth.uid());
    NEW.verificado_em := coalesce(NEW.verificado_em, now());
  end if;

  return NEW;
end $$;


--
-- Name: fn_portal_access_autorizacao_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_portal_access_autorizacao_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_aut public.authorized_portal_emails%ROWTYPE;
BEGIN
  NEW.email := lower(btrim(NEW.email));

  IF TG_OP = 'INSERT'
     OR NEW.email IS DISTINCT FROM OLD.email
     OR NEW.access_level IS DISTINCT FROM OLD.access_level THEN
    SELECT * INTO v_aut
    FROM public.authorized_portal_emails a
    WHERE a.organization_id = NEW.organization_id
      AND lower(a.email) = NEW.email
      AND a.status = 'aprovado'
      AND a.archived_at IS NULL
      AND a.nivel_pretendido = NEW.access_level
      AND (a.client_id IS NULL OR a.client_id = NEW.client_id)
    ORDER BY a.validado_em DESC NULLS LAST
    LIMIT 1;

    IF v_aut.id IS NULL THEN
      RAISE EXCEPTION 'Bloqueado: e-mail não autorizado previamente para este nível de acesso.';
    END IF;

    NEW.authorized_email_id := v_aut.id;
    IF NEW.finalidade IS NULL OR length(btrim(NEW.finalidade)) < 5 THEN
      NEW.finalidade := v_aut.finalidade;
    END IF;
    IF v_aut.is_demo THEN NEW.is_demo := true; END IF;
  END IF;

  IF NEW.access_status = 'suspended' THEN
    IF NEW.suspended_at IS NULL THEN NEW.suspended_at := now(); END IF;
    IF NEW.suspension_reason IS NULL OR length(btrim(NEW.suspension_reason)) < 5 THEN
      NEW.suspension_reason := coalesce(NEW.revocation_reason, 'Suspensão registrada pela equipe.');
    END IF;
  END IF;

  IF NEW.access_status = 'revoked' AND (NEW.revocation_reason IS NULL OR length(btrim(NEW.revocation_reason)) < 5) THEN
    RAISE EXCEPTION 'Revogação exige motivo registrado.';
  END IF;

  IF NEW.magic_link_max_uses < 1 THEN
    RAISE EXCEPTION 'O link mágico precisa ter pelo menos um uso permitido.';
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: fn_portal_case_access_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_portal_case_access_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_acesso public.client_portal_access%ROWTYPE;
  v_caso public.crm_casos%ROWTYPE;
BEGIN
  SELECT * INTO v_acesso FROM public.client_portal_access WHERE id = NEW.client_portal_access_id;
  IF v_acesso.id IS NULL THEN
    RAISE EXCEPTION 'Acesso ao portal não encontrado.';
  END IF;

  SELECT * INTO v_caso FROM public.crm_casos WHERE id = NEW.case_id;
  IF v_caso.id IS NULL OR v_caso.archived_at IS NOT NULL THEN
    RAISE EXCEPTION 'Caso não encontrado ou arquivado.';
  END IF;

  IF v_acesso.access_level = 'proposal_portal' THEN
    RAISE EXCEPTION 'Bloqueado: portal de proposta não recebe vínculo de caso operacional.';
  END IF;

  IF v_caso.cliente_id IS DISTINCT FROM v_acesso.client_id THEN
    RAISE EXCEPTION 'Bloqueado: o caso não pertence à pessoa deste acesso.';
  END IF;

  IF NEW.access_status IS DISTINCT FROM 'revoked'::public.portal_case_status THEN
    IF NOT coalesce(v_caso.contrato_assinado, false) THEN
      RAISE EXCEPTION 'Bloqueado: contrato não assinado.';
    END IF;
    IF NOT coalesce(v_caso.pagamento_confirmado, false) THEN
      RAISE EXCEPTION 'Bloqueado: pagamento inicial não confirmado.';
    END IF;
    IF NOT coalesce(v_caso.documentos_minimos_ok, false) THEN
      RAISE EXCEPTION 'Bloqueado: documentos mínimos não concluídos.';
    END IF;
    IF v_caso.ativado_em IS NULL AND v_caso.onboarding_iniciado_em IS NULL THEN
      RAISE EXCEPTION 'Bloqueado: falta decisão humana de ativação ou onboarding elegível.';
    END IF;
    IF coalesce(v_acesso.is_demo, false) <> coalesce(v_caso.demo, false) THEN
      RAISE EXCEPTION 'Bloqueado: acesso de demonstração não pode ser vinculado a caso real.';
    END IF;
  END IF;

  IF NEW.access_status = 'revoked'::public.portal_case_status
     AND (NEW.revocation_reason IS NULL OR length(btrim(NEW.revocation_reason)) < 5) THEN
    RAISE EXCEPTION 'Revogação de caso exige motivo registrado.';
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: fn_portal_ticket_msg(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_portal_ticket_msg() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.autor_tipo = 'cliente' THEN
    NEW.visivel_cliente := true;
  END IF;
  NEW.autor_user_id := COALESCE(NEW.autor_user_id, auth.uid());
  RETURN NEW;
END;
$$;


--
-- Name: fn_portal_ticket_touch(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_portal_ticket_touch() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  UPDATE public.portal_tickets
     SET ultima_mensagem_em = now(),
         status = CASE
           WHEN NEW.autor_tipo = 'cliente' AND status IN ('resolvido','respondido') THEN 'aberto'
           WHEN NEW.autor_tipo = 'equipe' AND status IN ('aberto','em_analise') THEN 'respondido'
           ELSE status END,
         updated_at = now()
   WHERE id = NEW.ticket_id;
  RETURN NEW;
END;
$$;


--
-- Name: fn_preview_aprovacao_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_preview_aprovacao_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.aprovado_por IS NOT NULL AND OLD.aprovado_por IS DISTINCT FROM NEW.aprovado_por THEN
    IF NEW.legado_sem_evento OR NEW.legado_sem_corpo OR NOT NEW.corpo_contratual THEN
      RAISE EXCEPTION 'Prévia legada ou sem corpo contratual não pode ser aprovada nem usada para assinatura.';
    END IF;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: fn_preview_evento_obrigatorio(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_preview_evento_obrigatorio() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.evento IS NULL OR btrim(NEW.evento) = '' THEN
    RAISE EXCEPTION 'Prévia exige evento de governança não nulo.';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: fn_preview_template_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_preview_template_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.template_code IS NOT NULL
     AND NEW.template_code NOT IN ('MODELO-ESTUDO','BASE-GEN-V2') THEN
    RAISE EXCEPTION 'Prévia só pode ser gerada pelo MODELO ESTUDO + base contratual genérica v2.';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: fn_proposals_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_proposals_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_venc date;
begin
  if TG_OP = 'UPDATE' and NEW.status = 'aprovada' and OLD.status is distinct from 'aprovada' then
    v_venc := NEW.validade;
    if v_venc is null then
      raise exception 'Proposta só pode ser aprovada com data de validade registrada.';
    end if;
    if v_venc < current_date then
      raise exception 'Proposta vencida: registre a renovação de validade antes de aprovar.';
    end if;
    if OLD.status = 'expirada' and (NEW.validade_renovada_em is null or coalesce(btrim(NEW.validade_renovada_motivo),'') = '') then
      raise exception 'Proposta expirada exige renovação de validade com motivo registrado.';
    end if;
    NEW.aprovada_em := coalesce(NEW.aprovada_em, now());

    if NEW.client_id is not null then
      update public.proposals
         set status = 'substituida',
             substituida_em = now(),
             substituida_por_id = NEW.id
       where organization_id = NEW.organization_id
         and client_id = NEW.client_id
         and id <> NEW.id
         and status = 'aprovada'
         and archived_at is null;
    end if;
  end if;

  if TG_OP = 'UPDATE' and NEW.validade is distinct from OLD.validade and OLD.validade is not null
     and OLD.validade < current_date then
    if coalesce(btrim(NEW.validade_renovada_motivo),'') = '' then
      raise exception 'Renovar a validade de uma proposta vencida exige motivo.';
    end if;
    NEW.validade_renovada_em := now();
    NEW.validade_renovada_por := auth.uid();
  end if;

  if TG_OP = 'UPDATE' and NEW.status = 'recusada' and OLD.status is distinct from 'recusada' then
    NEW.recusada_em := coalesce(NEW.recusada_em, now());
  end if;
  if TG_OP = 'UPDATE' and NEW.status = 'enviada' and OLD.status is distinct from 'enviada' then
    NEW.enviada_em := coalesce(NEW.enviada_em, now());
  end if;
  return NEW;
end $$;


--
-- Name: fn_proposta_paginas_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_proposta_paginas_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE p smallint;
BEGIN
  IF NEW.paginas_registradas IS NOT NULL THEN
    FOREACH p IN ARRAY NEW.paginas_registradas LOOP
      IF p < 1 OR p > 7 THEN
        RAISE EXCEPTION 'Páginas da proposta Canva devem estar entre 1 e 7 (recebido %).', p;
      END IF;
    END LOOP;
  END IF;
  IF NEW.escopo_paginas IS NOT NULL AND jsonb_typeof(NEW.escopo_paginas) <> 'object' THEN
    RAISE EXCEPTION 'Conteúdo extraído por página deve ser um objeto.';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: fn_proteger_ultimo_admin(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_proteger_ultimo_admin() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare v_outros int;
begin
  if OLD.role = 'admin' and OLD.status = 'active' and OLD.archived_at is null then
    if NEW.role <> 'admin' or NEW.status <> 'active' or NEW.archived_at is not null then
      select count(*) into v_outros
      from public.staff_access s
      where s.organization_id = OLD.organization_id
        and s.id <> OLD.id
        and s.role = 'admin'
        and s.status = 'active'
        and s.archived_at is null;
      if v_outros = 0 then
        raise exception 'Não é possível suspender, revogar, arquivar ou rebaixar o último administrador ativo. Ative outro administrador antes.';
      end if;
    end if;
  end if;
  return NEW;
end $$;


--
-- Name: fn_quality_guard_ativacao(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_quality_guard_ativacao() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE v_bloqueios text;
BEGIN
  IF (NEW.status = 'ativo' OR NEW.ativo IS TRUE)
     AND (TG_OP = 'INSERT' OR (COALESCE(OLD.status,'') <> 'ativo' AND COALESCE(OLD.ativo,false) = false)) THEN
    SELECT string_agg(titulo, '; ') INTO v_bloqueios
      FROM quality_issues
     WHERE case_id = NEW.id AND severidade = 'critica'
       AND status IN ('aberta','reconhecida');
    IF v_bloqueios IS NOT NULL THEN
      RAISE EXCEPTION 'Ativação bloqueada por inconsistências críticas em aberto: %', v_bloqueios;
    END IF;
  END IF;
  RETURN NEW;
END; $$;


--
-- Name: fn_quality_issue_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_quality_issue_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  -- campos de detecção são imutáveis: não é possível "ocultar" a inconsistência
  NEW.regra_key := OLD.regra_key;
  NEW.severidade := OLD.severidade;
  NEW.entidade := OLD.entidade;
  NEW.entidade_id := OLD.entidade_id;
  NEW.organization_id := OLD.organization_id;
  NEW.detectada_em := OLD.detectada_em;

  IF NEW.status IS DISTINCT FROM OLD.status THEN
    IF OLD.status = 'sanada' AND NEW.status <> 'sanada' THEN
      RAISE EXCEPTION 'Inconsistência já sanada pela varredura não pode mudar de estado.';
    END IF;
    IF NEW.status = 'reconhecida' THEN
      NEW.reconhecida_por := COALESCE(NEW.reconhecida_por, auth.uid());
      NEW.reconhecida_em := now();
      IF NEW.resolucao_comentario IS NULL OR length(btrim(NEW.resolucao_comentario)) < 10 THEN
        RAISE EXCEPTION 'Reconhecer a inconsistência exige comentário com ao menos 10 caracteres.';
      END IF;
    ELSIF NEW.status IN ('resolvida','falso_positivo') THEN
      IF NEW.resolucao_comentario IS NULL OR length(btrim(NEW.resolucao_comentario)) < 10 THEN
        RAISE EXCEPTION 'Resolver ou marcar falso positivo exige justificativa com ao menos 10 caracteres.';
      END IF;
      IF NEW.severidade IN ('critica','alta')
         AND NEW.status = 'resolvida'
         AND (NEW.resolucao_evidencia IS NULL OR length(btrim(NEW.resolucao_evidencia)) = 0) THEN
        RAISE EXCEPTION 'Inconsistências críticas e altas exigem evidência da resolução.';
      END IF;
      NEW.resolvida_por := COALESCE(NEW.resolvida_por, auth.uid());
      NEW.resolvida_em := now();
    ELSIF NEW.status = 'aberta' THEN
      NULL;
    END IF;
  END IF;
  NEW.updated_at := now();
  RETURN NEW;
END; $$;


--
-- Name: fn_report_link_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_report_link_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org uuid;
BEGIN
  NEW.updated_at := now();
  SELECT organization_id INTO v_org FROM public.case_reports WHERE id = NEW.report_id;
  IF v_org IS NULL OR v_org <> NEW.organization_id THEN
    RAISE EXCEPTION 'Vinculo deve pertencer a mesma organizacao do relatorio';
  END IF;
  IF NEW.archived_at IS NOT NULL AND (NEW.archived_reason IS NULL OR btrim(NEW.archived_reason) = '') THEN
    RAISE EXCEPTION 'Arquivamento exige motivo';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: fn_research_case_estado_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_research_case_estado_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.status NOT IN (
    'not_started','preparation','internal_research','awaiting_documents',
    'awaiting_review','paused','completed','archived'
  ) THEN
    RAISE EXCEPTION 'Situação de pesquisa inválida: %', NEW.status;
  END IF;

  IF coalesce(NEW.external_research_gate_status,'blocked_by_contract') = 'released_by_authorized_user'
     AND coalesce(NEW.external_research_authorization_status,'not_requested')
         NOT IN ('authorized','autorizada') THEN
    RAISE EXCEPTION 'Pesquisa externa não pode ser liberada sem autorização registrada.';
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: fn_research_report_estado_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_research_report_estado_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.report_type NOT IN ('F1','F2') THEN
    RAISE EXCEPTION 'Tipo de relatório inválido: %', NEW.report_type;
  END IF;
  IF NEW.status NOT IN ('rascunho_interno','em_revisao','aprovado_interno','publicado_cliente','arquivado') THEN
    RAISE EXCEPTION 'Situação de relatório inválida: %', NEW.status;
  END IF;
  IF NEW.status = 'publicado_cliente' THEN
    IF coalesce(btrim(NEW.approved_summary_client),'') = '' THEN
      RAISE EXCEPTION 'Relatório só é publicado com resumo sanitizado aprovado para o cliente.';
    END IF;
    IF NEW.approved_by IS NULL OR NEW.approved_at IS NULL THEN
      RAISE EXCEPTION 'Relatório só é publicado com aprovação interna registrada.';
    END IF;
    NEW.published_at := coalesce(NEW.published_at, now());
  ELSE
    NEW.published_at := NULL;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: fn_rg_audit(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_rg_audit() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare rc uuid; tipo text; org uuid; jnew jsonb; jold jsonb;
begin
  org := new.organization_id;
  jnew := to_jsonb(new);
  jold := case when TG_OP = 'UPDATE' then to_jsonb(old) else '{}'::jsonb end;
  rc := nullif(jnew->>'research_case_id','')::uuid;
  if TG_TABLE_NAME = 'research_cases' then rc := new.id; end if;
  if TG_OP = 'INSERT' then tipo := 'created';
  elsif (jnew->>'archived_at') is not null and (jold->>'archived_at') is null then tipo := 'archived';
  elsif (jnew->>'status') is distinct from (jold->>'status') then tipo := 'status_changed';
  else tipo := 'updated';
  end if;
  insert into public.research_audit_events(organization_id, research_case_id, entity_type, entity_id, event_type, actor_user_id, metadata)
  values (org, rc, TG_TABLE_NAME, new.id, tipo, auth.uid(),
          jsonb_strip_nulls(jsonb_build_object('status', jnew->>'status', 'op', TG_OP)));
  return new;
end $$;


--
-- Name: fn_rg_case_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_rg_case_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare gate jsonb;
begin
  if TG_OP='UPDATE' and new.archived_at is not null and old.archived_at is null then
    if exists (select 1 from public.research_pending_items p
                where p.research_case_id = new.id and p.severity='critical'
                  and p.status in ('open','in_progress','blocked') and p.archived_at is null)
       and not public.rg_admin(new.organization_id) then
      raise exception 'Pesquisa com pendência crítica aberta só pode ser arquivada por admin com justificativa.';
    end if;
  end if;
  if new.external_research_gate_status = 'released_by_authorized_user'
     and (TG_OP='INSERT' or old.external_research_gate_status is distinct from 'released_by_authorized_user') then
    if not (public.rg_admin(new.organization_id) or public.staff_meu_papel(new.organization_id) = 'operacoes'::app_role) then
      raise exception 'Somente admin ou operações podem registrar a liberação de pesquisa externa.';
    end if;
  elsif TG_OP='UPDATE' then
    gate := public.pode_iniciar_pesquisa_externa(new.id);
    if gate is not null then
      new.external_research_gate_status := gate->>'estado';
    end if;
  end if;
  return new;
end $$;


--
-- Name: fn_rg_evento_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_rg_evento_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if new.status = 'validated' and not public.rg_tem_evidencia_validada('event', new.id) then
    raise exception 'Evento validado exige ao menos uma evidência validada vinculada.';
  end if;
  return new;
end $$;


--
-- Name: fn_rg_evidencia_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_rg_evidencia_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare gate jsonb;
begin
  if new.sensitivity_level = 'highly_restricted' and new.client_visibility <> 'never' then
    raise exception 'Dado altamente restrito não pode ser visível ao cliente.';
  end if;
  if new.evidence_status = 'validated' then
    if new.source_id is null and new.document_id is null and coalesce(btrim(new.external_reference),'') = '' then
      raise exception 'Evidência validada exige fonte, documento ou referência.';
    end if;
    if new.validated_by is null and new.reviewed_by is null then
      raise exception 'Evidência validada exige responsável pela revisão.';
    end if;
    if new.validated_at is null and new.reviewed_at is null then
      raise exception 'Evidência validada exige data de revisão.';
    end if;
    if coalesce(length(btrim(new.validation_rationale)),0) < 20 then
      raise exception 'Evidência validada exige justificativa com pelo menos 20 caracteres.';
    end if;
  end if;
  if new.evidence_status = 'discarded' and coalesce(length(btrim(new.discard_reason)),0) < 5 then
    raise exception 'Evidência descartada exige motivo.';
  end if;
  if TG_OP = 'INSERT' and new.origem_externa and not new.fornecida_pelo_cliente then
    gate := public.pode_iniciar_pesquisa_externa(new.research_case_id);
    if (gate->>'permitido')::boolean is not true then
      insert into public.research_audit_events(organization_id, research_case_id, entity_type, entity_id, event_type, metadata)
      values (new.organization_id, new.research_case_id, 'research_evidence_items', null, 'external_action_blocked',
              jsonb_build_object('estado', gate->>'estado'));
      raise exception '%', gate->>'mensagem';
    end if;
  end if;
  if new.client_visibility = 'released' and new.evidence_status <> 'validated' then
    raise exception 'Somente evidência validada pode ser liberada.';
  end if;
  return new;
end $$;


--
-- Name: fn_rg_meta(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_rg_meta() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
begin
  if TG_OP = 'INSERT' then
    new.created_by := coalesce(new.created_by, auth.uid());
  else
    new.updated_at := now();
    new.updated_by := coalesce(auth.uid(), new.updated_by);
    if new.archived_at is not null and old.archived_at is null then
      if new.archive_reason is null or length(btrim(new.archive_reason)) < 5 then
        raise exception 'Arquivamento exige motivo (archive_reason).';
      end if;
      new.archived_by := coalesce(new.archived_by, auth.uid());
    end if;
  end if;
  return new;
end $$;


--
-- Name: fn_rg_pedido_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_rg_pedido_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare gate jsonb;
begin
  if new.external_action_required then
    gate := public.pode_iniciar_pesquisa_externa(new.research_case_id);
    new.external_gate_status := gate->>'estado';
    if (gate->>'permitido')::boolean is not true
       and new.status not in ('draft','blocked_by_gate','cancelled','archived') then
      insert into public.research_audit_events(organization_id, research_case_id, entity_type, entity_id, event_type, metadata)
      values (new.organization_id, new.research_case_id, 'research_document_requests', new.id, 'external_action_blocked',
              jsonb_build_object('estado', gate->>'estado'));
      new.status := 'blocked_by_gate';
    end if;
  else
    new.external_gate_status := 'not_applicable';
  end if;
  return new;
end $$;


--
-- Name: fn_rg_pendencia_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_rg_pendencia_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
begin
  if TG_OP='UPDATE' and new.status = 'resolved' and old.status <> 'resolved' then
    if coalesce(length(btrim(new.resolution_note)),0) < 5 then
      raise exception 'Resolução de pendência exige nota.';
    end if;
    new.resolved_by := coalesce(new.resolved_by, auth.uid());
    new.resolved_at := coalesce(new.resolved_at, now());
  end if;
  return new;
end $$;


--
-- Name: fn_rg_pessoa_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_rg_pessoa_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
begin
  if (new.living_status = 'living' or new.is_minor) and new.sensitivity_level = 'standard' then
    new.sensitivity_level := case when new.is_minor then 'highly_restricted' else 'restricted' end;
  end if;
  if new.sensitivity_level = 'highly_restricted' then new.visible_to_client_summary := false; end if;
  if new.identity_status = 'confirmed' and exists (
      select 1 from public.research_relationships r
       where r.archived_at is null and r.status = 'conflicting'
         and (r.person_a_id = new.id or r.person_b_id = new.id)) then
    raise exception 'Identidade não pode ser confirmada com relação conflitante em aberto.';
  end if;
  return new;
end $$;


--
-- Name: fn_rg_relacao_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_rg_relacao_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if new.status = 'validated' and not public.rg_tem_evidencia_validada('relationship', new.id) then
    raise exception 'Relação validada exige ao menos uma evidência validada vinculada.';
  end if;
  if new.status = 'validated' then
    new.validated_by := coalesce(new.validated_by, auth.uid());
    new.validated_at := coalesce(new.validated_at, now());
  end if;
  new.supporting_evidence_count := (
    select count(*) from public.research_evidence_links l join public.research_evidence_items e on e.id = l.evidence_item_id
     where l.entity_type='relationship' and l.entity_id = new.id and e.evidence_status='validated' and e.archived_at is null);
  return new;
end $$;


--
-- Name: fn_rg_relatorio_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_rg_relatorio_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
begin
  if new.status = 'released' and (new.approved_by is null or new.client_release_authorized_by is null) then
    raise exception 'Relatório cliente-facing exige aprovação e liberação humana.';
  end if;
  return new;
end $$;


--
-- Name: fn_rg_resumo_cliente_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_rg_resumo_cliente_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare txt text;
begin
  txt := lower(coalesce(new.title_client_facing,'') || ' ' || coalesce(new.summary_client_facing,''));
  if txt ~ '(hip[oó]tese|probabilidad|chance|elegibilidad|eleg[ií]vel|[êe]xito|garantia|prazo garantido|r\$|pre[çc]o|http|familysearch|sku)' then
    insert into public.research_audit_events(organization_id, research_case_id, entity_type, entity_id, event_type, metadata)
    values (new.organization_id, new.research_case_id, 'research_client_summaries', new.id, 'client_visibility_blocked', '{}'::jsonb);
    raise exception 'Resumo cliente-facing não pode conter hipótese, probabilidade, elegibilidade, preço ou referência de fonte.';
  end if;
  if new.status in ('approved_for_release','released') and new.approved_by is null then
    raise exception 'Resumo cliente-facing exige aprovação humana registrada.';
  end if;
  if new.status = 'released' and (new.released_by is null or new.released_at is null) then
    raise exception 'Liberação de resumo exige usuário e data de liberação.';
  end if;
  return new;
end $_$;


--
-- Name: fn_seed_activation_checks(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_seed_activation_checks() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  insert into public.case_activation_checks (organization_id, case_id, check_key, label, dominio, obrigatorio)
  select NEW.organization_id, NEW.id, d.check_key, d.label, d.dominio, d.obrigatorio
  from public.activation_check_definicoes() d
  on conflict (case_id, check_key) do nothing;
  return NEW;
end $$;


--
-- Name: fn_seed_contract_parameters(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_seed_contract_parameters() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  INSERT INTO public.contract_parameter_values
    (organization_id, parameters_id, grupo, campo, label, obrigatorio, ordem, status, created_by, updated_by)
  SELECT NEW.organization_id, NEW.id, d.grupo, d.campo, d.label, d.obrigatorio, d.ordem, 'vazio', auth.uid(), auth.uid()
  FROM public.contract_parameter_definicoes() d;
  RETURN NEW;
END;
$$;


--
-- Name: fn_service_orders_case_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_service_orders_case_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
begin
  if NEW.status in ('active','completed') and NEW.case_id is null then
    raise exception 'Ordem de serviço só pode ser iniciada vinculada a um caso.';
  end if;
  return NEW;
end $$;


--
-- Name: fn_service_orders_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_service_orders_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare v_seq int; v_contract record; v_excecao boolean;
begin
  select * into v_contract from public.contracts where id = NEW.contract_id;
  if v_contract is null or v_contract.organization_id <> NEW.organization_id then
    raise exception 'Ordem de serviço deve referenciar contrato da mesma organização.';
  end if;

  if TG_OP = 'INSERT' then
    select count(*) + 1 into v_seq from public.service_orders where organization_id = NEW.organization_id;
    NEW.service_order_number := to_char(now(),'YYYY') || '-OS-' || lpad(v_seq::text, 4, '0');
  else
    if NEW.service_order_number is distinct from OLD.service_order_number then
      raise exception 'A numeração da ordem de serviço é gerada pelo sistema.';
    end if;
  end if;

  if NEW.status = 'active' and (TG_OP = 'INSERT' or OLD.status <> 'active') then
    select exists (
      select 1 from public.contract_exceptions e
      where e.contract_id = NEW.contract_id
        and e.scope in ('activation_gate','financial_gate')
        and e.revoked_at is null and e.archived_at is null
        and (e.expires_at is null or e.expires_at > now())
    ) into v_excecao;
    if not v_excecao then
      if v_contract.status <> 'signed' then
        insert into public.contract_review_events (organization_id, contract_id, event_type, actor_user_id, metadata)
        values (NEW.organization_id, NEW.contract_id, 'activation_gate_blocked', auth.uid(), jsonb_build_object('motivo','contrato_nao_assinado'));
        raise exception 'Ordem de serviço não pode ser ativada sem contrato assinado.';
      end if;
      if v_contract.financial_gate_status not in ('confirmed','not_applicable') then
        insert into public.contract_review_events (organization_id, contract_id, event_type, actor_user_id, metadata)
        values (NEW.organization_id, NEW.contract_id, 'financial_gate_blocked', auth.uid(), jsonb_build_object('motivo','condicao_financeira_nao_confirmada'));
        raise exception 'Ordem de serviço não pode ser ativada sem condição financeira confirmada.';
      end if;
    end if;
  end if;
  return NEW;
end $$;


--
-- Name: fn_sku_price_exception_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_sku_price_exception_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF coalesce(btrim(NEW.motivo),'') = '' THEN
    RAISE EXCEPTION 'Exceção comercial exige motivo registrado.';
  END IF;
  IF coalesce(btrim(NEW.responsavel),'') = '' THEN
    RAISE EXCEPTION 'Exceção comercial exige responsável identificado.';
  END IF;
  IF NEW.status = 'aprovada' AND (NEW.aprovado_por IS NULL OR NEW.aprovado_em IS NULL) THEN
    RAISE EXCEPTION 'Exceção comercial só pode ser aprovada com aprovador humano e data de aprovação.';
  END IF;
  IF NEW.status = 'aprovada' AND NEW.valido_ate < current_date THEN
    RAISE EXCEPTION 'Exceção comercial aprovada exige validade futura.';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: fn_staff_archive_meta(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_staff_archive_meta() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
begin
  if NEW.archived_at is not null and OLD.archived_at is null then
    NEW.archived_by := coalesce(NEW.archived_by, auth.uid());
    if NEW.archive_reason is null or length(trim(NEW.archive_reason)) = 0 then
      raise exception 'Informe o motivo do arquivamento.';
    end if;
  end if;
  return NEW;
end $$;


--
-- Name: fn_suspensao_tarefa_revisao(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_suspensao_tarefa_revisao() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if NEW.status = 'pausado' and OLD.status <> 'pausado' then
    insert into public.tarefas (organization_id, caso_id, titulo, descricao, responsavel_id, prioridade, status, prazo, created_by)
    values (NEW.organization_id, NEW.id,
      'Revisão de caso suspenso: ' || NEW.codigo,
      'Motivo da suspensão: ' || coalesce(NEW.suspenso_motivo,''),
      NEW.responsavel_id, 'alta', 'aberta', (current_date + 3), auth.uid());
  end if;
  return NEW;
end $$;


--
-- Name: fn_tarefa_audit_campos(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_tarefa_audit_campos() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if OLD.responsavel_id is distinct from NEW.responsavel_id
     or OLD.prazo is distinct from NEW.prazo
     or OLD.prioridade is distinct from NEW.prioridade then
    insert into public.audit_logs (organization_id, user_id, acao, entidade, entidade_id, valores_anteriores, valores_posteriores)
    values (NEW.organization_id, auth.uid(), 'alteracao_operacional', 'tarefas', NEW.id,
      jsonb_build_object('responsavel_id', OLD.responsavel_id, 'prazo', OLD.prazo, 'prioridade', OLD.prioridade),
      jsonb_build_object('responsavel_id', NEW.responsavel_id, 'prazo', NEW.prazo, 'prioridade', NEW.prioridade));
  end if;
  return NEW;
end $$;


--
-- Name: fn_tarefa_sla(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_tarefa_sla() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_h integer; v_a integer; v_base timestamptz;
begin
  select r.horas_alvo, r.horas_alerta into v_h, v_a
  from public.ops_sla_regras r
  where r.organization_id = NEW.organization_id and r.ativo
    and r.tipo_tarefa in (NEW.tipo, '*')
    and r.prioridade in (coalesce(NEW.prioridade,'media'), '*')
  order by (r.tipo_tarefa = NEW.tipo) desc, (r.prioridade = coalesce(NEW.prioridade,'media')) desc
  limit 1;

  if v_h is null then
    NEW.sla_horas := null;
    NEW.sla_prazo_em := case when NEW.prazo is not null then (NEW.prazo + time '23:59')::timestamptz else null end;
    NEW.sla_alerta_em := null;
    return NEW;
  end if;

  v_base := coalesce(NEW.created_at, now()) + make_interval(hours => v_h);
  if NEW.prazo is not null then
    v_base := least(v_base, (NEW.prazo + time '23:59')::timestamptz);
  end if;
  NEW.sla_horas := v_h;
  NEW.sla_prazo_em := v_base;
  NEW.sla_alerta_em := v_base - make_interval(hours => v_a);
  return NEW;
end $$;


--
-- Name: fn_third_party_expense_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_third_party_expense_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF coalesce(btrim(NEW.descricao),'') = '' THEN
    RAISE EXCEPTION 'Despesa de terceiro exige descrição.';
  END IF;
  IF NEW.estado <> 'nao_aplicavel' THEN
    IF NEW.estado <> 'estimativa_pendente' AND NEW.estimativa_min IS NULL AND NEW.estimativa_max IS NULL THEN
      RAISE EXCEPTION 'Despesa aplicável exige estimativa ou faixa antes de ser comunicada.';
    END IF;
    IF NEW.estado IN ('estimada_comunicada','aguardando_aprovacao','aprovada','paga_diretamente_pelo_cliente','parcialmente_paga')
       AND NEW.comunicado_em IS NULL THEN
      RAISE EXCEPTION 'Despesa exige comunicação prévia ao cliente registrada.';
    END IF;
    IF NEW.estado IN ('aprovada','paga_diretamente_pelo_cliente','parcialmente_paga')
       AND (NEW.aprovado_pelo_cliente_em IS NULL OR coalesce(btrim(NEW.aprovacao_evidencia),'') = '') THEN
      RAISE EXCEPTION 'Execução de despesa de terceiro exige aprovação do cliente registrada com evidência.';
    END IF;
    IF NEW.executado_em IS NOT NULL AND NEW.aprovado_pelo_cliente_em IS NULL THEN
      RAISE EXCEPTION 'Despesa não pode ser executada antes da aprovação do cliente.';
    END IF;
  END IF;
  IF NEW.pagador <> 'cliente' AND NEW.excecao_id IS NULL THEN
    RAISE EXCEPTION 'Pagador diferente do cliente exige exceção formal aprovada.';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: fn_timeline_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_timeline_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.visibility = 'cliente_aprovado' AND coalesce(btrim(NEW.summary_client_approved), '') = '' THEN
    RAISE EXCEPTION 'Evento visível ao cliente exige resumo aprovado para o cliente.';
  END IF;
  NEW.updated_at := now();
  RETURN NEW;
END; $$;


--
-- Name: fn_touch_meta(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_touch_meta() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
begin
  if TG_OP = 'INSERT' then
    NEW.created_by := coalesce(NEW.created_by, auth.uid());
    NEW.updated_by := coalesce(NEW.updated_by, auth.uid());
    NEW.created_at := coalesce(NEW.created_at, now());
  else
    NEW.updated_by := coalesce(auth.uid(), NEW.updated_by);
  end if;
  NEW.updated_at := now();
  return NEW;
end $$;


--
-- Name: fn_validar_uso_template(uuid, uuid, uuid, uuid, uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_validar_uso_template(_template_id uuid, _actor_id uuid DEFAULT auth.uid(), _lead_id uuid DEFAULT NULL::uuid, _opportunity_id uuid DEFAULT NULL::uuid, _case_id uuid DEFAULT NULL::uuid, _person_id uuid DEFAULT NULL::uuid, _channel text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  t public.message_templates%rowtype;
  cat public.message_template_categories%rowtype;
  caso public.crm_casos%rowtype;
  lead_demo boolean := false;
  b text[] := '{}';
  papeis text[];
  permitidos text[];
  etapa text;
begin
  select * into t from public.message_templates where id = _template_id;
  if not found then
    return jsonb_build_object('permitido', false, 'bloqueios', jsonb_build_array('Modelo inexistente.'));
  end if;

  if not public.is_org_member(t.organization_id) then
    return jsonb_build_object('permitido', false, 'bloqueios', jsonb_build_array('Modelo pertence a outra organização.'));
  end if;

  select * into cat from public.message_template_categories where id = t.category_id;

  select array_agg(r.role::text) into papeis
  from public.user_roles r
  where r.user_id = coalesce(_actor_id, auth.uid()) and r.organization_id = t.organization_id;
  papeis := coalesce(papeis, '{}');

  permitidos := case cat.key
    when 'comercial' then array['admin','comercial','operacoes']
    when 'formalizacao' then array['admin','comercial','operacoes']
    when 'financeiro' then array['admin','financeiro']
    when 'pesquisa' then array['admin','operacoes','pesquisador']
    when 'marketing_editorial' then array['admin','operacoes','comercial']
    else array['admin','operacoes']
  end;

  if not (papeis && permitidos) then
    b := b || 'Seu papel não autoriza o uso desta categoria de modelo.';
  end if;

  if t.archived_at is not null or t.status in ('arquivado','suspenso','substituido') then
    b := b || 'Modelo arquivado, suspenso ou substituído.';
  elsif t.status not in ('aprovado','vigente') then
    b := b || 'Modelo ainda não aprovado: uso externo bloqueado.';
  end if;

  if _channel is not null and _channel <> t.channel then
    b := b || 'Canal incompatível com o modelo.';
  end if;

  if cat.key = 'marketing_editorial' and (_case_id is not null or _lead_id is not null or _person_id is not null) then
    b := b || 'Modelo editorial não pode ser vinculado a pessoa, lead ou caso identificável.';
  end if;

  if _case_id is not null then
    select * into caso from public.crm_casos where id = _case_id;
    if not found or caso.organization_id <> t.organization_id then
      b := b || 'Caso inexistente ou de outra organização.';
      _case_id := null;
    end if;
  end if;

  if _lead_id is not null then
    select l.demo into lead_demo from public.leads l
    where l.id = _lead_id and l.organization_id = t.organization_id;
    if not found then b := b || 'Lead inexistente ou de outra organização.'; end if;
  end if;

  if t.is_demo and coalesce(caso.demo, lead_demo, false) = false and (_case_id is not null or _lead_id is not null) then
    b := b || 'Modelo de demonstração não pode ser usado em contexto real.';
  end if;
  if not t.is_demo and coalesce(caso.demo, lead_demo, false) then
    b := b || 'Registro de demonstração: uso apenas com modelo marcado como demonstração.';
  end if;

  etapa := coalesce(t.stage_scope, '');
  if t.requires_gate_validation and etapa <> '' then
    if etapa in ('aceite_verbal_confirmado','confirmacao_formal_recebida','formalizacao_em_preparacao',
                 'contrato_enviado','contrato_assinado','pagamento_inicial_confirmado',
                 'onboarding_iniciado','primeira_microentrega','espera_externa')
       and _case_id is null then
      b := b || 'Vincule o caso correspondente antes de usar este modelo.';
    else
      if etapa = 'aceite_verbal_confirmado' and caso.aceite_comercial_em is null then
        b := b || 'Bloqueado: aceite verbal ainda não registrado.';
      end if;
      if etapa = 'confirmacao_formal_recebida' and caso.data_confirmacao_formal_proposta is null then
        b := b || 'Bloqueado: confirmação formal não registrada.';
      end if;
      if etapa = 'contrato_enviado' and not exists (
        select 1 from public.contracts c
        where c.case_id = _case_id and c.archived_at is null
          and c.approved_for_send_at is not null
      ) then
        b := b || 'Bloqueado: contrato ainda não revisado e liberado para envio.';
      end if;
      if etapa = 'contrato_assinado' and coalesce(caso.contrato_assinado, false) = false then
        b := b || 'Bloqueado: contrato assinado não registrado.';
      end if;
      if etapa = 'pagamento_inicial_confirmado' and coalesce(caso.pagamento_confirmado, false) = false then
        b := b || 'Bloqueado: pagamento inicial não confirmado na fonte transacional.';
      end if;
      if etapa = 'onboarding_iniciado' and caso.onboarding_iniciado_em is null then
        b := b || 'Bloqueado: onboarding ainda não iniciado.';
      end if;
      if etapa = 'primeira_microentrega' and not exists (
        select 1 from public.client_deliverables d
        where d.case_id = _case_id and d.archived_at is null
          and d.approval_status = 'aprovado' and d.published_at is not null
      ) then
        b := b || 'Bloqueado: não há entrega aprovada e publicada para o cliente.';
      end if;
      if etapa = 'espera_externa' and not exists (
        select 1 from public.case_espera_externa e
        where e.case_id = _case_id and e.archived_at is null
          and coalesce(btrim(e.motivo), '') <> '' and e.prazo_rechecagem is not null
      ) then
        b := b || 'Bloqueado: espera externa não registrada de forma completa.';
      end if;
      if etapa = 'proposta_enviada' and _case_id is not null and caso.data_proposta is null then
        b := b || 'Bloqueado: proposta enviada não registrada.';
      end if;
    end if;
  end if;

  return jsonb_build_object(
    'permitido', array_length(b, 1) is null,
    'bloqueios', to_jsonb(coalesce(b, '{}')),
    'template_version', t.version,
    'channel', t.channel,
    'organization_id', t.organization_id
  );
end;
$$;


--
-- Name: gerar_case_id(uuid, text, boolean, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gerar_case_id(_org uuid, _modelo text, _demo boolean DEFAULT false, _ano integer DEFAULT NULL::integer) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  v_modelo text := upper(btrim(coalesce(_modelo, 'IND')));
  v_ano text := to_char(coalesce(make_date(coalesce(_ano, extract(year from now())::int), 1, 1), now()::date), 'YYYY');
  v_prefixo text;
  v_seq int;
BEGIN
  IF v_modelo NOT IN ('IND','FAM','MULTI','PESQ','LEG','POS') THEN
    RAISE EXCEPTION 'Modelo de caso inválido: %. Permitidos: IND, FAM, MULTI, PESQ, LEG, POS.', _modelo;
  END IF;

  v_prefixo := CASE WHEN _demo THEN 'CA-DEMO-CID-' ELSE 'CA-CID-' END || v_modelo || '-' || v_ano || '-';

  -- serializa a geração por organização/modelo/ano dentro da transação
  PERFORM pg_advisory_xact_lock(hashtextextended(_org::text || v_prefixo, 0));

  SELECT coalesce(max((regexp_replace(codigo, '^' || v_prefixo, ''))::int), 0) + 1
    INTO v_seq
    FROM public.crm_casos
   WHERE organization_id = _org
     AND codigo ~ ('^' || v_prefixo || '\d+$');

  RETURN v_prefixo || lpad(v_seq::text, 3, '0');
END;
$_$;


--
-- Name: has_org_role(uuid, public.app_role); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.has_org_role(_org uuid, _role public.app_role) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select public.is_staff_ativo(_org) and exists (
    select 1 from public.user_roles r
    where r.organization_id = _org and r.user_id = auth.uid() and r.role = _role
  )
$$;


--
-- Name: is_org_member(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.is_org_member(_org uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select exists (
    select 1 from public.organization_members m
    where m.organization_id = _org and m.user_id = auth.uid() and m.archived_at is null
  )
  and exists (
    select 1 from public.staff_access s
    where s.organization_id = _org and s.auth_user_id = auth.uid()
      and s.status = 'active' and s.archived_at is null
  )
$$;


--
-- Name: is_staff_ativo(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.is_staff_ativo(_org uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select exists (
    select 1 from public.staff_access s
    where s.organization_id = _org
      and s.auth_user_id = auth.uid()
      and s.status = 'active'
      and s.archived_at is null
  )
$$;


--
-- Name: matriz_juridica_deduplicar(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.matriz_juridica_deduplicar(_org uuid) RETURNS TABLE(tema_codigo text, canonica_id uuid, arquivadas integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  r record;
  n integer;
BEGIN
  IF NOT public.can_write(_org) THEN
    RAISE EXCEPTION 'Sem permissão para consolidar a matriz jurídica desta organização.';
  END IF;

  FOR r IN
    SELECT m.tema_codigo AS tc,
           (SELECT id FROM public.legal_clause_matrix x
             WHERE x.organization_id = _org AND x.tema_codigo = m.tema_codigo AND x.archived_at IS NULL
             ORDER BY (x.decidido_em IS NOT NULL) DESC, x.decidido_em DESC NULLS LAST, x.updated_at DESC
             LIMIT 1) AS canonica
      FROM public.legal_clause_matrix m
     WHERE m.organization_id = _org AND m.archived_at IS NULL
     GROUP BY m.tema_codigo
    HAVING count(*) > 1
  LOOP
    UPDATE public.legal_clause_matrix d
       SET archived_at = now(),
           archive_motivo = 'Deduplicação ANA-E-01: linha substituída pela canônica do tema.',
           substituido_por_id = r.canonica,
           substituicao_motivo = 'Uma linha canônica por organização e tema.',
           updated_at = now()
     WHERE d.organization_id = _org AND d.tema_codigo = r.tc AND d.archived_at IS NULL AND d.id <> r.canonica;
    GET DIAGNOSTICS n = ROW_COUNT;

    INSERT INTO public.audit_logs (organization_id, entidade, entidade_id, acao, valores_anteriores, valores_posteriores)
    VALUES (_org, 'legal_clause_matrix', r.canonica, 'deduplicacao',
            jsonb_build_object('tema_codigo', r.tc),
            jsonb_build_object('arquivadas', n, 'canonica_id', r.canonica));

    tema_codigo := r.tc; canonica_id := r.canonica; arquivadas := n;
    RETURN NEXT;
  END LOOP;
END;
$$;


--
-- Name: nucleo_completude(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.nucleo_completude(_case uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  _n public.nucleos_familiares%ROWTYPE;
  _participantes_sem_papel int := 0;
  _participantes int := 0;
  _deps_sem_status int := 0;
  _deps int := 0;
  _itens jsonb := '[]'::jsonb;
BEGIN
  SELECT * INTO _n FROM public.nucleos_familiares
    WHERE case_id = _case AND archived_at IS NULL ORDER BY created_at LIMIT 1;

  IF _n.id IS NOT NULL THEN
    SELECT count(*), count(*) FILTER (WHERE coalesce(btrim(papel),'') = '')
      INTO _participantes, _participantes_sem_papel
      FROM public.nucleo_membros WHERE nucleo_id = _n.id AND archived_at IS NULL;
  END IF;

  SELECT count(*), count(*) FILTER (WHERE status_representacao IS NULL OR btrim(status_representacao) = '')
    INTO _deps, _deps_sem_status
    FROM public.case_dependents WHERE case_id = _case AND archived_at IS NULL;

  _itens := jsonb_build_array(
    jsonb_build_object('chave','nucleo_vinculado','rotulo','Núcleo familiar vinculado ao caso',
      'ok', _n.id IS NOT NULL,
      'motivo', CASE WHEN _n.id IS NULL THEN 'Nenhum núcleo familiar ativo vinculado a este caso.' ELSE NULL END),
    jsonb_build_object('chave','contratante','rotulo','Contratante identificada',
      'ok', coalesce(btrim(_n.contratante_nome),'') <> '',
      'motivo', CASE WHEN coalesce(btrim(_n.contratante_nome),'') = '' THEN 'Contratante do núcleo não identificada.' ELSE NULL END),
    jsonb_build_object('chave','participantes','rotulo','Participantes com papel definido',
      'ok', _participantes > 0 AND _participantes_sem_papel = 0,
      'motivo', CASE WHEN _participantes = 0 THEN 'Nenhum participante registrado no núcleo.'
                     WHEN _participantes_sem_papel > 0 THEN _participantes_sem_papel || ' participante(s) sem papel definido.'
                     ELSE NULL END),
    jsonb_build_object('chave','dependentes','rotulo','Dependentes com status de representação',
      'ok', _deps_sem_status = 0,
      'motivo', CASE WHEN _deps_sem_status > 0 THEN _deps_sem_status || ' dependente(s) sem status de representação.' ELSE NULL END),
    jsonb_build_object('chave','dossie_ambiente','rotulo','Dossiê-mãe, ambiente e nível de acesso',
      'ok', coalesce(btrim(_n.dossie_mae),'') <> '' AND coalesce(btrim(_n.ambiente),'') <> '' AND coalesce(btrim(_n.nivel_acesso),'') <> '',
      'motivo', CASE WHEN _n.id IS NULL THEN 'Sem núcleo para avaliar dossiê e ambiente.'
                     WHEN coalesce(btrim(_n.dossie_mae),'') = '' OR coalesce(btrim(_n.ambiente),'') = '' OR coalesce(btrim(_n.nivel_acesso),'') = ''
                       THEN 'Dossiê-mãe, ambiente ou nível de acesso não registrados.'
                     ELSE NULL END)
  );

  RETURN jsonb_build_object(
    'nucleo_id', _n.id,
    'itens', _itens,
    'completo', NOT EXISTS (SELECT 1 FROM jsonb_array_elements(_itens) i WHERE (i->>'ok')::boolean IS NOT TRUE)
  );
END;
$$;


--
-- Name: ops_painel(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ops_painel(_org uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v jsonb;
begin
  if not public.is_org_member(_org) then
    raise exception 'Sem acesso a esta organização.';
  end if;

  select jsonb_build_object(
    'casos_ativos', (select count(*) from public.crm_casos c where c.organization_id=_org and c.status='ativo' and c.archived_at is null),
    'casos_bloqueados', (select count(*) from public.crm_casos c where c.organization_id=_org and c.status in ('pausado','aguardando_documentos','aguardando_pagamento') and c.archived_at is null),
    'tarefas_vencidas', (select count(*) from public.tarefas t where t.organization_id=_org and t.archived_at is null and t.status not in ('concluida','cancelada') and t.sla_prazo_em is not null and now() > t.sla_prazo_em),
    'sla_em_risco', (select count(*) from public.tarefas t where t.organization_id=_org and t.archived_at is null and t.status not in ('concluida','cancelada') and t.sla_alerta_em is not null and now() between t.sla_alerta_em and t.sla_prazo_em),
    'tarefas_bloqueadas', (select count(*) from public.tarefas t where t.organization_id=_org and t.archived_at is null and t.status='bloqueada'),
    'micro_pendentes', (select count(*) from public.ops_microentregas m where m.organization_id=_org and m.archived_at is null and m.status not in ('concluida','cancelada')),
    'micro_atrasadas', (select count(*) from public.ops_microentregas m where m.organization_id=_org and m.archived_at is null and m.status not in ('concluida','cancelada') and m.prazo is not null and m.prazo < current_date),
    'carga', (
      select coalesce(jsonb_agg(x order by x->>'nome'), '[]'::jsonb) from (
        select jsonb_build_object(
          'responsavel_id', s.auth_user_id,
          'nome', coalesce(s.full_name, s.email),
          'tarefas_abertas', (select count(*) from public.tarefas t where t.organization_id=_org and t.archived_at is null and t.responsavel_id = s.auth_user_id and t.status not in ('concluida','cancelada')),
          'tarefas_atrasadas', (select count(*) from public.tarefas t where t.organization_id=_org and t.archived_at is null and t.responsavel_id = s.auth_user_id and t.status not in ('concluida','cancelada') and t.sla_prazo_em is not null and now() > t.sla_prazo_em),
          'micro_abertas', (select count(*) from public.ops_microentregas m where m.organization_id=_org and m.archived_at is null and m.responsavel_id = s.auth_user_id and m.status not in ('concluida','cancelada'))
        ) as x
        from public.staff_access s
        where s.organization_id=_org and s.status='active' and s.archived_at is null
      ) q
    )
  ) into v;

  return v;
end $$;


--
-- Name: ops_sla_status(text, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ops_sla_status(_status text, _prazo_em timestamp with time zone, _alerta_em timestamp with time zone) RETURNS text
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  select case
    when _status in ('concluida','cancelada') then 'concluido'
    when _prazo_em is null then 'sem_sla'
    when now() > _prazo_em then 'atrasada'
    when _alerta_em is not null and now() > _alerta_em then 'em_risco'
    else 'no_prazo' end
$$;


--
-- Name: pais_canonico(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pais_canonico(_valor text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $$
  SELECT CASE lower(btrim(coalesce(_valor,'')))
    WHEN '' THEN NULL
    WHEN 'austria' THEN 'Áustria'
    WHEN 'áustria' THEN 'Áustria'
    WHEN 'italia' THEN 'Itália'
    WHEN 'itália' THEN 'Itália'
    WHEN 'portugal' THEN 'Portugal'
    WHEN 'espanha' THEN 'Espanha'
    WHEN 'alemanha' THEN 'Alemanha'
    WHEN 'polonia' THEN 'Polônia'
    WHEN 'polônia' THEN 'Polônia'
    WHEN 'hungria' THEN 'Hungria'
    WHEN 'romenia' THEN 'Romênia'
    WHEN 'romênia' THEN 'Romênia'
    WHEN 'lituania' THEN 'Lituânia'
    WHEN 'lituânia' THEN 'Lituânia'
    ELSE initcap(btrim(_valor))
  END
$$;


--
-- Name: pode_iniciar_pesquisa_externa(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pode_iniciar_pesquisa_externa(_rc uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare rc record; c record; estado text; msg text; papel app_role; criticas int; pend int;
begin
  select * into rc from public.research_cases where id = _rc;
  if not found then
    return jsonb_build_object('permitido',false,'elegivel',false,'estado','blocked_by_case_status',
      'mensagem','Pesquisa externa bloqueada: caso não está elegível.');
  end if;
  select * into c from public.crm_casos where id = rc.case_id and organization_id = rc.organization_id;
  papel := public.staff_meu_papel(rc.organization_id);

  select count(*) into criticas from public.quality_issues q
   where q.organization_id = rc.organization_id and q.case_id = rc.case_id
     and q.severidade = 'critica' and q.status in ('aberta','reconhecida');
  select count(*) into pend from public.research_pending_items pi
   where pi.research_case_id = _rc and pi.severity = 'critical'
     and pi.status in ('open','in_progress','blocked') and pi.archived_at is null;

  if c is null or c.archived_at is not null or rc.archived_at is not null
     or c.status in ('pausado','encerrado','concluido','arquivado')
     or rc.status in ('paused','completed','archived') then
    estado := 'blocked_by_case_status'; msg := 'Pesquisa externa bloqueada: caso não está elegível.';
  elsif coalesce(c.contrato_assinado,false) is not true then
    estado := 'blocked_by_contract'; msg := 'Pesquisa externa bloqueada: contrato aplicável não assinado.';
  elsif coalesce(c.pagamento_confirmado,false) is not true then
    estado := 'blocked_by_financial_gate'; msg := 'Pesquisa externa bloqueada: condição financeira pendente.';
  elsif rc.external_research_authorization_status not in ('registered','not_applicable') then
    estado := 'pending_authorization'; msg := 'Pesquisa externa bloqueada: autorização aplicável pendente.';
  elsif criticas > 0 or pend > 0 then
    estado := 'blocked_by_quality'; msg := 'Pesquisa externa bloqueada: há inconsistência crítica aberta.';
  elsif rc.external_research_gate_status = 'released_by_authorized_user' then
    estado := 'released_by_authorized_user'; msg := 'Liberação humana registrada por usuário autorizado.';
  else
    estado := 'eligible_for_human_release';
    msg := 'Elegível para liberação humana; nenhuma ação externa foi executada.';
  end if;

  return jsonb_build_object(
    'permitido', estado = 'released_by_authorized_user',
    'elegivel', estado in ('eligible_for_human_release','released_by_authorized_user'),
    'estado', estado, 'mensagem', msg,
    'papel_autorizado', coalesce(papel in ('admin'::app_role,'operacoes'::app_role), false),
    'pendencias_criticas', pend, 'inconsistencias_criticas', criticas);
end $$;


--
-- Name: pode_pesquisar_caso(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pode_pesquisar_caso(_case uuid) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  _org uuid;
  _resp uuid;
BEGIN
  IF auth.uid() IS NULL THEN
    RETURN true; -- rotinas administrativas e carga inicial
  END IF;
  SELECT organization_id, responsavel_id INTO _org, _resp FROM public.crm_casos WHERE id = _case;
  IF _org IS NULL THEN
    RETURN false;
  END IF;
  IF has_org_role(_org, 'admin') OR has_org_role(_org, 'operacoes') THEN
    RETURN true;
  END IF;
  IF has_org_role(_org, 'pesquisador') THEN
    RETURN _resp = auth.uid();
  END IF;
  RETURN can_write(_org);
END;
$$;


--
-- Name: portal_caso_permitido(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.portal_caso_permitido(_case uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select exists (
    select 1
    from public.client_portal_access a
    join public.client_portal_case_access ca
      on ca.client_portal_access_id = a.id
     and ca.organization_id = a.organization_id
     and ca.access_status = 'active'
     and ca.revoked_at is null
    join public.crm_casos c
      on c.id = ca.case_id
     and c.organization_id = a.organization_id
    where a.auth_user_id = auth.uid()
      and a.archived_at is null
      and a.access_status = 'active'
      and a.access_level = 'client_workspace'
      and (a.invitation_expires_at is null or a.invitation_expires_at > now() or a.first_authenticated_at is not null)
      and ca.case_id = _case
      and c.cliente_id = a.client_id
      and c.archived_at is null
      and c.app_access_status = 'liberado'
      and c.app_visibility_level in ('workspace','completo')
      and c.consentimento_compartilhamento = true
      and c.info_cliente_liberada = true
  )
$$;


