--
-- Name: quality_relatorio_semanal(uuid, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.quality_relatorio_semanal(_org uuid, _inicio date DEFAULT NULL::date) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  ini timestamptz;
  fim timestamptz;
  out_json jsonb;
BEGIN
  IF NOT public.is_staff_ativo(_org) THEN
    RAISE EXCEPTION 'Acesso interno não autorizado.';
  END IF;
  ini := date_trunc('week', COALESCE(_inicio, current_date)::timestamptz);
  fim := ini + interval '7 days';

  SELECT jsonb_build_object(
    'inicio', ini,
    'fim', fim,
    'casos_ativos', (SELECT count(*) FROM crm_casos WHERE organization_id=_org AND archived_at IS NULL AND (status='ativo' OR ativo IS TRUE)),
    'casos_ativados_semana', (SELECT count(*) FROM crm_casos WHERE organization_id=_org AND ativado_em >= ini AND ativado_em < fim),
    'casos_suspensos', (SELECT count(*) FROM crm_casos WHERE organization_id=_org AND archived_at IS NULL AND status='suspenso'),
    'tarefas_concluidas_semana', (SELECT count(*) FROM tarefas WHERE organization_id=_org AND concluida_em >= ini AND concluida_em < fim),
    'tarefas_vencidas', (SELECT count(*) FROM tarefas WHERE organization_id=_org AND archived_at IS NULL AND prazo < current_date AND status NOT IN ('concluida','cancelada')),
    'microentregas_pendentes', (SELECT count(*) FROM microentregas m JOIN crm_casos c ON c.id=m.caso_id WHERE c.organization_id=_org AND m.status <> 'concluida'),
    'evidencias_validadas_semana', (SELECT count(*) FROM evidencias WHERE organization_id=_org AND status='validada' AND updated_at >= ini AND updated_at < fim),
    'faturas_emitidas_semana', (SELECT count(*) FROM invoices WHERE organization_id=_org AND emitida_em >= ini AND emitida_em < fim),
    'pagamentos_confirmados_semana', (SELECT count(*) FROM payments WHERE organization_id=_org AND status='confirmado' AND pago_em >= ini AND pago_em < fim),
    'valor_recebido_semana', (SELECT COALESCE(sum(valor),0) FROM payments WHERE organization_id=_org AND status='confirmado' AND pago_em >= ini AND pago_em < fim),
    'inconsistencias', (
      SELECT COALESCE(jsonb_object_agg(severidade, total), '{}'::jsonb) FROM (
        SELECT severidade, count(*) total FROM quality_issues
         WHERE organization_id=_org AND status IN ('aberta','reconhecida') GROUP BY severidade
      ) s),
    'inconsistencias_resolvidas_semana', (SELECT count(*) FROM quality_issues WHERE organization_id=_org AND resolvida_em >= ini AND resolvida_em < fim),
    'carga_por_responsavel', (
      SELECT COALESCE(jsonb_agg(jsonb_build_object('responsavel', nome, 'tarefas_abertas', total) ORDER BY total DESC), '[]'::jsonb)
      FROM (
        SELECT COALESCE(s.full_name, s.email, 'Sem responsável') nome, count(*) total
          FROM tarefas t LEFT JOIN staff_access s ON s.auth_user_id = t.responsavel_id
         WHERE t.organization_id=_org AND t.archived_at IS NULL AND t.status NOT IN ('concluida','cancelada')
         GROUP BY 1
      ) r)
  ) INTO out_json;

  RETURN out_json;
END; $$;


--
-- Name: quality_scan(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.quality_scan(_org uuid) RETURNS TABLE(criadas integer, sanadas integer, abertas integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_criadas integer := 0;
  v_sanadas integer := 0;
  v_abertas integer := 0;
BEGIN
  IF NOT public.is_staff_ativo(_org) THEN
    RAISE EXCEPTION 'Acesso interno não autorizado.';
  END IF;

  CREATE TEMP TABLE _achados (
    regra_key text, dominio text, severidade text, entidade text, entidade_id uuid,
    case_id uuid, titulo text, detalhe text
  ) ON COMMIT DROP;

  -- CRM / onboarding: caso ativo sem responsável (crítica)
  INSERT INTO _achados
  SELECT 'caso_sem_responsavel','crm','critica','caso',c.id,c.id,
         'Caso ativo sem responsável',
         'O caso '||c.codigo||' está ativo e não possui responsável designado.'
  FROM crm_casos c
  WHERE c.organization_id = _org AND c.archived_at IS NULL
    AND (c.status = 'ativo' OR c.ativo IS TRUE) AND c.responsavel_id IS NULL;

  -- Privacidade: caso ativo sem consentimento ativo (crítica)
  INSERT INTO _achados
  SELECT 'caso_sem_consentimento','privacidade','critica','caso',c.id,c.id,
         'Caso ativo sem consentimento ativo',
         'O caso '||c.codigo||' está ativo sem consentimento vigente nem exceção formal registrada.'
  FROM crm_casos c
  WHERE c.organization_id = _org AND c.archived_at IS NULL
    AND (c.status = 'ativo' OR c.ativo IS TRUE)
    AND NOT EXISTS (
      SELECT 1 FROM consent_records r
      WHERE r.organization_id = _org AND r.archived_at IS NULL
        AND r.status = 'ativo' AND r.revogado_em IS NULL
        AND (r.case_id = c.id OR (r.case_id IS NULL AND r.client_id = c.cliente_id))
    )
    AND NOT EXISTS (
      SELECT 1 FROM consent_exceptions e
      WHERE e.case_id = c.id AND e.archived_at IS NULL
    );

  -- Entrega: caso ativo sem ordem de serviço pronta ou em execução (alta)
  INSERT INTO _achados
  SELECT 'caso_sem_ordem_servico','entrega','alta','caso',c.id,c.id,
         'Caso ativo sem ordem de serviço pronta',
         'O caso '||c.codigo||' está ativo e não possui ordem de serviço pronta ou em execução.'
  FROM crm_casos c
  WHERE c.organization_id = _org AND c.archived_at IS NULL
    AND (c.status = 'ativo' OR c.ativo IS TRUE)
    AND NOT EXISTS (
      SELECT 1 FROM service_orders o
      WHERE o.case_id = c.id AND o.archived_at IS NULL
        AND o.status IN ('approved','active')
    );

  -- Contrato: caso ativo sem contrato assinado (crítica)
  INSERT INTO _achados
  SELECT 'caso_sem_contrato','contrato','critica','caso',c.id,c.id,
         'Caso ativo sem contrato assinado',
         'O caso '||c.codigo||' está ativo sem contrato assinado registrado.'
  FROM crm_casos c
  WHERE c.organization_id = _org AND c.archived_at IS NULL
    AND (c.status = 'ativo' OR c.ativo IS TRUE)
    AND COALESCE(c.contrato_assinado, false) = false;

  -- Pagamento divergente (alta)
  INSERT INTO _achados
  SELECT 'pagamento_divergente','pagamento','alta','pagamento',p.id,i.case_id,
         'Pagamento divergente',
         'Pagamento de '||COALESCE(p.valor::text,'valor não informado')||' está com conciliação divergente.'
  FROM payments p
  LEFT JOIN invoices i ON i.id = p.invoice_id
  WHERE p.organization_id = _org AND p.archived_at IS NULL
    AND p.conciliacao_status = 'divergente';

  INSERT INTO _achados
  SELECT 'fatura_divergente','pagamento','alta','fatura',i.id,i.case_id,
         'Fatura com conciliação divergente',
         'A fatura '||COALESCE(i.numero,'sem número')||' está com conciliação divergente.'
  FROM invoices i
  WHERE i.organization_id = _org AND i.archived_at IS NULL
    AND i.conciliacao_status = 'divergente';

  -- Evidência validada sem fonte (alta)
  INSERT INTO _achados
  SELECT 'evidencia_sem_fonte','evidencia','alta','evidencia',e.id,e.caso_id,
         'Evidência validada sem fonte',
         'A evidência "'||e.titulo||'" está marcada como validada sem fonte registrada.'
  FROM evidencias e
  WHERE e.organization_id = _org AND e.archived_at IS NULL
    AND e.status = 'validada'
    AND (e.fonte IS NULL OR length(btrim(e.fonte)) = 0);

  -- Tarefa vencida (média)
  INSERT INTO _achados
  SELECT 'tarefa_vencida','entrega','media','tarefa',t.id,t.caso_id,
         'Tarefa vencida',
         'A tarefa "'||t.titulo||'" venceu em '||to_char(t.prazo,'DD/MM/YYYY')||' e continua em aberto.'
  FROM tarefas t
  WHERE t.organization_id = _org AND t.archived_at IS NULL
    AND t.prazo IS NOT NULL AND t.prazo < current_date
    AND t.status NOT IN ('concluida','cancelada');

  -- Cliente com dado obrigatório ausente (média)
  INSERT INTO _achados
  SELECT 'cliente_dado_obrigatorio','crm','media','cliente',cl.id,NULL,
         'Cliente com dado obrigatório ausente',
         'Cliente '||cl.nome||' sem: '||array_to_string(ARRAY_REMOVE(ARRAY[
            CASE WHEN cl.email IS NULL OR length(btrim(cl.email))=0 THEN 'e-mail' END,
            CASE WHEN cl.telefone IS NULL OR length(btrim(cl.telefone))=0 THEN 'telefone' END,
            CASE WHEN cl.documento IS NULL OR length(btrim(cl.documento))=0 THEN 'documento' END
         ], NULL), ', ')||'.'
  FROM clientes cl
  WHERE cl.organization_id = _org AND cl.archived_at IS NULL
    AND (cl.email IS NULL OR length(btrim(cl.email))=0
      OR cl.telefone IS NULL OR length(btrim(cl.telefone))=0
      OR cl.documento IS NULL OR length(btrim(cl.documento))=0);

  -- Caso ativo sem próxima ação definida (baixa)
  INSERT INTO _achados
  SELECT 'caso_sem_proxima_acao','crm','baixa','caso',c.id,c.id,
         'Caso ativo sem próxima ação',
         'O caso '||c.codigo||' está ativo sem próxima ação registrada.'
  FROM crm_casos c
  WHERE c.organization_id = _org AND c.archived_at IS NULL
    AND (c.status = 'ativo' OR c.ativo IS TRUE)
    AND (c.proxima_acao IS NULL OR length(btrim(c.proxima_acao)) = 0);

  -- Checklist obrigatório pendente em caso ativo (baixa)
  INSERT INTO _achados
  SELECT DISTINCT 'checklist_pendente','entrega','baixa','caso',c.id,c.id,
         'Checklist obrigatório pendente',
         'O caso '||c.codigo||' possui itens obrigatórios de checklist ainda pendentes.'
  FROM crm_casos c
  JOIN case_checklist_items k ON k.case_id = c.id AND k.archived_at IS NULL
  WHERE c.organization_id = _org AND c.archived_at IS NULL
    AND (c.status = 'ativo' OR c.ativo IS TRUE)
    AND k.obrigatorio AND k.status = 'pendente';

  -- Grava / reabre
  INSERT INTO quality_issues AS q
    (organization_id, regra_key, dominio, severidade, entidade, entidade_id, case_id,
     titulo, detalhe, bloqueia_ativacao, exige_suspensao)
  SELECT _org, a.regra_key, a.dominio, a.severidade, a.entidade, a.entidade_id, a.case_id,
         a.titulo, a.detalhe,
         a.severidade = 'critica',
         a.severidade = 'critica' AND EXISTS (
           SELECT 1 FROM crm_casos c2
           WHERE c2.id = a.case_id AND (c2.status = 'ativo' OR c2.ativo IS TRUE)
         )
  FROM _achados a
  ON CONFLICT (organization_id, regra_key, entidade, entidade_id) DO UPDATE
    SET detalhe = EXCLUDED.detalhe,
        case_id = EXCLUDED.case_id,
        bloqueia_ativacao = EXCLUDED.bloqueia_ativacao,
        exige_suspensao = EXCLUDED.exige_suspensao,
        sanada_em = NULL,
        status = CASE WHEN q.status IN ('sanada','resolvida') THEN 'aberta' ELSE q.status END,
        detectada_em = CASE WHEN q.status IN ('sanada','resolvida') THEN now() ELSE q.detectada_em END,
        updated_at = now();
  GET DIAGNOSTICS v_criadas = ROW_COUNT;

  UPDATE quality_issues q
     SET status = 'sanada', sanada_em = now(), updated_at = now()
   WHERE q.organization_id = _org
     AND q.status IN ('aberta','reconhecida')
     AND NOT EXISTS (
       SELECT 1 FROM _achados a
       WHERE a.regra_key = q.regra_key AND a.entidade = q.entidade AND a.entidade_id = q.entidade_id
     );
  GET DIAGNOSTICS v_sanadas = ROW_COUNT;

  SELECT count(*) INTO v_abertas FROM quality_issues
   WHERE organization_id = _org AND status IN ('aberta','reconhecida');

  RETURN QUERY SELECT v_criadas, v_sanadas, v_abertas;
END; $$;


--
-- Name: quality_sync_checklist(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.quality_sync_checklist(_case uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_org uuid; v_tipo text; v_fase text; v_n integer := 0;
BEGIN
  SELECT organization_id, COALESCE(tipo_servico,'*'), COALESCE(fase,'*')
    INTO v_org, v_tipo, v_fase FROM crm_casos WHERE id = _case;
  IF v_org IS NULL THEN RAISE EXCEPTION 'Caso não encontrado.'; END IF;
  IF NOT public.is_staff_ativo(v_org) THEN RAISE EXCEPTION 'Acesso interno não autorizado.'; END IF;

  INSERT INTO case_checklist_items
    (organization_id, case_id, template_id, item_key, label, fase, tipo_servico, obrigatorio, ordem)
  SELECT v_org, _case, t.id, t.item_key, t.label, t.fase, t.tipo_servico, t.obrigatorio, t.ordem
    FROM quality_checklist_templates t
   WHERE t.organization_id = v_org AND t.archived_at IS NULL
     AND t.tipo_servico IN ('*', v_tipo)
     AND t.fase IN ('*', v_fase)
  ON CONFLICT (case_id, item_key) DO NOTHING;
  GET DIAGNOSTICS v_n = ROW_COUNT;
  RETURN v_n;
END; $$;


--
-- Name: research_quality_scan(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.research_quality_scan(_org uuid) RETURNS TABLE(criadas integer, sanadas integer, abertas integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_criadas int := 0; v_sanadas int := 0; v_abertas int := 0;
begin
  if not public.is_staff_ativo(_org) then raise exception 'Acesso interno não autorizado.'; end if;

  create temp table _rg_achados (
    regra_key text, dominio text, severidade text, entidade text, entidade_id uuid,
    case_id uuid, titulo text, detalhe text) on commit drop;

  insert into _rg_achados
  select 'rg_evidencia_validada_sem_fonte','pesquisa','critica','research_evidence_items',e.id,rc.case_id,
         'Evidência validada sem fonte, documento ou referência',
         'A evidência "'||e.title||'" está validada sem lastro documental.'
  from research_evidence_items e join research_cases rc on rc.id = e.research_case_id
  where e.organization_id = _org and e.archived_at is null and e.evidence_status='validated'
    and e.source_id is null and e.document_id is null and coalesce(btrim(e.external_reference),'')='';

  insert into _rg_achados
  select 'rg_sensivel_visivel','pesquisa','critica','research_evidence_items',e.id,rc.case_id,
         'Dado altamente restrito com visibilidade cliente-facing',
         'A evidência "'||e.title||'" é altamente restrita e não pode ser exposta.'
  from research_evidence_items e join research_cases rc on rc.id = e.research_case_id
  where e.organization_id = _org and e.archived_at is null
    and e.sensitivity_level='highly_restricted' and e.client_visibility <> 'never';

  insert into _rg_achados
  select 'rg_relacao_validada_sem_evidencia','pesquisa','alta','research_relationships',r.id,rc.case_id,
         'Relação validada sem evidência validada',
         'Relação validada sem evidência validada vinculada.'
  from research_relationships r join research_cases rc on rc.id = r.research_case_id
  where r.organization_id = _org and r.archived_at is null and r.status='validated'
    and not public.rg_tem_evidencia_validada('relationship', r.id);

  insert into _rg_achados
  select 'rg_evento_validado_sem_evidencia','pesquisa','alta','research_case_events',ev.id,rc.case_id,
         'Evento validado sem evidência validada',
         'Evento validado sem evidência validada vinculada.'
  from research_case_events ev join research_cases rc on rc.id = ev.research_case_id
  where ev.organization_id = _org and ev.archived_at is null and ev.status='validated'
    and not public.rg_tem_evidencia_validada('event', ev.id);

  insert into _rg_achados
  select 'rg_fonte_verificada_sem_revisao','pesquisa','alta','research_sources',s.id,rc.case_id,
         'Fonte externa verificada sem revisão registrada',
         'A fonte "'||s.title||'" está marcada como verificada sem revisor ou data.'
  from research_sources s left join research_cases rc on rc.id = s.research_case_id
  where s.organization_id = _org and s.archived_at is null and s.external_source
    and s.source_status='verified' and (s.reviewed_by is null or s.reviewed_at is null);

  insert into _rg_achados
  select 'rg_pesquisa_sem_responsavel','pesquisa','media','research_cases',rc.id,rc.case_id,
         'Pesquisa sem responsável designado','Defina um pesquisador responsável.'
  from research_cases rc
  where rc.organization_id = _org and rc.archived_at is null
    and rc.status not in ('not_started','completed','archived') and rc.assigned_researcher_user_id is null;

  insert into _rg_achados
  select 'rg_pendencia_vencida','pesquisa','media','research_pending_items',p.id,rc.case_id,
         'Pendência de pesquisa vencida','A pendência "'||p.title||'" passou do prazo.'
  from research_pending_items p join research_cases rc on rc.id = p.research_case_id
  where p.organization_id = _org and p.archived_at is null and p.due_at is not null
    and p.due_at < now() and p.status in ('open','in_progress','blocked');

  insert into _rg_achados
  select 'rg_pendencia_critica_aberta','pesquisa','critica','research_pending_items',p.id,rc.case_id,
         'Pendência crítica de pesquisa em aberto','A pendência "'||p.title||'" bloqueia a liberação externa.'
  from research_pending_items p join research_cases rc on rc.id = p.research_case_id
  where p.organization_id = _org and p.archived_at is null and p.severity='critical'
    and p.status in ('open','in_progress','blocked');

  insert into _rg_achados
  select 'rg_pesquisa_sem_proxima_acao','pesquisa','baixa','research_cases',rc.id,rc.case_id,
         'Pesquisa sem próxima ação definida','Registre a próxima ação de pesquisa.'
  from research_cases rc
  where rc.organization_id = _org and rc.archived_at is null
    and rc.status in ('preparation','internal_research','awaiting_documents','awaiting_review')
    and coalesce(btrim(rc.next_research_action),'') = '';

  insert into _rg_achados
  select 'rg_fonte_sem_citacao','pesquisa','baixa','research_sources',s.id,rc.case_id,
         'Fonte sem citação registrada','A fonte "'||s.title||'" não possui citação.'
  from research_sources s left join research_cases rc on rc.id = s.research_case_id
  where s.organization_id = _org and s.archived_at is null and coalesce(btrim(s.citation_text),'')='';

  insert into public.quality_issues (organization_id, regra_key, dominio, severidade, entidade, entidade_id, case_id, titulo, detalhe, bloqueia_ativacao)
  select _org, a.regra_key, a.dominio, a.severidade, a.entidade, a.entidade_id, a.case_id, a.titulo, a.detalhe, false
  from _rg_achados a
  on conflict (organization_id, regra_key, entidade, entidade_id) do update
    set status = case when quality_issues.status in ('resolvida','sanada','falso_positivo') then quality_issues.status else 'aberta' end,
        detalhe = excluded.detalhe, updated_at = now();
  get diagnostics v_criadas = row_count;

  update public.quality_issues q set status='sanada', sanada_em=now(), updated_at=now()
   where q.organization_id=_org and q.dominio='pesquisa' and q.status in ('aberta','reconhecida')
     and not exists (select 1 from _rg_achados a where a.regra_key=q.regra_key and a.entidade=q.entidade and a.entidade_id=q.entidade_id);
  get diagnostics v_sanadas = row_count;

  select count(*) into v_abertas from public.quality_issues q
   where q.organization_id=_org and q.dominio='pesquisa' and q.status in ('aberta','reconhecida');

  return query select v_criadas, v_sanadas, v_abertas;
end $$;


--
-- Name: resolver_case_canonico(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.resolver_case_canonico(_ref text) RETURNS TABLE(case_id uuid, codigo text, alias boolean)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT c.id, c.codigo, (upper(btrim(_ref)) <> upper(c.codigo)) AS alias
  FROM public.crm_casos c
  WHERE public.is_org_member(c.organization_id)
    AND c.archived_at IS NULL
    AND (
      upper(c.codigo) = upper(btrim(_ref))
      OR upper(btrim(_ref)) = ANY (SELECT upper(x) FROM unnest(c.codigos_legados) x)
    )
  LIMIT 1;
$$;


--
-- Name: rg_admin(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rg_admin(_org uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select public.is_staff_ativo(_org) and public.staff_meu_papel(_org) = 'admin'::app_role
$$;


--
-- Name: rg_editar(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rg_editar(_org uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select public.is_staff_ativo(_org)
     and public.staff_meu_papel(_org) = any (array['admin','operacoes','pesquisador']::app_role[])
$$;


--
-- Name: rg_ler_detalhe(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rg_ler_detalhe(_org uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select public.is_staff_ativo(_org)
     and public.staff_meu_papel(_org) = any (array['admin','operacoes','pesquisador','leitura']::app_role[])
$$;


--
-- Name: rg_ler_resumo(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rg_ler_resumo(_org uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select public.is_staff_ativo(_org)
     and public.staff_meu_papel(_org) = any (array['admin','operacoes','pesquisador','leitura','comercial']::app_role[])
$$;


--
-- Name: rg_papel(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rg_papel(_org uuid) RETURNS public.app_role
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select public.staff_meu_papel(_org)
$$;


--
-- Name: rg_pode_editar_caso(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rg_pode_editar_caso(_rc uuid) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare r record; p app_role;
begin
  select rc.organization_id, rc.assigned_researcher_user_id, rc.archived_at, c.responsavel_id
    into r from public.research_cases rc join public.crm_casos c on c.id = rc.case_id where rc.id = _rc;
  if not found then return false; end if;
  if not public.is_staff_ativo(r.organization_id) then return false; end if;
  p := public.staff_meu_papel(r.organization_id);
  if p in ('admin'::app_role,'operacoes'::app_role) then return true; end if;
  if p = 'pesquisador'::app_role then
    return coalesce(r.assigned_researcher_user_id = auth.uid(), false)
        or coalesce(r.responsavel_id = auth.uid(), false);
  end if;
  return false;
end $$;


--
-- Name: rg_tem_evidencia_validada(text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rg_tem_evidencia_validada(_tipo text, _id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select exists (
    select 1 from public.research_evidence_links l
    join public.research_evidence_items e on e.id = l.evidence_item_id
    where l.entity_type = _tipo and l.entity_id = _id and l.archived_at is null
      and l.link_role in ('supports','identifies','dates','locates')
      and e.evidence_status = 'validated' and e.archived_at is null)
$$;


--
-- Name: sku_preco_homologado(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sku_preco_homologado(_org uuid, _sku text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE r public.sku_catalog%ROWTYPE; e public.sku_price_exceptions%ROWTYPE;
BEGIN
  IF _sku IS NULL OR btrim(_sku) = '' THEN
    RETURN jsonb_build_object('ok', false, 'motivo', 'SKU não informado.');
  END IF;
  SELECT * INTO r FROM public.sku_catalog
   WHERE organization_id = _org AND sku = _sku AND ativo AND homologado AND archived_at IS NULL
     AND vigencia_inicio <= current_date AND (vigencia_fim IS NULL OR vigencia_fim >= current_date)
   ORDER BY vigencia_inicio DESC LIMIT 1;

  SELECT * INTO e FROM public.sku_price_exceptions
   WHERE organization_id = _org AND sku = _sku AND status = 'aprovada' AND archived_at IS NULL
     AND valido_ate >= current_date
   ORDER BY aprovado_em DESC NULLS LAST LIMIT 1;

  IF r.id IS NULL AND e.id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'motivo', 'SKU sem preço/condição homologados na Planilha Mestre.');
  END IF;
  IF r.id IS NOT NULL AND (r.preco_total IS NULL OR coalesce(btrim(r.condicao_pagamento),'') = '') AND e.id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'motivo', 'SKU homologado sem preço ou condição de pagamento completos.');
  END IF;
  RETURN jsonb_build_object(
    'ok', true,
    'fonte', CASE WHEN e.id IS NOT NULL THEN 'excecao_comercial_aprovada' ELSE 'planilha_mestre' END,
    'sku', _sku,
    'nome', r.nome,
    'moeda', coalesce(e.moeda, r.moeda),
    'preco_total', coalesce(e.preco_total, r.preco_total),
    'condicao_pagamento', coalesce(e.condicao_pagamento, r.condicao_pagamento),
    'parcelas', r.parcelas,
    'excecao_valida_ate', e.valido_ate
  );
END;
$$;


--
-- Name: staff_meu_papel(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.staff_meu_papel(_org uuid) RETURNS public.app_role
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select s.role from public.staff_access s
  where s.organization_id = _org and s.auth_user_id = auth.uid()
    and s.status = 'active' and s.archived_at is null
  limit 1
$$;


--
-- Name: transicao_permitida(text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.transicao_permitida(_entidade text, _de text, _para text) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $$
  select case
    when _de = _para then true
    when _entidade = 'lead' then _para = any (case _de
      when 'novo' then array['qualificado','perdido','arquivado']
      when 'qualificado' then array['proposta_em_preparo','perdido','arquivado']
      when 'proposta_em_preparo' then array['proposta_enviada','perdido','arquivado']
      when 'proposta_enviada' then array['ganho','perdido','arquivado']
      when 'ganho' then array['arquivado']
      when 'perdido' then array['novo','qualificado','arquivado']
      else array[]::text[] end)
    when _entidade = 'cliente' then _para = any (case _de
      when 'pre_onboarding' then array['ativo','encerrado','arquivado']
      when 'ativo' then array['suspenso','encerrado','arquivado']
      when 'suspenso' then array['ativo','encerrado','arquivado']
      when 'encerrado' then array['arquivado']
      else array[]::text[] end)
    when _entidade = 'caso' then _para = any (case _de
      when 'rascunho' then array['aguardando_documentos','aguardando_pagamento','encerrado','arquivado']
      when 'aguardando_documentos' then array['aguardando_pagamento','pronto_para_ativar','encerrado','arquivado']
      when 'aguardando_pagamento' then array['aguardando_documentos','pronto_para_ativar','encerrado','arquivado']
      when 'pronto_para_ativar' then array['ativo','aguardando_documentos','aguardando_pagamento','encerrado','arquivado']
      when 'ativo' then array['pausado','concluido','encerrado','arquivado']
      when 'pausado' then array['ativo','encerrado','arquivado']
      when 'concluido' then array['encerrado','arquivado']
      when 'encerrado' then array['arquivado']
      else array[]::text[] end)
    when _entidade = 'tarefa' then _para = any (case _de
      when 'nao_iniciada' then array['em_andamento','bloqueada','cancelada']
      when 'em_andamento' then array['bloqueada','concluida','cancelada']
      when 'bloqueada' then array['em_andamento','cancelada']
      when 'cancelada' then array['nao_iniciada']
      else array[]::text[] end)
    when _entidade = 'evidencia' then _para = any (case _de
      when 'coletada' then array['em_revisao','descartada']
      when 'em_revisao' then array['validada','inconclusiva','descartada','coletada']
      when 'validada' then array['em_revisao','descartada']
      when 'inconclusiva' then array['em_revisao','descartada']
      else array[]::text[] end)
    else false end
$$;


--
-- Name: unaccent_imutavel(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.unaccent_imutavel(_t text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $_$
  SELECT translate($1,
    'áàâãäéèêëíìîïóòôõöúùûüçÁÀÂÃÄÉÈÊËÍÌÎÏÓÒÔÕÖÚÙÛÜÇ',
    'aaaaaeeeeiiiiooooouuuucAAAAAEEEEIIIIOOOOOUUUUC')
$_$;


