--
-- Name: portal_casos; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.portal_casos WITH (security_barrier='true', security_invoker='true') AS
 SELECT id,
    organization_id,
    cliente_id,
    codigo,
    titulo,
    pais,
    via,
    status,
    ativo,
    suspenso_em,
    app_access_status,
    created_at,
    updated_at
   FROM public.crm_casos c
  WHERE ((archived_at IS NULL) AND public.portal_caso_permitido(id));


