);


--
-- Name: portal_meu_cadastro; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.portal_meu_cadastro WITH (security_barrier='true', security_invoker='true') AS
 SELECT id,
    organization_id,
    nome,
    nome_social,
    email,
    telefone,
    pais_interesse,
    status
   FROM public.clientes cl
  WHERE ((archived_at IS NULL) AND (id = public.portal_meu_cliente()) AND (organization_id = public.portal_minha_org()));


--
-- Name: portal_projecoes; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.portal_projecoes WITH (security_barrier='true', security_invoker='true') AS
 SELECT id,
    case_id,
    projection_type,
    content_sanitized,
    effective_from,
    updated_at
   FROM public.app_projections p
  WHERE ((destination = 'app'::text) AND (approval_status = 'published'::text) AND (archived_at IS NULL) AND (effective_from IS NOT NULL) AND (effective_from <= now()));


