--
-- Name: v_ops_microentregas; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_ops_microentregas WITH (security_invoker='on') AS
 SELECT m.id,
    m.organization_id,
    m.caso_id,
    m.fase,
    m.titulo,
    m.descricao,
    m.responsavel_id,
    m.prazo,
    m.prioridade,
    m.status,
    m.criterio_aceite,
    m.evidencia_url,
    m.evidencia_descricao,
    m.justificativa_sem_evidencia,
    m.concluida_em,
    m.concluida_por,
    m.excecao_id,
    m.archived_at,
    m.archived_by,
    m.archive_motivo,
    m.created_by,
    m.updated_by,
    m.created_at,
    m.updated_at,
        CASE
            WHEN (m.status = ANY (ARRAY['concluida'::text, 'cancelada'::text])) THEN 'concluido'::text
            WHEN (m.prazo IS NULL) THEN 'sem_prazo'::text
            WHEN (m.prazo < CURRENT_DATE) THEN 'atrasada'::text
            WHEN (m.prazo <= (CURRENT_DATE + 3)) THEN 'em_risco'::text
            ELSE 'no_prazo'::text
        END AS prazo_status,
    c.codigo AS caso_codigo,
    c.titulo AS caso_titulo,
    c.status AS caso_status
   FROM (public.ops_microentregas m
     LEFT JOIN public.crm_casos c ON ((c.id = m.caso_id)));


--
-- Name: v_ops_tarefas; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_ops_tarefas WITH (security_invoker='on') AS
 SELECT t.id,
    t.organization_id,
    t.caso_id,
    t.titulo,
    t.descricao,
    t.responsavel_id,
    t.prioridade,
    t.status,
    t.prazo,
    t.concluida_em,
    t.demo,
    t.archived_at,
    t.archived_by,
    t.archive_motivo,
    t.created_by,
    t.created_at,
    t.updated_at,
    t.updated_by,
    t.bloqueio,
    t.motivo_bloqueio,
    t.person_id,
    t.evidencia_id,
    t.hypothesis_id,
    t.tipo,
    t.bloqueado_em,
    t.desbloqueado_em,
    t.desbloqueio_por,
    t.desbloqueio_justificativa,
    t.sla_horas,
    t.sla_prazo_em,
    t.sla_alerta_em,
    public.ops_sla_status(t.status, t.sla_prazo_em, t.sla_alerta_em) AS sla_status,
    c.codigo AS caso_codigo,
    c.titulo AS caso_titulo,
    c.status AS caso_status
   FROM (public.tarefas t
     LEFT JOIN public.crm_casos c ON ((c.id = t.caso_id)));


