--
-- Name: owner_override_events Organizacao le suas decisoes de proprietaria; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY "Organizacao le suas decisoes de proprietaria" ON public.owner_override_events FOR SELECT TO authenticated USING ((organization_id IN ( SELECT om.organization_id
   FROM public.organization_members om
  WHERE ((om.user_id = auth.uid()) AND (om.archived_at IS NULL)))));


--
-- Name: owner_override_events Somente admin registra decisao de proprietaria; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY "Somente admin registra decisao de proprietaria" ON public.owner_override_events FOR INSERT TO authenticated WITH CHECK (((actor_user_id = auth.uid()) AND public.has_org_role(organization_id, 'admin'::public.app_role)));


--
-- Name: invoice_adjustments adjust_insert; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY adjust_insert ON public.invoice_adjustments FOR INSERT TO authenticated WITH CHECK (public.can_write_financeiro(organization_id));


--
-- Name: invoice_adjustments adjust_select; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY adjust_select ON public.invoice_adjustments FOR SELECT TO authenticated USING (public.is_org_member(organization_id));


--
-- Name: invoice_adjustments adjust_update; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY adjust_update ON public.invoice_adjustments FOR UPDATE TO authenticated USING (public.can_write_financeiro(organization_id)) WITH CHECK (public.can_write_financeiro(organization_id));


--
-- Name: app_projections app_proj_insert; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY app_proj_insert ON public.app_projections FOR INSERT TO authenticated WITH CHECK (public.can_write(organization_id));


--
-- Name: app_projections app_proj_select; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY app_proj_select ON public.app_projections FOR SELECT TO authenticated USING (public.is_org_member(organization_id));


--
-- Name: app_projections app_proj_select_portal; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY app_proj_select_portal ON public.app_projections FOR SELECT TO authenticated USING (((destination = 'app'::text) AND (approval_status = 'published'::text) AND (archived_at IS NULL) AND (effective_from IS NOT NULL) AND (effective_from <= now()) AND (visibility_scope = ANY (ARRAY['titular'::text, 'nucleo'::text])) AND public.portal_caso_permitido(case_id)));


--
-- Name: app_projections app_proj_update; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY app_proj_update ON public.app_projections FOR UPDATE TO authenticated USING (public.can_write(organization_id)) WITH CHECK (public.can_write(organization_id));


--
-- Name: app_projections; Type: ROW SECURITY; Schema: public; Owner: -
--

ALTER TABLE public.app_projections ENABLE ROW LEVEL SECURITY;

--
-- Name: artifact_register artifact_insert; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY artifact_insert ON public.artifact_register FOR INSERT TO authenticated WITH CHECK ((public.is_staff_ativo(organization_id) AND (public.staff_meu_papel(organization_id) <> 'leitura'::public.app_role)));


--
-- Name: artifact_register; Type: ROW SECURITY; Schema: public; Owner: -
--

ALTER TABLE public.artifact_register ENABLE ROW LEVEL SECURITY;

--
-- Name: artifact_register artifact_select; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY artifact_select ON public.artifact_register FOR SELECT TO authenticated USING ((public.is_staff_ativo(organization_id) AND ((nivel_acesso <> 'interno_restrito'::text) OR (public.staff_meu_papel(organization_id) = ANY (ARRAY['admin'::public.app_role, 'operacoes'::public.app_role])))));


--
